INSERT INTO lp_resources (slug, kind, perspective, audience, urgency, evidence_level, emoji, title, summary, body, sections, reading_minutes, min_day, max_day, countries, sex, tags, is_featured, review_status, sort_order) VALUES
  ('isl-duas-for-righteous-children', 'article', 'islamic', 'shared', 'educational', 'religious', '🤲', '{"en":"Duas from the Quran for righteous children","bn":"নেক সন্তানের জন্য কুরআনের দোয়া"}'::jsonb, '{"en":"Three short duas that prophets and believers made for good children, with Arabic, transliteration and meaning, to learn together as a couple.","bn":"নবী ও মুমিনরা নেক সন্তানের জন্য যে তিনটি ছোট দোয়া করেছেন — আরবি, উচ্চারণ ও অর্থসহ, স্বামী-স্ত্রী একসাথে শেখার জন্য।"}'::jsonb, '{"en":"Long before a child is born, the prophets turned to Allah and asked for good children. Their words are short, beautiful and easy to learn together as a couple, whether you are planning a family or already expecting.\n\n## The dua of Ibrahim (peace be upon him)\n\nرَبِّ اجْعَلْنِي مُقِيمَ الصَّلَاةِ وَمِن ذُرِّيَّتِي ۚ رَبَّنَا وَتَقَبَّلْ دُعَاءِ\n\n**Rabbij''alni muqimas-salati wa min dhurriyyati, Rabbana wa taqabbal du''a.**\n\nMeaning: My Lord, make me one who keeps up the prayer, and from my descendants too. Our Lord, accept my prayer. (Surah Ibrahim 14:40)\n\nIbrahim asks for himself first, then for his children. Children learn salah most easily from parents who pray.\n\n## The dua of the servants of the Most Merciful\n\nرَبَّنَا هَبْ لَنَا مِنْ أَزْوَاجِنَا وَذُرِّيَّاتِنَا قُرَّةَ أَعْيُنٍ وَاجْعَلْنَا لِلْمُتَّقِينَ إِمَامًا\n\n**Rabbana hab lana min azwajina wa dhurriyyatina qurrata a''yunin waj''alna lil-muttaqina imama.**\n\nMeaning: Our Lord, grant us from our spouses and our children the coolness of our eyes, and make us an example for those who are mindful of You. (Surah Al-Furqan 25:74)\n\nThis dua asks for joy in the whole family: husband, wife and children together.\n\n## The dua of Zakariyya (peace be upon him)\n\nرَبِّ هَبْ لِي مِن لَّدُنكَ ذُرِّيَّةً طَيِّبَةً ۖ إِنَّكَ سَمِيعُ الدُّعَاءِ\n\n**Rabbi hab li min ladunka dhurriyyatan tayyibah, innaka sami''ud-du''a.**\n\nMeaning: My Lord, grant me from Yourself good offspring. Surely You hear every prayer. (Surah Al Imran 3:38)\n\nZakariyya was old and his wife had not had children, yet he kept asking with hope, and Allah gave him the good news of Yahya (Surah Maryam 19:7).\n\n## Making these duas part of your life\n\n- Learn one dua a week together. The husband can lead it after a prayer and the wife can say amin, or the other way round.\n- You may also make dua in Bangla or any language. Allah understands every heart.\n- Keep asking whether a baby comes quickly, slowly or not yet. Waiting is not a sign that Allah has forgotten you.\n- If you are finding it hard to conceive, keep making dua and also see a doctor. Taking the means is part of trusting Allah.","bn":"সন্তান জন্মের অনেক আগেই নবীগণ আল্লাহর কাছে নেক সন্তান চেয়েছেন। তাঁদের দোয়াগুলো ছোট, সুন্দর এবং স্বামী-স্ত্রী মিলে সহজেই শেখা যায় — আপনি পরিবার পরিকল্পনা করছেন বা ইতিমধ্যে সন্তানের অপেক্ষায় আছেন, দুই অবস্থাতেই।\n\n## ইবরাহিম (আ.)-এর দোয়া\n\nرَبِّ اجْعَلْنِي مُقِيمَ الصَّلَاةِ وَمِن ذُرِّيَّتِي ۚ رَبَّنَا وَتَقَبَّلْ دُعَاءِ\n\n**উচ্চারণ: রব্বিজ আলনি মুকিমাস সালাতি ওয়া মিন যুররিয়্যাতি, রব্বানা ওয়া তাকাব্বাল দুআ।**\n\nঅর্থ: হে আমার রব, আমাকে নামাজ কায়েমকারী বানান এবং আমার বংশধরদের মধ্য থেকেও। হে আমাদের রব, আমার দোয়া কবুল করুন। (সূরা ইবরাহিম ১৪:৪০)\n\nলক্ষ করুন, ইবরাহিম (আ.) আগে নিজের জন্য চেয়েছেন, তারপর সন্তানের জন্য। যে বাবা-মা নিজেরা নামাজ পড়েন, সন্তান তাঁদের দেখেই সবচেয়ে সহজে নামাজ শেখে।\n\n## রহমানের বান্দাদের দোয়া\n\nرَبَّنَا هَبْ لَنَا مِنْ أَزْوَاجِنَا وَذُرِّيَّاتِنَا قُرَّةَ أَعْيُنٍ وَاجْعَلْنَا لِلْمُتَّقِينَ إِمَامًا\n\n**উচ্চারণ: রব্বানা হাব লানা মিন আযওয়াজিনা ওয়া যুররিয়্যাতিনা কুররাতা আ''ইউনিউ ওয়াজ''আলনা লিলমুত্তাকিনা ইমামা।**\n\nঅর্থ: হে আমাদের রব, আমাদের স্ত্রী-স্বামী ও সন্তানদের আমাদের চোখের শীতলতা বানিয়ে দিন এবং আমাদের মুত্তাকিদের জন্য আদর্শ বানান। (সূরা আল-ফুরকান ২৫:৭৪)\n\nএই দোয়ায় পুরো পরিবারের আনন্দ চাওয়া হয় — স্বামী, স্ত্রী ও সন্তান সবাই মিলে।\n\n## জাকারিয়া (আ.)-এর দোয়া\n\nرَبِّ هَبْ لِي مِن لَّدُنكَ ذُرِّيَّةً طَيِّبَةً ۖ إِنَّكَ سَمِيعُ الدُّعَاءِ\n\n**উচ্চারণ: রব্বি হাব লি মিল্লাদুনকা যুররিয়্যাতান তাইয়্যিবাহ, ইন্নাকা সামিউদ দুআ।**\n\nঅর্থ: হে আমার রব, আপনার পক্ষ থেকে আমাকে পবিত্র সন্তান দান করুন। নিশ্চয়ই আপনি দোয়া শোনেন। (সূরা আলে ইমরান ৩:৩৮)\n\nজাকারিয়া (আ.) বৃদ্ধ ছিলেন, তাঁর স্ত্রীর সন্তান হয়নি, তবু তিনি আশা নিয়ে চাইতে থাকেন। আল্লাহ তাঁকে ইয়াহইয়া (আ.)-এর সুসংবাদ দেন (সূরা মারইয়াম ১৯:৭)।\n\n## দোয়াগুলোকে জীবনের অংশ করুন\n\n- প্রতি সপ্তাহে একসাথে একটি দোয়া শিখুন। নামাজের পর স্বামী দোয়া পড়তে পারেন, স্ত্রী আমিন বলবেন — বা উল্টোটাও।\n- বাংলায় বা যেকোনো ভাষায়ও দোয়া করা যায়। আল্লাহ সব মনের কথা বোঝেন।\n- সন্তান তাড়াতাড়ি আসুক, দেরিতে আসুক বা এখনও না আসুক — চাইতে থাকুন। অপেক্ষা মানে এই নয় যে আল্লাহ আপনাকে ভুলে গেছেন।\n- গর্ভধারণে দেরি হলে দোয়ার পাশাপাশি ডাক্তারের কাছেও যান। উপায় অবলম্বন করাও আল্লাহর ওপর ভরসারই অংশ।"}'::jsonb, '{}'::jsonb, 4, NULL, 0, '{}'::text[], 'any', ARRAY['dua', 'righteous children', 'planning', 'pregnancy', 'quran']::text[], false, 'in_review'::lp_review_status, 9001),
  ('isl-children-amanah-gift', 'article', 'islamic', 'shared', 'educational', 'religious', '🎁', '{"en":"Children: a gift from Allah and a trust (amanah)","bn":"সন্তান: আল্লাহর দান ও আমানত"}'::jsonb, '{"en":"In Islam a child is a gift we did not earn and a trust we will be asked about. Seeing it this way brings both gratitude and gentle responsibility.","bn":"ইসলামে সন্তান এমন এক দান যা আমরা অর্জন করিনি, আবার এমন এক আমানত যার ব্যাপারে আমাদের জিজ্ঞেস করা হবে। এভাবে দেখলে মনে কৃতজ্ঞতা ও কোমল দায়িত্ববোধ দুটোই আসে।"}'::jsonb, '{"en":"Before a baby arrives, it helps to ask: what is a child, in the eyes of Islam? The Quran gives two answers that belong together: a gift and a trust.\n\n## A gift from Allah\n\nAllah says that to Him belongs the dominion of the heavens and the earth. He gives daughters to whom He wills and sons to whom He wills, or gives both, and leaves whom He wills without children (Surah Ash-Shura 42:49–50). In this verse daughters are mentioned first.\n\nA child is not something we produce by our own effort. Every child, girl or boy, is a gift to be received with thanks. The Quran criticises those who once felt ashamed at the news of a daughter (Surah An-Nahl 16:58–59), and the Prophet ﷺ said that whoever raises two girls with care until they grow up will be close to him on the Day of Resurrection (Sahih Muslim).\n\n## A trust (amanah)\n\nThe Prophet ﷺ said that every one of us is a shepherd and responsible for those in our care (Sahih al-Bukhari and Sahih Muslim). He also said that every child is born upon the fitrah, the natural goodness Allah placed in people (Sahih al-Bukhari and Sahih Muslim). Our job is to protect that goodness, not to force it.\n\nThe Quran calls wealth and children an adornment of this life (Surah Al-Kahf 18:46) and also a test (Surah At-Taghabun 64:15). A test here is not a threat. It is a chance to grow in patience, mercy and sincerity.\n\n## A lasting reward\n\nThe Prophet ﷺ said that when a person dies their deeds end, except three: ongoing charity, useful knowledge, and a righteous child who prays for them (Sahih Muslim). Raising a child with love is work that can keep bringing reward long after us.\n\n## Preparing now\n\n- Work on your own salah and character first. Children copy what they see.\n- Talk as a couple about the values you want at home: honesty, kindness, prayer, respect.\n- Plan to earn and spend in halal ways. Providing for the family is worship for the father and the mother who works.\n- If children have not come, remember that this is Allah''s wisdom, not a punishment. Some of the best people in history had no children. Caring for an orphan is also a great door: the Prophet ﷺ said the one who looks after an orphan will be with him in Paradise like two fingers held together (Sahih al-Bukhari).","bn":"শিশু আসার আগে একটু ভাবা ভালো: ইসলামের চোখে সন্তান আসলে কী? কুরআন দুটি উত্তর দেয়, যা একসাথে চলে — সন্তান একটি দান, আবার একটি আমানত।\n\n## আল্লাহর দান\n\nআল্লাহ বলেন, আসমান ও জমিনের রাজত্ব তাঁরই। তিনি যাকে ইচ্ছা কন্যা দেন, যাকে ইচ্ছা পুত্র দেন, অথবা দুটোই দেন, আর যাকে ইচ্ছা নিঃসন্তান রাখেন (সূরা আশ-শুরা ৪২:৪৯–৫০)। এই আয়াতে কন্যার কথা আগে এসেছে।\n\nসন্তান আমাদের নিজের চেষ্টায় বানানো কিছু নয়। মেয়ে হোক বা ছেলে, প্রতিটি সন্তান কৃতজ্ঞতার সাথে গ্রহণ করার মতো দান। জাহিলি যুগে কন্যাসন্তানের খবরে যারা লজ্জা পেত, কুরআন তাদের নিন্দা করেছে (সূরা আন-নাহল ১৬:৫৮–৫৯)। আর রাসূলুল্লাহ ﷺ বলেছেন, যে দুটি মেয়েকে যত্নে বড় করে, কিয়ামতের দিন সে তাঁর খুব কাছে থাকবে (সহিহ মুসলিম)।\n\n## একটি আমানত\n\nরাসূলুল্লাহ ﷺ বলেছেন, তোমরা প্রত্যেকেই দায়িত্বশীল এবং প্রত্যেককে তার অধীনস্থদের ব্যাপারে জিজ্ঞেস করা হবে (সহিহ বুখারি ও সহিহ মুসলিম)। তিনি আরও বলেছেন, প্রতিটি শিশু ফিতরাতের ওপর জন্ম নেয় — অর্থাৎ আল্লাহ মানুষের ভেতরে যে স্বাভাবিক ভালোত্ব দিয়েছেন তার ওপর (সহিহ বুখারি ও সহিহ মুসলিম)। আমাদের কাজ সেই ভালোত্বকে রক্ষা করা, জোর করে চাপিয়ে দেওয়া নয়।\n\nকুরআন সম্পদ ও সন্তানকে দুনিয়ার জীবনের শোভা বলেছে (সূরা আল-কাহফ ১৮:৪৬), আবার পরীক্ষাও বলেছে (সূরা আত-তাগাবুন ৬৪:১৫)। এখানে পরীক্ষা মানে ভয় দেখানো নয়; এটি ধৈর্য, দয়া ও আন্তরিকতায় বেড়ে ওঠার সুযোগ।\n\n## স্থায়ী সওয়াব\n\nরাসূলুল্লাহ ﷺ বলেছেন, মানুষ মারা গেলে তার আমল বন্ধ হয়ে যায়, তিনটি ছাড়া: সদকায়ে জারিয়া, উপকারী জ্ঞান এবং নেক সন্তান যে তার জন্য দোয়া করে (সহিহ মুসলিম)। ভালোবাসা দিয়ে সন্তান মানুষ করা এমন কাজ, যার সওয়াব আমাদের পরেও চলতে পারে।\n\n## এখনই প্রস্তুতি\n\n- আগে নিজের নামাজ ও আচরণের যত্ন নিন। সন্তান যা দেখে, তা-ই শেখে।\n- স্বামী-স্ত্রী মিলে ঠিক করুন ঘরে কোন মূল্যবোধ রাখবেন: সততা, দয়া, নামাজ, সম্মান।\n- হালাল উপায়ে আয় ও ব্যয়ের পরিকল্পনা করুন। পরিবারের জন্য উপার্জন বাবার জন্য এবং কর্মজীবী মায়ের জন্যও ইবাদত।\n- সন্তান না এলে মনে রাখুন, এটি আল্লাহর হিকমত, শাস্তি নয়। ইতিহাসের অনেক শ্রেষ্ঠ মানুষ নিঃসন্তান ছিলেন। এতিমের দেখাশোনাও এক বড় দরজা: রাসূলুল্লাহ ﷺ বলেছেন, এতিমের দায়িত্ব যে নেয়, সে জান্নাতে তাঁর সাথে পাশাপাশি দুই আঙুলের মতো থাকবে (সহিহ বুখারি)।"}'::jsonb, '{}'::jsonb, 4, NULL, 0, '{}'::text[], 'any', ARRAY['amanah', 'trust', 'gift', 'daughters', 'fitrah', 'planning']::text[], false, 'in_review'::lp_review_status, 9002),
  ('isl-status-of-mother', 'article', 'islamic', 'shared', 'educational', 'religious', '🌷', '{"en":"The honour of the mother in Islam","bn":"ইসলামে মায়ের মর্যাদা"}'::jsonb, '{"en":"The Quran names the effort of pregnancy, birth and nursing, and the Prophet ﷺ placed the mother first three times. What this means for the whole family now.","bn":"কুরআন গর্ভধারণ, প্রসব ও দুধ খাওয়ানোর কষ্টের কথা আলাদা করে বলেছে, আর রাসূলুল্লাহ ﷺ তিনবার মায়ের কথা আগে বলেছেন। পুরো পরিবারের জন্য এর অর্থ কী।"}'::jsonb, '{"en":"Islam does not take a mother''s effort for granted. The Quran describes it in detail, and the Prophet ﷺ taught people to honour it.\n\n## What the Quran says\n\nAllah says that He has instructed every person to be good to their parents. Their mother carried them, weakness upon weakness, and weaning takes two years. Then He says: be grateful to Me and to your parents (Surah Luqman 31:14).\n\nIn another place: their mother carried them with hardship and gave birth to them with hardship, and the carrying and weaning together are thirty months (Surah Al-Ahqaf 46:15). The same verse teaches a dua for a grown child to thank Allah for the blessings given to them and to their parents.\n\nThese verses name the tiredness, the heavy months and the pain of birth. Allah sees all of it.\n\n## Your mother, your mother, your mother\n\nA man asked the Prophet ﷺ who most deserved his good company. He said: your mother. The man asked: then who? He said: your mother. Then who? Your mother. Then who? Your father (Sahih al-Bukhari and Sahih Muslim).\n\n## What this means for the father\n\nHonouring mothers is not only a lesson for children one day. It begins now, with the husband.\n\n- The Prophet ﷺ said: the best of you are those who are best to their families, and I am the best of you to my family (Jami'' at-Tirmidhi).\n- ''A''ishah was asked what he did at home. She said he helped with the work of his family and went out when it was time for prayer (Sahih al-Bukhari).\n- Carry the heavy bags, take over chores, go with her to check-ups, and let her rest without guilt.\n- Speak gently, especially when she is tired or emotional.\n\n## What this means for the family\n\n- In-laws and relatives can honour her by easing her load, not by adding duties or comparing her with others.\n- If the mother is working outside the home, sharing the housework is part of honouring her.\n- A single mother carries both roles. The family and community should support her, not judge her.\n\nWhen children grow up seeing their father respect their mother, they learn the meaning of these verses without a lecture.","bn":"ইসলাম মায়ের কষ্টকে সাধারণ কিছু মনে করে না। কুরআন তা বিস্তারিত বলেছে, আর রাসূলুল্লাহ ﷺ মানুষকে তা সম্মান করতে শিখিয়েছেন।\n\n## কুরআন কী বলে\n\nআল্লাহ বলেন, তিনি মানুষকে বাবা-মায়ের প্রতি সদ্ব্যবহারের নির্দেশ দিয়েছেন। মা তাকে কষ্টের ওপর কষ্ট সহ্য করে গর্ভে ধারণ করেছেন, আর দুধ ছাড়ানো হয় দুই বছরে। তারপর বলেন: আমার প্রতি ও তোমার বাবা-মায়ের প্রতি কৃতজ্ঞ হও (সূরা লুকমান ৩১:১৪)।\n\nআরেক জায়গায় বলেন: মা তাকে কষ্ট করে গর্ভে ধারণ করেছেন এবং কষ্ট করে প্রসব করেছেন, আর গর্ভধারণ ও দুধ ছাড়ানো মিলে ত্রিশ মাস (সূরা আল-আহকাফ ৪৬:১৫)। একই আয়াতে বড় হওয়া সন্তানের জন্য একটি দোয়াও আছে — নিজের ও বাবা-মায়ের ওপর আল্লাহর নিয়ামতের শুকরিয়া আদায়ের দোয়া।\n\nএই আয়াতগুলো ক্লান্তি, ভারী মাসগুলো আর প্রসবের ব্যথার কথা নাম ধরে বলে। আল্লাহ সবকিছু দেখেন।\n\n## তোমার মা, তোমার মা, তোমার মা\n\nএক ব্যক্তি রাসূলুল্লাহ ﷺ-কে জিজ্ঞেস করল, আমার সদ্ব্যবহার পাওয়ার সবচেয়ে বেশি হকদার কে? তিনি বললেন: তোমার মা। সে বলল: তারপর কে? তিনি বললেন: তোমার মা। তারপর কে? তোমার মা। তারপর কে? তোমার বাবা (সহিহ বুখারি ও সহিহ মুসলিম)।\n\n## বাবার জন্য এর অর্থ\n\nমায়ের সম্মান শুধু একদিন সন্তানকে শেখানোর বিষয় নয়। এটি এখনই শুরু হয় — স্বামীর কাছ থেকে।\n\n- রাসূলুল্লাহ ﷺ বলেছেন: তোমাদের মধ্যে সেই উত্তম, যে তার পরিবারের কাছে উত্তম, আর আমি আমার পরিবারের কাছে তোমাদের সবার চেয়ে উত্তম (জামে তিরমিজি)।\n- আয়েশা (রা.)-কে জিজ্ঞেস করা হয়েছিল, তিনি ঘরে কী করতেন। তিনি বলেছেন, তিনি পরিবারের কাজে সাহায্য করতেন, আর নামাজের সময় হলে বেরিয়ে যেতেন (সহিহ বুখারি)।\n- ভারী ব্যাগ আপনি বহন করুন, ঘরের কাজ হাতে নিন, চেকআপে সাথে যান, আর তাঁকে অপরাধবোধ ছাড়াই বিশ্রাম নিতে দিন।\n- বিশেষ করে তিনি যখন ক্লান্ত বা আবেগপ্রবণ, তখন নরম করে কথা বলুন।\n\n## পরিবারের জন্য এর অর্থ\n\n- শ্বশুরবাড়ি ও আত্মীয়রা তাঁর বোঝা কমিয়ে সম্মান দেখাতে পারেন — নতুন দায়িত্ব চাপিয়ে বা অন্যের সাথে তুলনা করে নয়।\n- মা বাইরে চাকরি করলে ঘরের কাজ ভাগ করে নেওয়াও তাঁকে সম্মান করার অংশ।\n- একক মা দুই দায়িত্বই বহন করেন। পরিবার ও সমাজের উচিত তাঁর পাশে দাঁড়ানো, বিচার করা নয়।\n\nসন্তান যখন দেখে বাবা মাকে সম্মান করছেন, তখন কোনো উপদেশ ছাড়াই সে এই আয়াতগুলোর অর্থ শিখে যায়।"}'::jsonb, '{}'::jsonb, 4, -280, 365, '{}'::text[], 'any', ARRAY['mother', 'pregnancy', 'father role', 'respect', 'family']::text[], false, 'in_review'::lp_review_status, 9003),
  ('isl-pregnancy-gratitude-patience', 'article', 'islamic', 'shared', 'educational', 'religious', '🌙', '{"en":"Gratitude and patience in pregnancy","bn":"গর্ভাবস্থায় শুকরিয়া ও ধৈর্য"}'::jsonb, '{"en":"Pregnancy brings joy and hard days. Islam offers both shukr and sabr, and also real ease: prayer can be made easier and fasting may be left when there is fear of harm.","bn":"গর্ভাবস্থায় আনন্দও আছে, কঠিন দিনও আছে। ইসলাম শুকরিয়া ও সবর দুটোই শেখায়, আবার সত্যিকারের সহজতাও দেয়: নামাজ সহজ করে পড়া যায়, আর ক্ষতির আশঙ্কা থাকলে রোজা ছাড়া যায়।"}'::jsonb, '{"en":"Some days in pregnancy feel full of joy. Other days bring nausea, tiredness, worry or tears. Islam does not ask you to pretend. It gives you two companions for the journey: gratitude (shukr) and patience (sabr).\n\n## Both are good\n\nThe Prophet ﷺ said: how wonderful is the affair of the believer, for all of it is good. If something good happens, they are grateful, and that is good for them. If something hard happens, they are patient, and that is good for them (Sahih Muslim).\n\nHe also said that no tiredness, illness, worry or sadness reaches a Muslim, not even the prick of a thorn, except that Allah removes some of their sins because of it (Sahih al-Bukhari and Sahih Muslim). Your hard days are not wasted.\n\n## Words of comfort\n\nفَإِنَّ مَعَ الْعُسْرِ يُسْرًا ۝ إِنَّ مَعَ الْعُسْرِ يُسْرًا\n\n**Fa inna ma''al-''usri yusra. Inna ma''al-''usri yusra.**\n\nMeaning: So surely with hardship comes ease. Surely with hardship comes ease. (Surah Ash-Sharh 94:5–6)\n\nAllah also says that He does not place on any soul more than it can bear (Surah Al-Baqarah 2:286), and that if you are grateful, He will give you more (Surah Ibrahim 14:7).\n\n## Ease in worship\n\n- **Salah:** if standing is hard, you may pray sitting, and if sitting is hard, lying on your side. The Prophet ﷺ taught this to a man who was unwell (Sahih al-Bukhari).\n- **Fasting:** the Prophet ﷺ said that Allah has relieved the pregnant and the breastfeeding woman of fasting (Sunan Abi Dawud, Jami'' at-Tirmidhi). Decide about fasting with your doctor''s advice. How to make up missed fasts differs between scholars, so ask a trusted local scholar.\n- Small acts count: a few minutes of dhikr while resting, listening to the Quran, a whispered dua for your baby.\n\n## For the father\n\n- Thank your wife often, out loud. Gratitude to people is part of gratitude to Allah.\n- Pray together when you can, and make dua for her and the baby where she can hear you.\n- Take over tasks without being asked on her hardest days.\n\n## When it feels too heavy\n\nFeeling low or anxious is not weak faith. If sadness or worry stays most days, tell your doctor or health worker as well as making dua. If a loss happens, grief is allowed: when his baby son Ibrahim died, the Prophet ﷺ wept and said that the eye weeps and the heart grieves, but we say only what pleases our Lord (Sahih al-Bukhari and Sahih Muslim).","bn":"গর্ভাবস্থায় কিছু দিন আনন্দে ভরা থাকে। আবার কিছু দিন বমিভাব, ক্লান্তি, দুশ্চিন্তা বা কান্না নিয়ে আসে। ইসলাম আপনাকে ভান করতে বলে না। এই পথে দুটি সঙ্গী দেয়: শুকরিয়া আর সবর।\n\n## দুটোই কল্যাণ\n\nরাসূলুল্লাহ ﷺ বলেছেন: মুমিনের ব্যাপারটা কত চমৎকার! তার সবকিছুই কল্যাণ। ভালো কিছু হলে সে শুকরিয়া আদায় করে, তা তার জন্য কল্যাণ। কষ্ট এলে সে সবর করে, তা-ও তার জন্য কল্যাণ (সহিহ মুসলিম)।\n\nতিনি আরও বলেছেন, মুসলিমের ওপর যে ক্লান্তি, অসুখ, দুশ্চিন্তা বা দুঃখ আসে — এমনকি একটি কাঁটা বিঁধলেও — আল্লাহ তার বিনিময়ে তার কিছু গুনাহ মাফ করে দেন (সহিহ বুখারি ও সহিহ মুসলিম)। আপনার কঠিন দিনগুলো বৃথা যাচ্ছে না।\n\n## সান্ত্বনার বাণী\n\nفَإِنَّ مَعَ الْعُسْرِ يُسْرًا ۝ إِنَّ مَعَ الْعُسْرِ يُسْرًا\n\n**উচ্চারণ: ফাইন্না মাআল উসরি ইউসরা। ইন্না মাআল উসরি ইউসরা।**\n\nঅর্থ: নিশ্চয়ই কষ্টের সাথে স্বস্তি আছে। নিশ্চয়ই কষ্টের সাথে স্বস্তি আছে। (সূরা আশ-শারহ ৯৪:৫–৬)\n\nআল্লাহ আরও বলেন, তিনি কারও ওপর তার সাধ্যের বাইরে বোঝা চাপান না (সূরা আল-বাকারা ২:২৮৬), আর তোমরা কৃতজ্ঞ হলে তিনি আরও বাড়িয়ে দেবেন (সূরা ইবরাহিম ১৪:৭)।\n\n## ইবাদতে সহজতা\n\n- **নামাজ:** দাঁড়াতে কষ্ট হলে বসে পড়া যায়, বসতে কষ্ট হলে কাত হয়ে শুয়ে। রাসূলুল্লাহ ﷺ এক অসুস্থ সাহাবিকে এভাবে শিখিয়েছেন (সহিহ বুখারি)।\n- **রোজা:** রাসূলুল্লাহ ﷺ বলেছেন, আল্লাহ গর্ভবতী ও দুধদানকারী নারীর জন্য রোজায় ছাড় দিয়েছেন (সুনান আবু দাউদ, জামে তিরমিজি)। রোজা রাখবেন কিনা, তা ডাক্তারের পরামর্শ নিয়ে ঠিক করুন। ছুটে যাওয়া রোজা কীভাবে পূরণ করবেন, এ নিয়ে আলেমদের মধ্যে মতভেদ আছে, তাই একজন বিশ্বস্ত স্থানীয় আলেমকে জিজ্ঞেস করুন।\n- ছোট আমলও গোনা হয়: বিশ্রামের সময় কয়েক মিনিট জিকির, কুরআন শোনা, সন্তানের জন্য চুপিচুপি একটি দোয়া।\n\n## বাবার জন্য\n\n- স্ত্রীকে প্রায়ই মুখে ধন্যবাদ দিন। মানুষের প্রতি কৃতজ্ঞতা আল্লাহর প্রতি কৃতজ্ঞতারই অংশ।\n- সুযোগ হলে একসাথে নামাজ পড়ুন, আর তাঁর ও সন্তানের জন্য এমনভাবে দোয়া করুন যেন তিনি শুনতে পান।\n- তাঁর সবচেয়ে কঠিন দিনগুলোতে না বলতেই কাজগুলো নিজে করে ফেলুন।\n\n## যখন খুব ভারী লাগে\n\nমন খারাপ বা দুশ্চিন্তা হওয়া মানে ঈমান দুর্বল নয়। দুঃখ বা ভয় যদি বেশিরভাগ দিন থাকে, দোয়ার পাশাপাশি ডাক্তার বা স্বাস্থ্যকর্মীকেও জানান। যদি কোনো ক্ষতি হয়ে যায়, শোক করা জায়েজ: শিশুপুত্র ইবরাহিম মারা গেলে রাসূলুল্লাহ ﷺ কেঁদেছিলেন এবং বলেছিলেন, চোখ অশ্রু ঝরায়, অন্তর ব্যথিত হয়, কিন্তু আমরা তা-ই বলি যাতে আমাদের রব সন্তুষ্ট (সহিহ বুখারি ও সহিহ মুসলিম)।"}'::jsonb, '{}'::jsonb, 4, -280, 0, '{}'::text[], 'any', ARRAY['pregnancy', 'gratitude', 'patience', 'sabr', 'shukr', 'prayer', 'fasting']::text[], false, 'in_review'::lp_review_status, 9004),
  ('isl-maryam-story-expecting-mothers', 'article', 'islamic', 'mother', 'educational', 'religious', '🌴', '{"en":"Maryam''s story: comfort for expecting mothers","bn":"মারইয়াম (আ.)-এর ঘটনা: অন্তঃসত্ত্বা মায়ের জন্য সান্ত্বনা"}'::jsonb, '{"en":"Surah Maryam tells of a woman facing labour alone, afraid and in pain, and how Allah cared for her. A gentle reflection for the last weeks of pregnancy.","bn":"সূরা মারইয়ামে আছে এক নারীর কথা, যিনি একা, ভয় ও ব্যথা নিয়ে প্রসবের মুখোমুখি হয়েছিলেন — আর আল্লাহ কীভাবে তাঁর যত্ন নিয়েছিলেন। গর্ভাবস্থার শেষ সপ্তাহগুলোর জন্য একটি কোমল ভাবনা।"}'::jsonb, '{"en":"Maryam (peace be upon her) is the only woman named in the Quran, and a whole surah carries her name. Her story speaks directly to mothers waiting to give birth.\n\n## A mother''s dua before birth\n\nHer own story begins with her mother. While still pregnant, the wife of ''Imran said: my Lord, I dedicate what is in my womb to You, so accept it from me. When a daughter was born, she named her Maryam and asked Allah to protect her and her children from Shaytan (Surah Al Imran 3:35–36). You too can speak to Allah about your baby now, in your own words.\n\n## Fear, pain and honest feelings\n\nWhen the angel brought Maryam the news of a son, she asked how this could be, as no man had touched her. She was told that it is easy for Allah (Surah Maryam 19:16–21). She carried the baby and went to a place far away. Then the pains of labour drove her to the trunk of a palm tree, and she said: I wish I had died before this and been completely forgotten (Surah Maryam 19:22–23).\n\nThe Quran keeps these words. One of the best women who ever lived felt fear and pain, and said so. Your feelings in labour do not make you less of a believer.\n\n## Allah''s care in that moment\n\nA voice called to her from below her: do not grieve. Your Lord has placed a stream beneath you. Shake the trunk of the palm tree towards you, and fresh ripe dates will fall. So eat, drink and let your eyes be comforted (Surah Maryam 19:24–26).\n\nNotice what came first: comfort, water, food and rest. Then her baby, ''Isa (peace be upon him), spoke in the cradle to defend her honour (Surah Maryam 19:27–33).\n\n## Lessons for your birth\n\n- It is all right to be afraid. Bring your fear to Allah in dua.\n- Allah''s help often comes through simple things: a drink of water, food, a kind voice, a skilled midwife or doctor.\n- Maryam was alone. You do not have to be. Ask your husband, mother or a trusted woman to stay near you, and follow your doctor''s and midwife''s advice about eating and drinking in labour.\n- Prepare your bag and your plan, then trust Allah with what you cannot control.\n\n## For the father\n\nRead these verses with your wife in the last weeks. Then ask her: what will help you feel cared for on the day? Write it down and make it happen.","bn":"মারইয়াম (আ.) কুরআনে নাম ধরে উল্লেখ করা একমাত্র নারী, আর তাঁর নামে একটি পুরো সূরা আছে। তাঁর ঘটনা প্রসবের অপেক্ষায় থাকা মায়েদের সাথে সরাসরি কথা বলে।\n\n## জন্মের আগে এক মায়ের দোয়া\n\nতাঁর গল্প শুরু হয় তাঁর মাকে দিয়ে। গর্ভাবস্থায় ইমরানের স্ত্রী বলেছিলেন: হে আমার রব, আমার গর্ভে যা আছে তা আপনার জন্য উৎসর্গ করলাম, আমার কাছ থেকে কবুল করুন। মেয়ে জন্ম নিলে তিনি তার নাম রাখেন মারইয়াম এবং আল্লাহর কাছে তাকে ও তার সন্তানদের শয়তান থেকে রক্ষার দোয়া করেন (সূরা আলে ইমরান ৩:৩৫–৩৬)। আপনিও এখনই নিজের ভাষায় সন্তানের ব্যাপারে আল্লাহর সাথে কথা বলতে পারেন।\n\n## ভয়, ব্যথা ও সৎ অনুভূতি\n\nফেরেশতা যখন মারইয়াম (আ.)-কে পুত্রের সুসংবাদ দিলেন, তিনি জিজ্ঞেস করলেন, এ কীভাবে হবে, কোনো পুরুষ তো আমাকে স্পর্শ করেনি। তাঁকে বলা হলো, এটা আল্লাহর জন্য সহজ (সূরা মারইয়াম ১৯:১৬–২১)। তিনি সন্তান ধারণ করে দূরে এক জায়গায় চলে গেলেন। তারপর প্রসবব্যথা তাঁকে একটি খেজুর গাছের কাণ্ডের কাছে নিয়ে গেল, আর তিনি বললেন: হায়, এর আগেই যদি মরে যেতাম আর সবাই আমাকে ভুলে যেত (সূরা মারইয়াম ১৯:২২–২৩)।\n\nকুরআন এই কথাগুলো রেখে দিয়েছে। পৃথিবীর শ্রেষ্ঠ নারীদের একজনও ভয় ও ব্যথা অনুভব করেছেন এবং তা মুখে বলেছেন। প্রসবের সময় আপনার অনুভূতি আপনাকে কম ঈমানদার বানায় না।\n\n## সেই মুহূর্তে আল্লাহর যত্ন\n\nতাঁর নিচ থেকে একটি আওয়াজ তাঁকে ডেকে বলল: দুঃখ কোরো না। তোমার রব তোমার নিচে একটি ঝরনা দিয়েছেন। খেজুর গাছের কাণ্ড তোমার দিকে নাড়া দাও, তাজা পাকা খেজুর ঝরে পড়বে। তাই খাও, পান করো এবং চোখ জুড়াও (সূরা মারইয়াম ১৯:২৪–২৬)।\n\nলক্ষ করুন, আগে কী এল: সান্ত্বনা, পানি, খাবার আর বিশ্রাম। তারপর তাঁর শিশু ঈসা (আ.) দোলনা থেকেই কথা বলে মায়ের সম্মান রক্ষা করলেন (সূরা মারইয়াম ১৯:২৭–৩৩)।\n\n## আপনার প্রসবের জন্য শিক্ষা\n\n- ভয় পাওয়া স্বাভাবিক। ভয়টা দোয়ায় আল্লাহর কাছে নিয়ে যান।\n- আল্লাহর সাহায্য প্রায়ই আসে সাধারণ জিনিসের মাধ্যমে: এক চুমুক পানি, খাবার, একটি মমতাময় কণ্ঠ, একজন দক্ষ ধাত্রী বা ডাক্তার।\n- মারইয়াম (আ.) একা ছিলেন। আপনাকে একা থাকতে হবে না। স্বামী, মা বা বিশ্বস্ত কোনো নারীকে কাছে থাকতে বলুন। প্রসবের সময় কী খাবেন-পান করবেন, তা ডাক্তার ও ধাত্রীর পরামর্শমতো করুন।\n- ব্যাগ ও পরিকল্পনা গুছিয়ে নিন, তারপর যা আপনার হাতে নেই তা আল্লাহর ওপর ছেড়ে দিন।\n\n## বাবার জন্য\n\nশেষ সপ্তাহগুলোতে স্ত্রীর সাথে এই আয়াতগুলো পড়ুন। তারপর জিজ্ঞেস করুন: সেদিন কী করলে তুমি যত্ন পাচ্ছ বলে মনে হবে? লিখে রাখুন এবং সেভাবেই ব্যবস্থা করুন।"}'::jsonb, '{}'::jsonb, 4, -280, 0, '{}'::text[], 'any', ARRAY['maryam', 'pregnancy', 'birth', 'labour', 'comfort', 'quran story']::text[], false, 'in_review'::lp_review_status, 9005),
  ('isl-receiving-the-baby', 'checklist', 'islamic', 'shared', 'important', 'religious', '👶', '{"en":"Welcoming your baby: a newborn sunnah checklist","bn":"সন্তানকে স্বাগত জানানো: নবজাতকের সুন্নাহ চেকলিস্ট"}'::jsonb, '{"en":"The first days are for gratitude, rest and care. Here are the Islamic practices families often follow in the first week, and where to read more.","bn":"প্রথম দিনগুলো শুকরিয়া, বিশ্রাম ও যত্নের। প্রথম সপ্তাহে পরিবারগুলো সাধারণত যে ইসলামি আমলগুলো করে, এবং কোথায় বিস্তারিত পড়বেন।"}'::jsonb, '{"en":"Your baby has arrived. Begin with Alhamdulillah, whether you have a son or a daughter, an easy birth or a hard one. The Quran warns against feeling sad or ashamed at the birth of a girl (Surah An-Nahl 16:58–59), so welcome every child with the same joy.\n\nThe mother''s and baby''s health care comes first. None of these practices needs to happen in a rush, and none should delay medical care. Where scholars differ, the linked guides say so; ask a trusted local scholar if you are unsure.","bn":"আপনার সন্তান এসেছে। শুরু করুন আলহামদুলিল্লাহ দিয়ে — ছেলে হোক বা মেয়ে, প্রসব সহজ হোক বা কঠিন। কন্যাসন্তান জন্মে দুঃখ বা লজ্জা পাওয়ার বিরুদ্ধে কুরআন সতর্ক করেছে (সূরা আন-নাহল ১৬:৫৮–৫৯), তাই প্রতিটি সন্তানকে একই আনন্দে স্বাগত জানান।\n\nমা ও শিশুর স্বাস্থ্যসেবা সবার আগে। এই আমলগুলোর কোনোটির জন্য তাড়াহুড়ার দরকার নেই, আর কোনোটির জন্য চিকিৎসা দেরি করা যাবে না। যেখানে আলেমদের মধ্যে মতভেদ আছে, সংশ্লিষ্ট লেখায় তা বলা আছে; নিশ্চিত না হলে বিশ্বস্ত স্থানীয় আলেমকে জিজ্ঞেস করুন।"}'::jsonb, '{"items":{"en":["Say Alhamdulillah and thank Allah for your child, girl or boy","Let the mother rest and follow the health worker''s care for mother and baby first","Optional: say the adhan softly in the baby''s right ear (read the guide on the difference of opinion)","Optional: tahneek with a tiny amount of softened date, only if your doctor agrees; never honey","Choose a good name with a beautiful meaning, on the first day or by the seventh day","If you can afford it, plan the aqiqah for the seventh day, and shave the baby''s head with care","Give some charity in thanks, even a small amount","Make dua for your baby in any language, every day","For a boy, talk to your doctor about if and when to do circumcision","Share the good news with family and ask them to make dua, not to compare boys and girls"],"bn":["আলহামদুলিল্লাহ বলুন এবং সন্তানের জন্য আল্লাহর শুকরিয়া আদায় করুন — মেয়ে হোক বা ছেলে","মাকে বিশ্রাম দিন; আগে স্বাস্থ্যকর্মীর পরামর্শমতো মা ও শিশুর যত্ন নিন","ঐচ্ছিক: শিশুর ডান কানে আস্তে আজান দিন (মতভেদ বিষয়ে লেখাটি পড়ুন)","ঐচ্ছিক: ডাক্তার রাজি থাকলে খুব সামান্য নরম খেজুর দিয়ে তাহনিক; মধু কখনোই নয়","সুন্দর অর্থের একটি ভালো নাম রাখুন — প্রথম দিনে বা সপ্তম দিনের মধ্যে","সামর্থ্য থাকলে সপ্তম দিনে আকিকার পরিকল্পনা করুন এবং যত্ন করে শিশুর মাথা মুণ্ডন করুন","শুকরিয়া হিসেবে কিছু সদকা দিন, অল্প হলেও","প্রতিদিন যেকোনো ভাষায় সন্তানের জন্য দোয়া করুন","ছেলে হলে খতনা কখন ও কীভাবে করবেন, তা ডাক্তারের সাথে আলাপ করুন","পরিবারকে সুখবর দিন এবং ছেলে-মেয়ে তুলনা না করে দোয়া করতে বলুন"]}}'::jsonb, 2, -84, 30, '{}'::text[], 'any', ARRAY['newborn', 'sunnah', 'first week', 'gratitude', 'daughter', 'son']::text[], false, 'in_review'::lp_review_status, 9006),
  ('isl-adhan-newborn', 'article', 'islamic', 'father', 'educational', 'religious', '🕌', '{"en":"The adhan in the newborn''s ear","bn":"নবজাতকের কানে আজান"}'::jsonb, '{"en":"Many Muslim families softly say the adhan in a newborn''s right ear. Here is where the practice comes from, why scholars discuss it, and how to do it gently.","bn":"অনেক মুসলিম পরিবার নবজাতকের ডান কানে আস্তে আজান দেয়। এই আমলের উৎস কী, আলেমরা কেন এ নিয়ে আলোচনা করেন, আর কীভাবে কোমলভাবে করবেন।"}'::jsonb, '{"en":"In Bangladesh it is very common for the father or a grandfather to give the adhan in the baby''s ear soon after birth. It is a beautiful moment for many families. It also helps to know where it comes from.\n\n## The source\n\nAbu Rafi'' reported that he saw the Messenger of Allah ﷺ give the adhan for prayer in the ear of al-Hasan ibn ''Ali when Fatimah gave birth to him. This is recorded in Sunan Abi Dawud and Jami'' at-Tirmidhi.\n\n## A difference of opinion\n\nScholars differ on the strength of this report. At-Tirmidhi accepted it, and many scholars and families act on it. Other scholars consider its chain weak because of one narrator, and so do not regard the adhan as an established sunnah. Reports that add the iqamah in the left ear are considered weaker still by many scholars.\n\nBoth sides are sincere Muslims who love the Sunnah. Whichever view you follow, do not argue with relatives over it on such a happy day. If you want to be sure, ask a trusted local scholar.\n\n## The meaning many find in it\n\nScholars who discussed this practice, such as Ibn al-Qayyim in Tuhfat al-Mawdud, saw wisdom in it: the first words a baby hears are the greatness of Allah and the testimony of faith, the same words that call people to prayer for the rest of their life.\n\n## If you do it, do it gently\n\n- Wait until the mother and baby are settled and safe. It never needs to delay medical care.\n- Wash your hands. Hold the baby close and speak softly near the right ear. A newborn''s ears are sensitive, so do not shout.\n- The father can do it, or any Muslim family member, man or woman. You do not need to call an imam.\n- If the baby is in a special care unit, ask the staff when you may hold or be near the baby. Saying it later is fine.\n- Then make your own dua for your child.","bn":"বাংলাদেশে জন্মের পরপরই বাবা বা দাদা-নানার শিশুর কানে আজান দেওয়া খুব প্রচলিত। অনেক পরিবারের কাছে এটি একটি সুন্দর মুহূর্ত। এর উৎস জেনে রাখাও ভালো।\n\n## উৎস\n\nআবু রাফে (রা.) বর্ণনা করেছেন, ফাতিমা (রা.) যখন হাসান ইবনে আলী (রা.)-কে জন্ম দেন, তিনি রাসূলুল্লাহ ﷺ-কে তাঁর কানে নামাজের আজানের মতো আজান দিতে দেখেছেন। এটি সুনান আবু দাউদ ও জামে তিরমিজিতে আছে।\n\n## মতভেদ\n\nএই বর্ণনার শক্তি নিয়ে আলেমদের মধ্যে মতভেদ আছে। ইমাম তিরমিজি এটিকে গ্রহণ করেছেন, এবং অনেক আলেম ও পরিবার এর ওপর আমল করেন। আবার অনেক আলেম একজন বর্ণনাকারীর কারণে এর সনদকে দুর্বল মনে করেন, তাই একে প্রতিষ্ঠিত সুন্নাহ বলেন না। বাম কানে ইকামতের কথা যেসব বর্ণনায় আছে, অনেক আলেমের মতে সেগুলো আরও দুর্বল।\n\nদুই পক্ষই সুন্নাহকে ভালোবাসেন এমন আন্তরিক মুসলিম। যে মতই মানুন, এমন আনন্দের দিনে আত্মীয়দের সাথে এ নিয়ে তর্ক করবেন না। নিশ্চিত হতে চাইলে বিশ্বস্ত স্থানীয় আলেমকে জিজ্ঞেস করুন।\n\n## অনেকে এতে যে অর্থ খুঁজে পান\n\nযে আলেমরা এ নিয়ে আলোচনা করেছেন, যেমন ইবনুল কাইয়্যিম তাঁর তুহফাতুল মাওদুদ গ্রন্থে, তাঁরা এতে হিকমত দেখেছেন: শিশুর শোনা প্রথম কথাগুলো হয় আল্লাহর বড়ত্ব ও ঈমানের সাক্ষ্য — সেই একই কথা যা সারা জীবন তাকে নামাজের দিকে ডাকবে।\n\n## করলে কোমলভাবে করুন\n\n- মা ও শিশু স্থির ও নিরাপদ হওয়া পর্যন্ত অপেক্ষা করুন। এর জন্য কখনো চিকিৎসা দেরি করার দরকার নেই।\n- হাত ধুয়ে নিন। শিশুকে কাছে ধরে ডান কানের কাছে আস্তে বলুন। নবজাতকের কান খুব সংবেদনশীল, তাই জোরে বলবেন না।\n- বাবা দিতে পারেন, বা পরিবারের যেকোনো মুসলিম সদস্য — পুরুষ বা নারী। ইমাম ডাকার দরকার নেই।\n- শিশু বিশেষ সেবা ইউনিটে (SCANU/NICU) থাকলে কখন কোলে নিতে বা কাছে যেতে পারবেন, তা স্টাফদের জিজ্ঞেস করুন। পরে দিলেও সমস্যা নেই।\n- তারপর সন্তানের জন্য নিজের ভাষায় দোয়া করুন।"}'::jsonb, '{}'::jsonb, 3, -84, 30, '{}'::text[], 'any', ARRAY['adhan', 'azan', 'newborn', 'ear', 'difference of opinion']::text[], false, 'in_review'::lp_review_status, 9007),
  ('isl-tahneek', 'article', 'islamic', 'shared', 'educational', 'religious', '🌰', '{"en":"Tahneek: the sunnah of the softened date","bn":"তাহনিক: চিবানো খেজুরের সুন্নাহ"}'::jsonb, '{"en":"The Prophet ﷺ softened a date and touched it to newborns'' palates and prayed for them. What the hadith say, how scholars understand it, and how to keep it safe today.","bn":"রাসূলুল্লাহ ﷺ খেজুর নরম করে নবজাতকের তালুতে ছুঁইয়ে দিতেন এবং তাদের জন্য দোয়া করতেন। হাদিসে কী আছে, আলেমরা কীভাবে বোঝেন, আর আজ কীভাবে নিরাপদে করবেন।"}'::jsonb, '{"en":"Tahneek means softening a date and gently rubbing a little of it on the roof of a newborn''s mouth, together with a dua for blessing.\n\n## What the hadith say\n\nAbu Musa al-Ash''ari said: a son was born to me, and I brought him to the Prophet ﷺ. He named him Ibrahim, did tahneek for him with a date, prayed for blessing for him, and gave him back to me (Sahih al-Bukhari and Sahih Muslim).\n\nAnas ibn Malik also reported that when his mother Umm Sulaym gave birth to a son, Anas took the baby to the Prophet ﷺ, who chewed a date, put a little in the baby''s mouth, and named him ''Abdullah (Sahih al-Bukhari and Sahih Muslim).\n\nThe Companions brought their babies to the Prophet ﷺ because they wanted his blessing and his dua.\n\n## How scholars understand it\n\nMost scholars regard tahneek as a sunnah that families may follow today, done by a parent or a righteous person of the family. Ibn al-Qayyim discussed it in Tuhfat al-Mawdud. Some scholars hold that the special blessing was linked to the Prophet ﷺ himself, so they see it as permissible but not something to insist on. Either way, it is not an obligation, and leaving it is not a sin. Ask a trusted local scholar if you want more detail.\n\n## Keeping it safe today\n\nThe sunnah here is a tiny touch, not a feed.\n\n- Talk to your doctor or midwife first, especially if the baby is premature, small or unwell. If they advise waiting, wait.\n- Use clean, washed hands. A fresh, soft date can be mashed with a clean spoon rather than chewed.\n- Rub only a trace on the palate. Do not give anything for the baby to swallow.\n- Never use honey for a baby under one year.\n- Do not let tahneek delay the first breastfeed.\n\n## The heart of it\n\nWhatever you decide about the date, do not miss the dua. Hold your baby, ask Allah to bless them, to make them among the righteous, and to make them a coolness of the eyes for you.","bn":"তাহনিক মানে একটি খেজুর নরম করে তার সামান্য অংশ নবজাতকের মুখের তালুতে আলতো করে ঘষে দেওয়া, সাথে বরকতের দোয়া করা।\n\n## হাদিসে কী আছে\n\nআবু মুসা আশআরি (রা.) বলেছেন: আমার একটি ছেলে হলো, আমি তাকে নবী ﷺ-এর কাছে নিয়ে গেলাম। তিনি তার নাম রাখলেন ইবরাহিম, খেজুর দিয়ে তাহনিক করলেন, তার জন্য বরকতের দোয়া করলেন এবং আমার কাছে ফিরিয়ে দিলেন (সহিহ বুখারি ও সহিহ মুসলিম)।\n\nআনাস ইবনে মালিক (রা.)-ও বর্ণনা করেছেন, তাঁর মা উম্মে সুলাইম (রা.)-এর একটি ছেলে হলে আনাস (রা.) শিশুটিকে নবী ﷺ-এর কাছে নিয়ে যান। তিনি একটি খেজুর চিবিয়ে সামান্য শিশুর মুখে দিলেন এবং তার নাম রাখলেন আবদুল্লাহ (সহিহ বুখারি ও সহিহ মুসলিম)।\n\nসাহাবিরা নবী ﷺ-এর বরকত ও দোয়ার আশায় তাঁদের শিশুদের তাঁর কাছে নিয়ে যেতেন।\n\n## আলেমরা কীভাবে বোঝেন\n\nবেশিরভাগ আলেম তাহনিককে এমন সুন্নাহ মনে করেন যা আজও পরিবার করতে পারে — বাবা-মা বা পরিবারের কোনো নেককার মানুষ করবেন। ইবনুল কাইয়্যিম তুহফাতুল মাওদুদে এ নিয়ে আলোচনা করেছেন। কিছু আলেমের মতে বিশেষ বরকতটি নবী ﷺ-এর সাথেই সম্পর্কিত ছিল, তাই তাঁরা এটিকে জায়েজ বলেন, কিন্তু জোর দেন না। যেভাবেই হোক, এটি ফরজ নয়, না করলে গুনাহ নেই। বিস্তারিত জানতে বিশ্বস্ত স্থানীয় আলেমকে জিজ্ঞেস করুন।\n\n## আজ কীভাবে নিরাপদে করবেন\n\nএখানে সুন্নাহ হলো সামান্য ছোঁয়া, খাওয়ানো নয়।\n\n- আগে ডাক্তার বা ধাত্রীর সাথে কথা বলুন, বিশেষ করে শিশু অপরিণত (premature), ছোট বা অসুস্থ হলে। অপেক্ষা করতে বললে অপেক্ষা করুন।\n- পরিষ্কার, ধোয়া হাত ব্যবহার করুন। মুখে চিবানোর বদলে নরম তাজা খেজুর পরিষ্কার চামচ দিয়ে চটকে নিতে পারেন।\n- তালুতে শুধু সামান্য একটু ঘষুন। গিলে খাওয়ার মতো কিছু দেবেন না।\n- এক বছরের কম বয়সী শিশুকে কখনো মধু দেবেন না।\n- তাহনিকের জন্য প্রথম বুকের দুধ খাওয়ানো দেরি করবেন না।\n\n## আসল কথা\n\nখেজুর নিয়ে যে সিদ্ধান্তই নিন, দোয়াটা বাদ দেবেন না। সন্তানকে কোলে নিয়ে আল্লাহর কাছে চান — তাকে বরকত দিন, নেককারদের অন্তর্ভুক্ত করুন, আর আপনাদের চোখের শীতলতা বানান।"}'::jsonb, '{}'::jsonb, 3, -84, 30, '{}'::text[], 'any', ARRAY['tahneek', 'date', 'newborn', 'sunnah', 'honey']::text[], false, 'in_review'::lp_review_status, 9008),
  ('isl-choosing-a-name', 'article', 'islamic', 'shared', 'educational', 'religious', '📝', '{"en":"Choosing a good name for your child","bn":"সন্তানের জন্য সুন্দর নাম বাছাই"}'::jsonb, '{"en":"A name is a lifelong gift. What the Sunnah teaches about good names, when to name the baby, and practical tips for Bangladeshi families.","bn":"নাম সারা জীবনের একটি উপহার। সুন্দর নাম নিয়ে সুন্নাহ কী শেখায়, কখন নাম রাখবেন, আর বাংলাদেশি পরিবারের জন্য কিছু ব্যবহারিক পরামর্শ।"}'::jsonb, '{"en":"Your child will hear their name thousands of times. Islam asks parents to choose it with care, so it carries a good meaning and gives dignity.\n\n## What the Sunnah teaches\n\n- The Prophet ﷺ said that the names most beloved to Allah are ''Abdullah and ''Abdur-Rahman (Sahih Muslim). Names that mean servant of one of Allah''s names, like ''Abdul-Karim or ''Abdur-Rahim, carry the same beauty.\n- Names of prophets are good choices. The Prophet ﷺ named his own son Ibrahim, after his forefather (Sahih Muslim), and he allowed people to name their children Muhammad (Sahih al-Bukhari and Sahih Muslim).\n- He changed names with a bad meaning. For example, he changed the name of a woman called ''Asiyah, which means disobedient, to Jamilah, which means beautiful (Sahih Muslim).\n- Scholars agree to avoid names that mean servant of anyone other than Allah, and names with an ugly, proud or unclear meaning.\n- For girls there are many beautiful names: the Prophet''s daughters were Zaynab, Ruqayyah, Umm Kulthum and Fatimah, and Maryam is named in the Quran.\n\n## When to name the baby\n\nBoth are from the Sunnah. The Prophet ﷺ named his son Ibrahim on the night he was born (Sahih Muslim), and he also spoke of naming the child on the seventh day, with the aqiqah (Sunan Abi Dawud, Jami'' at-Tirmidhi). So you may name your baby on the first day or by the seventh. Ibn al-Qayyim discusses both in Tuhfat al-Mawdud.\n\n## Practical tips\n\n- Check the meaning with a reliable Arabic dictionary or a scholar. Many names circulate online with wrong meanings.\n- Choose a name that is easy to spell in Bangla and English, so it matches on the birth registration, passport and school records.\n- A name in Bangla or any language with a good meaning is also permissible.\n- Parents decide together. Grandparents often love to suggest names; listen kindly, and agree as a family.\n- Avoid names that may bring teasing, and avoid long strings of names your child will struggle to write.\n- Register the birth with the name you have chosen, so official papers are right from the start.","bn":"আপনার সন্তান হাজারবার তার নাম শুনবে। ইসলাম বাবা-মাকে যত্ন নিয়ে নাম বাছতে বলে, যেন তার অর্থ সুন্দর হয় এবং তা মর্যাদা দেয়।\n\n## সুন্নাহ কী শেখায়\n\n- রাসূলুল্লাহ ﷺ বলেছেন, আল্লাহর কাছে সবচেয়ে প্রিয় নাম আবদুল্লাহ ও আবদুর রহমান (সহিহ মুসলিম)। আল্লাহর কোনো নামের বান্দা অর্থে নাম, যেমন আবদুল করিম বা আবদুর রহিম, একই সৌন্দর্য বহন করে।\n- নবীদের নাম ভালো পছন্দ। নবী ﷺ নিজের ছেলের নাম পূর্বপুরুষ ইবরাহিম (আ.)-এর নামে রেখেছিলেন (সহিহ মুসলিম), আর মানুষকে মুহাম্মাদ নাম রাখার অনুমতি দিয়েছেন (সহিহ বুখারি ও সহিহ মুসলিম)।\n- খারাপ অর্থের নাম তিনি বদলে দিতেন। যেমন, আসিয়া (অবাধ্য) নামের এক নারীর নাম বদলে রাখেন জামিলা (সুন্দর) (সহিহ মুসলিম)।\n- আল্লাহ ছাড়া অন্য কারও বান্দা অর্থের নাম, এবং কুৎসিত, অহংকারী বা অস্পষ্ট অর্থের নাম এড়িয়ে চলতে আলেমরা একমত।\n- মেয়েদের জন্য অনেক সুন্দর নাম আছে: নবী ﷺ-এর মেয়েরা ছিলেন জয়নব, রুকাইয়া, উম্মে কুলসুম ও ফাতিমা, আর কুরআনে মারইয়াম নাম এসেছে।\n\n## কখন নাম রাখবেন\n\nদুটোই সুন্নাহ। নবী ﷺ জন্মের রাতেই ছেলের নাম ইবরাহিম রেখেছিলেন (সহিহ মুসলিম), আবার আকিকার সাথে সপ্তম দিনে নাম রাখার কথাও বলেছেন (সুনান আবু দাউদ, জামে তিরমিজি)। তাই প্রথম দিনে বা সপ্তম দিনের মধ্যে নাম রাখতে পারেন। ইবনুল কাইয়্যিম তুহফাতুল মাওদুদে দুটোই আলোচনা করেছেন।\n\n## ব্যবহারিক পরামর্শ\n\n- নির্ভরযোগ্য আরবি অভিধান বা আলেমের কাছে অর্থ যাচাই করুন। অনলাইনে অনেক নাম ভুল অর্থে ছড়ানো থাকে।\n- এমন নাম বাছুন যার বানান বাংলা ও ইংরেজিতে সহজ, যাতে জন্মনিবন্ধন, পাসপোর্ট ও স্কুলের কাগজে মিল থাকে।\n- বাংলা বা যেকোনো ভাষার সুন্দর অর্থের নামও রাখা জায়েজ।\n- বাবা-মা মিলে সিদ্ধান্ত নিন। দাদা-দাদি, নানা-নানি প্রায়ই নাম প্রস্তাব করতে ভালোবাসেন; আন্তরিকভাবে শুনুন এবং পরিবার মিলে একমত হোন।\n- যে নাম নিয়ে ঠাট্টা হতে পারে, বা এত লম্বা যে সন্তান লিখতে হিমশিম খাবে, তা এড়িয়ে চলুন।\n- বাছাই করা নাম দিয়েই জন্মনিবন্ধন করুন, যাতে শুরু থেকেই সরকারি কাগজ ঠিক থাকে।"}'::jsonb, '{}'::jsonb, 3, -280, 30, '{}'::text[], 'any', ARRAY['name', 'naming', 'newborn', 'meaning', 'seventh day']::text[], false, 'in_review'::lp_review_status, 9009),
  ('isl-aqiqah', 'article', 'islamic', 'shared', 'educational', 'religious', '🐐', '{"en":"Aqiqah: the seventh-day sunnah","bn":"আকিকা: সপ্তম দিনের সুন্নাহ"}'::jsonb, '{"en":"Aqiqah is an animal sacrifice in thanks for a child, with head shaving and charity. What is agreed, where scholars differ, and how to plan it without strain.","bn":"আকিকা হলো সন্তানের শুকরিয়া হিসেবে পশু জবাই, সাথে মাথা মুণ্ডন ও সদকা। কোন বিষয়ে আলেমরা একমত, কোথায় মতভেদ, আর চাপ ছাড়া কীভাবে পরিকল্পনা করবেন।"}'::jsonb, '{"en":"Aqiqah is a way of thanking Allah for a new child by sacrificing an animal and sharing the meat. It is joyful, and it is meant to be within your means.\n\n## The source\n\nThe Prophet ﷺ said that every child is held in pledge by its aqiqah, which is sacrificed for it on the seventh day; its head is shaved and it is given its name (Sunan Abi Dawud, Jami'' at-Tirmidhi, Sunan Ibn Majah). Other hadith in Sunan Abi Dawud and Jami'' at-Tirmidhi mention two sheep or goats for a boy and one for a girl.\n\n## What scholars agree on and where they differ\n\n- **Ruling:** most scholars consider aqiqah a strongly recommended sunnah, not an obligation. Some hold it is obligatory, and some Hanafi scholars treat it as simply permissible. If you cannot afford it, there is no sin.\n- **Number of animals:** many scholars say two for a boy and one for a girl. The Maliki school holds one animal for each child is enough. One animal for a boy is also accepted by many scholars when money is tight.\n- **A share of a cow:** in Bangladesh many families take a share in a cow. The Hanafi and Shafi''i schools allow this; others prefer a whole sheep or goat.\n- **Timing:** the seventh day is the sunnah. If that is missed, some scholars mention the fourteenth or twenty-first day, and many allow it later.\n- **Hair and charity:** shaving the baby''s head on the seventh day is in the hadith above. Weighing the hair and giving its weight in silver as charity is reported in Jami'' at-Tirmidhi; scholars discuss the strength of that report, and many families give charity equal to that value.\n\nFor your own situation, ask a trusted local scholar. Ibn al-Qayyim gathers these questions in Tuhfat al-Mawdud.\n\n## Health and safety\n\n- Shave the baby''s head only with a new or sterilised blade, by a careful, experienced person, and stop if the scalp is broken or the baby is unwell.\n- If the baby is in hospital or weak, the sacrifice can go ahead while the shaving waits.\n\n## The meat\n\nThe meat may be cooked or given raw. Families usually share it between the household, relatives and neighbours, and the poor. Remember the poor first, not only guests.","bn":"আকিকা হলো নতুন সন্তানের জন্য পশু জবাই করে ও গোশত ভাগ করে আল্লাহর শুকরিয়া আদায়ের একটি উপায়। এটি আনন্দের, আর এটি সামর্থ্যের মধ্যে করার জন্যই।\n\n## উৎস\n\nরাসূলুল্লাহ ﷺ বলেছেন, প্রতিটি শিশু তার আকিকার সাথে বন্ধক থাকে; সপ্তম দিনে তার পক্ষ থেকে জবাই করা হবে, তার মাথা মুণ্ডন করা হবে এবং নাম রাখা হবে (সুনান আবু দাউদ, জামে তিরমিজি, সুনান ইবনে মাজাহ)। সুনান আবু দাউদ ও জামে তিরমিজির অন্য হাদিসে ছেলের জন্য দুটি এবং মেয়ের জন্য একটি ছাগল বা ভেড়ার কথা আছে।\n\n## কোথায় একমত, কোথায় মতভেদ\n\n- **হুকুম:** বেশিরভাগ আলেমের মতে আকিকা সুন্নাতে মুআক্কাদা, ফরজ নয়। কেউ কেউ একে ওয়াজিব বলেন, আবার কিছু হানাফি আলেম একে শুধু জায়েজ বলেন। সামর্থ্য না থাকলে কোনো গুনাহ নেই।\n- **পশুর সংখ্যা:** অনেক আলেম বলেন ছেলের জন্য দুটি, মেয়ের জন্য একটি। মালিকি মাজহাবে প্রতিটি সন্তানের জন্য একটিই যথেষ্ট। টাকার টানাটানি থাকলে ছেলের জন্য একটি পশুকেও অনেক আলেম গ্রহণযোগ্য বলেন।\n- **গরুর ভাগ:** বাংলাদেশে অনেক পরিবার গরুতে ভাগ নেয়। হানাফি ও শাফেয়ি মাজহাবে এটি জায়েজ; অন্যরা আস্ত ছাগল বা ভেড়াকে উত্তম বলেন।\n- **সময়:** সপ্তম দিন সুন্নাহ। সেদিন না হলে কিছু আলেম চৌদ্দতম বা একুশতম দিনের কথা বলেন, আর অনেকে পরেও করার অনুমতি দেন।\n- **চুল ও সদকা:** সপ্তম দিনে মাথা মুণ্ডনের কথা ওপরের হাদিসেই আছে। চুল ওজন করে সমপরিমাণ রুপা সদকার কথা জামে তিরমিজিতে বর্ণিত; এর সনদ নিয়ে আলেমরা আলোচনা করেন, আর অনেক পরিবার সেই মূল্যের সমান সদকা দেয়।\n\nআপনার নিজের অবস্থার জন্য বিশ্বস্ত স্থানীয় আলেমকে জিজ্ঞেস করুন। ইবনুল কাইয়্যিম তুহফাতুল মাওদুদে এই প্রশ্নগুলো একসাথে আলোচনা করেছেন।\n\n## স্বাস্থ্য ও নিরাপত্তা\n\n- নতুন বা জীবাণুমুক্ত ব্লেড দিয়ে, সাবধানী ও অভিজ্ঞ কাউকে দিয়ে শিশুর মাথা মুণ্ডন করান। মাথার চামড়া কেটে গেলে বা শিশু অসুস্থ হলে থামুন।\n- শিশু হাসপাতালে বা দুর্বল থাকলে জবাই হয়ে যেতে পারে, মাথা মুণ্ডন পরে করলেও চলবে।\n\n## গোশত\n\nগোশত রান্না করে বা কাঁচা দুভাবেই দেওয়া যায়। পরিবারগুলো সাধারণত নিজেদের, আত্মীয়-প্রতিবেশী ও গরিবদের মধ্যে ভাগ করে। শুধু অতিথি নয়, আগে গরিবদের কথা মনে রাখুন।"}'::jsonb, '{"steps":{"en":["Decide as a couple what you can afford without debt or strain","Ask a trusted local scholar about the number of animals or a cow share if you are unsure","Arrange a healthy animal and a person to slaughter it the Islamic way, ideally on the seventh day","Have the baby''s head shaved gently with a clean blade, if the baby is well","Give charity, including for the poor in your area","Share the meat with family, neighbours and those in need","Make dua for your child together"],"bn":["ঋণ বা চাপ ছাড়া কতটুকু পারবেন, স্বামী-স্ত্রী মিলে ঠিক করুন","পশুর সংখ্যা বা গরুর ভাগ নিয়ে নিশ্চিত না হলে বিশ্বস্ত স্থানীয় আলেমকে জিজ্ঞেস করুন","সুস্থ পশু ও ইসলামি নিয়মে জবাই করার মানুষ ঠিক করুন — সম্ভব হলে সপ্তম দিনে","শিশু সুস্থ থাকলে পরিষ্কার ব্লেড দিয়ে আলতো করে মাথা মুণ্ডন করান","সদকা দিন, এলাকার গরিবদের কথাও মনে রাখুন","পরিবার, প্রতিবেশী ও অভাবীদের সাথে গোশত ভাগ করুন","একসাথে সন্তানের জন্য দোয়া করুন"]}}'::jsonb, 4, -84, 61, '{}'::text[], 'any', ARRAY['aqiqah', 'aqiqa', 'seventh day', 'head shaving', 'charity', 'sacrifice']::text[], false, 'in_review'::lp_review_status, 9010),
  ('isl-circumcision', 'article', 'islamic', 'shared', 'educational', 'religious', '🩹', '{"en":"Circumcision (khatna) for boys","bn":"ছেলেদের খতনা"}'::jsonb, '{"en":"Circumcision is part of the fitrah in Islam. The Sunnah sets no fixed age, so when and how is decided with your doctor''s advice, with care for your son''s feelings.","bn":"ইসলামে খতনা ফিতরাতের অংশ। সুন্নাহতে কোনো নির্দিষ্ট বয়স বাঁধা নেই, তাই কখন ও কীভাবে করবেন তা ডাক্তারের পরামর্শে ঠিক করুন — ছেলের অনুভূতির যত্ন নিয়ে।"}'::jsonb, '{"en":"In Bangladesh, khatna is a well-known family occasion. Here is what Islam teaches, and how to keep the focus on your son''s wellbeing.\n\n## Part of the fitrah\n\nThe Prophet ﷺ said that five things are part of the fitrah, the natural way: circumcision, removing pubic hair, trimming the moustache, clipping the nails and removing underarm hair (Sahih al-Bukhari and Sahih Muslim). He also mentioned that Prophet Ibrahim (peace be upon him) was circumcised (Sahih al-Bukhari and Sahih Muslim).\n\n## The ruling\n\nScholars agree that circumcision for boys is part of the Islamic way. They differ on how strong the ruling is: the Shafi''i and Hanbali schools consider it obligatory, while the Hanafi and Maliki schools consider it a strongly emphasised sunnah. In practice, Muslim families in every school circumcise their sons. Ibn al-Qayyim discusses the ruling and the timing at length in Tuhfat al-Mawdud.\n\n## When\n\nThe Sunnah does not fix one age. Some families choose the first weeks or months, others wait until the boy is older, and many scholars say it should be done before puberty, when he becomes responsible for his own purity in prayer. The right time and method for your son should be decided with your doctor''s advice.\n\n- Have it done by a trained doctor or surgeon in a clean health facility, not by an untrained person.\n- Ask the doctor about pain relief, care afterwards, and which signs mean you should come back.\n- If your son has any health condition, the doctor may advise a different time.\n\n## Caring for his feelings\n\nIf your son is old enough to understand:\n\n- Explain simply and honestly what will happen and why. Do not frighten him or make jokes about it.\n- Never threaten circumcision as a punishment.\n- Protect his privacy. It is not a show for guests, and relatives should not tease him.\n- Stay with him, hold his hand, praise his courage, and give him quiet time to rest.\n\n## For the father\n\nThis is a natural moment for a father to step forward: book the doctor, be there on the day, help with care afterwards, and talk to your son about cleanliness and the fitrah in a warm, respectful way.","bn":"বাংলাদেশে খতনা একটি পরিচিত পারিবারিক উপলক্ষ। ইসলাম কী শেখায়, আর কীভাবে ছেলের সুস্থতাকেই মূল বিষয় রাখবেন — তা এখানে।\n\n## ফিতরাতের অংশ\n\nরাসূলুল্লাহ ﷺ বলেছেন, পাঁচটি জিনিস ফিতরাত বা স্বাভাবিক পথের অংশ: খতনা, নাভির নিচের লোম পরিষ্কার, গোঁফ ছাঁটা, নখ কাটা এবং বগলের লোম পরিষ্কার (সহিহ বুখারি ও সহিহ মুসলিম)। তিনি আরও উল্লেখ করেছেন যে নবী ইবরাহিম (আ.)-এর খতনা হয়েছিল (সহিহ বুখারি ও সহিহ মুসলিম)।\n\n## হুকুম\n\nছেলেদের খতনা ইসলামি পথের অংশ — এ বিষয়ে আলেমরা একমত। তবে হুকুম কতটা জোরালো, তা নিয়ে মতভেদ আছে: শাফেয়ি ও হাম্বলি মাজহাবে এটি ওয়াজিব, আর হানাফি ও মালিকি মাজহাবে সুন্নাতে মুআক্কাদা। বাস্তবে সব মাজহাবের মুসলিম পরিবারই ছেলেদের খতনা করায়। ইবনুল কাইয়্যিম তুহফাতুল মাওদুদে এর হুকুম ও সময় নিয়ে বিস্তারিত আলোচনা করেছেন।\n\n## কখন\n\nসুন্নাহতে কোনো একটি বয়স বাঁধা নেই। কিছু পরিবার প্রথম কয়েক সপ্তাহ বা মাসে করায়, কেউ ছেলে একটু বড় হলে। অনেক আলেম বলেন বালেগ হওয়ার আগে করে ফেলা উচিত, কারণ তখন থেকে নামাজের পবিত্রতার দায়িত্ব তার নিজের। আপনার ছেলের জন্য সঠিক সময় ও পদ্ধতি ডাক্তারের পরামর্শে ঠিক করুন।\n\n- প্রশিক্ষিত ডাক্তার বা সার্জন দিয়ে পরিষ্কার স্বাস্থ্যকেন্দ্রে করান, অপ্রশিক্ষিত কাউকে দিয়ে নয়।\n- ব্যথা কমানো, পরের যত্ন, আর কোন লক্ষণ দেখলে আবার আসতে হবে — ডাক্তারকে জিজ্ঞেস করুন।\n- ছেলের কোনো স্বাস্থ্যগত সমস্যা থাকলে ডাক্তার অন্য সময় করার পরামর্শ দিতে পারেন।\n\n## তার অনুভূতির যত্ন\n\nছেলে বোঝার মতো বড় হলে:\n\n- কী হবে ও কেন, সহজ ভাষায় সত্যি করে বুঝিয়ে বলুন। ভয় দেখাবেন না, ঠাট্টাও করবেন না।\n- কখনো শাস্তি হিসেবে খতনার ভয় দেখাবেন না।\n- তার গোপনীয়তা রক্ষা করুন। এটি অতিথিদের দেখানোর বিষয় নয়, আর আত্মীয়রা যেন তাকে খেপাতে না পারে।\n- তার পাশে থাকুন, হাত ধরে রাখুন, সাহসের প্রশংসা করুন, আর শান্তিতে বিশ্রাম নিতে দিন।\n\n## বাবার জন্য\n\nএটি বাবার এগিয়ে আসার স্বাভাবিক মুহূর্ত: ডাক্তারের সময় নিন, সেদিন পাশে থাকুন, পরের যত্নে সাহায্য করুন, আর পরিচ্ছন্নতা ও ফিতরাত নিয়ে ছেলের সাথে আন্তরিক ও সম্মানজনকভাবে কথা বলুন।"}'::jsonb, '{}'::jsonb, 3, 0, 4748, '{}'::text[], 'male', ARRAY['circumcision', 'khatna', 'fitrah', 'boys', 'sunnah']::text[], false, 'in_review'::lp_review_status, 9011),
  ('isl-breastfeeding-quran', 'article', 'islamic', 'shared', 'educational', 'religious', '🤱', '{"en":"Breastfeeding in the Quran","bn":"কুরআনে বুকের দুধ খাওয়ানো"}'::jsonb, '{"en":"Surah Al-Baqarah 2:233 speaks of nursing for two years, of the father''s duty to provide, of mutual consultation, and of not burdening anyone beyond their capacity.","bn":"সূরা আল-বাকারা ২:২৩৩-এ আছে দুই বছর দুধ খাওয়ানো, বাবার ভরণপোষণের দায়িত্ব, পারস্পরিক পরামর্শ এবং কাউকে সাধ্যের বাইরে বোঝা না দেওয়ার কথা।"}'::jsonb, '{"en":"The Quran speaks about breastfeeding in a way that is practical and kind to both parents.\n\n## Surah Al-Baqarah 2:233\n\nThe meaning of this verse, in summary:\n\n- Mothers may nurse their children for two full years, for those who wish to complete the nursing.\n- The father is responsible for the mother''s food and clothing in a fair way.\n- No soul is burdened beyond what it can bear.\n- No mother should be harmed because of her child, and no father because of his child.\n- If both parents agree, after consulting each other, to wean earlier, there is no blame on them.\n- If you choose to have another woman nurse your child, there is no blame on you, as long as you pay what is fair.\n\n## Lessons for the family\n\n**It is a shared project.** The verse speaks to the mother and the father together. The mother nurses; the father provides, protects and supports. Bringing her water, taking the baby for burping and changing, and keeping visitors from tiring her are part of his role.\n\n**Decisions are made together.** The word used for weaning decisions involves mutual consent and consultation. Neither parent should decide alone, and grandparents can advise but should not pressure.\n\n**No one is burdened beyond capacity.** Some mothers face real difficulties with breastfeeding. That is not a failing in faith. Ask a health worker or breastfeeding counsellor for help, and decide together what is best.\n\n**Allah honours nursing.** Allah returned baby Musa to his mother so that she could nurse him and her eyes would be comforted (Surah Al-Qasas 28:7–13). Luqman 31:14 and Al-Ahqaf 46:15 also mention weaning as part of the mother''s effort.\n\n## Milk kinship\n\nThe Prophet ﷺ said that nursing creates the same unmarriageable relationships that birth does (Sahih al-Bukhari and Sahih Muslim). So if another woman nurses your baby, or you are thinking about donor milk, the child may become a milk-sibling to her children. The details of how much nursing counts differ between the schools of law, so ask a trusted local scholar and keep a record of who nursed your child.\n\nFor health questions about feeding, follow your doctor''s or health worker''s advice.","bn":"কুরআন বুকের দুধ খাওয়ানোর কথা এমনভাবে বলেছে, যা বাস্তবসম্মত এবং বাবা-মা দুজনের প্রতিই সদয়।\n\n## সূরা আল-বাকারা ২:২৩৩\n\nএই আয়াতের অর্থের সারকথা:\n\n- মায়েরা সন্তানদের পূর্ণ দুই বছর দুধ খাওয়াবেন — যারা দুধ খাওয়ানো পূর্ণ করতে চায় তাদের জন্য।\n- ন্যায্যভাবে মায়ের খাবার ও পোশাকের দায়িত্ব বাবার।\n- কাউকে তার সাধ্যের বাইরে বোঝা দেওয়া হয় না।\n- সন্তানের কারণে মায়ের ক্ষতি করা যাবে না, আর সন্তানের কারণে বাবারও না।\n- বাবা-মা দুজনে পরামর্শ করে রাজি হয়ে আগে দুধ ছাড়াতে চাইলে তাঁদের কোনো দোষ নেই।\n- অন্য কোনো নারীকে দিয়ে দুধ খাওয়াতে চাইলেও দোষ নেই, যদি ন্যায্য পারিশ্রমিক দেন।\n\n## পরিবারের জন্য শিক্ষা\n\n**এটি যৌথ কাজ।** আয়াতটি মা ও বাবা দুজনকেই উদ্দেশ করে। মা দুধ খাওয়ান; বাবা ভরণপোষণ দেন, আগলে রাখেন, পাশে থাকেন। তাঁকে পানি এনে দেওয়া, শিশুর ঢেকুর তোলানো ও কাপড় বদলানো, আর অতিথিরা যেন তাঁকে ক্লান্ত না করে তা দেখা — এগুলো বাবার কাজ।\n\n**সিদ্ধান্ত একসাথে।** দুধ ছাড়ানোর সিদ্ধান্তে পারস্পরিক সম্মতি ও পরামর্শের কথা বলা হয়েছে। কেউ একা সিদ্ধান্ত নেবেন না; দাদা-দাদি, নানা-নানি পরামর্শ দিতে পারেন, কিন্তু চাপ দেবেন না।\n\n**সাধ্যের বাইরে বোঝা নেই।** কিছু মা দুধ খাওয়াতে সত্যিই সমস্যায় পড়েন। এটা ঈমানের দুর্বলতা নয়। স্বাস্থ্যকর্মী বা ব্রেস্টফিডিং কাউন্সেলরের সাহায্য নিন, আর একসাথে ঠিক করুন কী ভালো।\n\n**আল্লাহ দুধ খাওয়ানোকে সম্মান দিয়েছেন।** আল্লাহ শিশু মূসা (আ.)-কে তাঁর মায়ের কাছে ফিরিয়ে দিয়েছিলেন, যেন তিনি দুধ খাওয়াতে পারেন এবং তাঁর চোখ জুড়ায় (সূরা আল-কাসাস ২৮:৭–১৩)। সূরা লুকমান ৩১:১৪ ও সূরা আল-আহকাফ ৪৬:১৫-তেও দুধ ছাড়ানোকে মায়ের কষ্টের অংশ হিসেবে বলা হয়েছে।\n\n## দুধ-সম্পর্ক\n\nরাসূলুল্লাহ ﷺ বলেছেন, জন্মের কারণে যেসব সম্পর্কে বিয়ে হারাম, দুধপানের কারণেও সেগুলো হারাম হয় (সহিহ বুখারি ও সহিহ মুসলিম)। তাই অন্য কোনো নারী আপনার শিশুকে দুধ খাওয়ালে, বা ডোনার মিল্কের কথা ভাবলে, শিশুটি তাঁর সন্তানদের দুধভাই বা দুধবোন হয়ে যেতে পারে। কতটুকু দুধপানে এই সম্পর্ক হয়, তা নিয়ে মাজহাবগুলোর মধ্যে মতভেদ আছে, তাই বিশ্বস্ত স্থানীয় আলেমকে জিজ্ঞেস করুন এবং কে দুধ খাইয়েছেন তা লিখে রাখুন।\n\nখাওয়ানো নিয়ে স্বাস্থ্যগত প্রশ্নে ডাক্তার বা স্বাস্থ্যকর্মীর পরামর্শ মানুন।"}'::jsonb, '{}'::jsonb, 3, -84, 730, '{}'::text[], 'any', ARRAY['breastfeeding', 'nursing', 'two years', 'father role', 'milk kinship']::text[], false, 'in_review'::lp_review_status, 9012),
  ('isl-every-one-a-shepherd', 'article', 'islamic', 'shared', 'educational', 'religious', '🐑', '{"en":"“Every one of you is a shepherd”: parenting as care, not control","bn":"“তোমরা প্রত্যেকেই রাখাল”: নিয়ন্ত্রণ নয়, যত্নের প্যারেন্টিং"}'::jsonb, '{"en":"The Prophet ﷺ compared responsibility to a shepherd caring for a flock. What that picture teaches mothers, fathers and every carer.","bn":"রাসূলুল্লাহ ﷺ দায়িত্বকে পাল আগলে রাখা রাখালের সাথে তুলনা করেছেন। এই ছবিটি মা, বাবা ও প্রত্যেক অভিভাবককে কী শেখায়।"}'::jsonb, '{"en":"## The hadith\n\nThe Prophet ﷺ said: every one of you is a shepherd, and every one of you is responsible for his flock. A man is a shepherd over his family and is responsible for them. A woman is a shepherd over her husband''s home and his children and is responsible for them (Sahih al-Bukhari and Sahih Muslim). The full hadith also names leaders and workers: everyone has someone in their care.\n\n## What a shepherd does\n\nThe Prophet ﷺ said that every prophet herded sheep, and that he too had done so (Sahih al-Bukhari). A good shepherd:\n\n- **Knows each one.** He notices which lamb is tired, which is limping, which wanders. Each child is different, so get to know yours.\n- **Leads from the front.** He walks the path first. Children follow what parents do more than what they say.\n- **Protects.** He keeps the flock away from danger. For parents this means safety at home, by water and on the road, and also protection online and from harmful people.\n- **Feeds and gives rest.** Food, sleep, play and health care are part of the trust.\n- **Is patient and gentle.** A shepherd does not beat the flock to move it. He guides it calmly, again and again.\n\n## Both parents are shepherds\n\nThe hadith names the father and the mother. Neither role is small. The father is not only the earner; his time, attention and gentleness matter. The mother is not only the carer; her wisdom and decisions matter. When one parent is absent, working abroad or has passed away, the other parent, grandparents or other carers take on this shepherding, and Allah sees their effort.\n\n## Responsible, not perfect\n\nBeing responsible does not mean controlling every thought your child has, or never making mistakes. It means doing your honest best, asking for help, saying sorry when you get it wrong, and leaving the results to Allah.\n\n## A shepherd also rests\n\nA tired, burnt-out shepherd cannot care for the flock. Share the load as a couple, accept help from family, pray, sleep when you can, and make time to recharge. Looking after yourself is part of looking after your children.\n\n## Try this week\n\nEach parent writes down one thing they notice about each child: something they love, something they find hard. Talk about it together and make a dua for each child by name.","bn":"## হাদিসটি\n\nরাসূলুল্লাহ ﷺ বলেছেন: তোমরা প্রত্যেকেই রাখাল (দায়িত্বশীল), আর প্রত্যেককে তার পালের ব্যাপারে জিজ্ঞেস করা হবে। পুরুষ তার পরিবারের রাখাল এবং তাদের ব্যাপারে দায়িত্বশীল। নারী তার স্বামীর ঘর ও সন্তানদের রাখাল এবং তাদের ব্যাপারে দায়িত্বশীল (সহিহ বুখারি ও সহিহ মুসলিম)। পুরো হাদিসে নেতা ও কর্মচারীর কথাও আছে: প্রত্যেকের অধীনেই কেউ না কেউ আছে।\n\n## রাখাল কী করে\n\nরাসূলুল্লাহ ﷺ বলেছেন, প্রত্যেক নবী ছাগল-ভেড়া চরিয়েছেন, তিনিও চরিয়েছেন (সহিহ বুখারি)। একজন ভালো রাখাল:\n\n- **প্রত্যেককে চেনে।** কোন ছানাটা ক্লান্ত, কোনটা খোঁড়াচ্ছে, কোনটা দলছুট — সে খেয়াল করে। প্রতিটি শিশু আলাদা, তাই নিজের সন্তানকে ভালো করে চিনুন।\n- **সামনে থেকে পথ দেখায়।** সে আগে হাঁটে। সন্তান বাবা-মায়ের কথার চেয়ে কাজকে বেশি অনুসরণ করে।\n- **রক্ষা করে।** বিপদ থেকে পালকে দূরে রাখে। বাবা-মায়ের জন্য এর মানে ঘরে, পানির কাছে ও রাস্তায় নিরাপত্তা, আর অনলাইনে ও ক্ষতিকর মানুষের হাত থেকেও সুরক্ষা।\n- **খাওয়ায় ও বিশ্রাম দেয়।** খাবার, ঘুম, খেলা ও চিকিৎসা — সবই আমানতের অংশ।\n- **ধৈর্যশীল ও কোমল।** পাল চালাতে রাখাল মারধর করে না। শান্তভাবে বারবার পথ দেখায়।\n\n## বাবা-মা দুজনেই রাখাল\n\nহাদিসে বাবা ও মা দুজনের কথাই এসেছে। কারও ভূমিকা ছোট নয়। বাবা শুধু উপার্জনকারী নন; তাঁর সময়, মনোযোগ ও কোমলতাও জরুরি। মা শুধু দেখাশোনাকারী নন; তাঁর বুদ্ধি ও সিদ্ধান্তও জরুরি। একজন অনুপস্থিত থাকলে, বিদেশে কাজ করলে বা মারা গেলে, অন্যজন, দাদা-দাদি, নানা-নানি বা অন্য অভিভাবক এই দায়িত্ব নেন — আর আল্লাহ তাঁদের চেষ্টা দেখেন।\n\n## দায়িত্বশীল, নিখুঁত নয়\n\nদায়িত্বশীল হওয়া মানে সন্তানের প্রতিটি চিন্তা নিয়ন্ত্রণ করা বা কখনো ভুল না করা নয়। এর মানে আন্তরিকভাবে সাধ্যমতো চেষ্টা করা, সাহায্য চাওয়া, ভুল হলে দুঃখিত বলা, আর ফলাফল আল্লাহর হাতে ছেড়ে দেওয়া।\n\n## রাখালেরও বিশ্রাম লাগে\n\nক্লান্ত, ভেঙে পড়া রাখাল পালের যত্ন নিতে পারে না। স্বামী-স্ত্রী মিলে কাজ ভাগ করুন, পরিবারের সাহায্য নিন, নামাজ পড়ুন, সুযোগমতো ঘুমান, আর নিজেকে চাঙা করার সময় রাখুন। নিজের যত্ন নেওয়াও সন্তানের যত্নের অংশ।\n\n## এই সপ্তাহে চেষ্টা করুন\n\nবাবা-মা দুজনেই প্রতিটি সন্তান সম্পর্কে একটি করে কথা লিখুন: তার কোন দিকটা ভালো লাগে, আর কোনটা কঠিন লাগে। একসাথে আলাপ করুন এবং প্রতিটি সন্তানের নাম ধরে দোয়া করুন।"}'::jsonb, '{}'::jsonb, 3, NULL, NULL, '{}'::text[], 'any', ARRAY['responsibility', 'shepherd', 'amanah', 'both parents', 'role']::text[], false, 'in_review'::lp_review_status, 9013),
  ('isl-mercy-to-children', 'article', 'islamic', 'shared', 'educational', 'religious', '💞', '{"en":"Mercy to children: how the Prophet ﷺ loved them","bn":"শিশুদের প্রতি দয়া: রাসূলুল্লাহ ﷺ যেভাবে তাদের ভালোবাসতেন"}'::jsonb, '{"en":"He kissed his grandchildren, played with little ones and shortened his prayer when a baby cried. Affection is not softness; it is Sunnah.","bn":"তিনি নাতিদের চুমু দিতেন, ছোটদের সাথে খেলতেন, শিশুর কান্না শুনে নামাজ সংক্ষেপ করতেন। আদর দুর্বলতা নয়; এটি সুন্নাহ।"}'::jsonb, '{"en":"Some people grow up thinking that a strict, distant parent is a good Muslim parent, especially a father. The Sunnah shows the opposite.\n\n## He kissed al-Hasan\n\nThe Prophet ﷺ kissed his grandson al-Hasan ibn ''Ali while al-Aqra'' ibn Habis was sitting with him. Al-Aqra'' said: I have ten children and I have never kissed any of them. The Prophet ﷺ looked at him and said: whoever does not show mercy will not be shown mercy (Sahih al-Bukhari and Sahih Muslim).\n\nWhen some Bedouins said, you kiss your children? We do not, he replied: what can I do for you if Allah has taken mercy out of your hearts? (Sahih al-Bukhari and Sahih Muslim).\n\n## Mercy in everyday moments\n\n- He would start a prayer meaning to make it long, then hear a baby crying and shorten it, knowing how worried the mother would be (Sahih al-Bukhari and Sahih Muslim).\n- He prayed while carrying his granddaughter Umamah, putting her down when he bowed and picking her up when he stood (Sahih al-Bukhari and Sahih Muslim).\n- A little boy, Abu ''Umayr, had a pet bird. When it died, the Prophet ﷺ would gently ask him about it, sharing in his small sorrow (Sahih al-Bukhari and Sahih Muslim).\n- Anas ibn Malik served him for ten years from boyhood and said the Prophet ﷺ never once said “uff” to him, nor asked why he did something or why he did not (Sahih al-Bukhari and Sahih Muslim).\n\nHe also said: whoever does not show mercy to our young and respect to our elders is not one of us (Jami'' at-Tirmidhi). And: Allah is gentle and loves gentleness in all things (Sahih al-Bukhari and Sahih Muslim).\n\n## What this looks like at home\n\n- Hug and kiss your children, sons as well as daughters, at every age they welcome it.\n- Fathers: carry the baby, play on the floor, give the bedtime cuddle. This is following the Sunnah, not losing respect.\n- Notice small sorrows: a broken toy, a lost game, a friend who was unkind.\n- Correct mistakes without shouting, insulting or shaming, especially in front of others.\n- Say “I love you” and “I am proud of you” in words your child understands.\n\nMercy does not mean no rules. It means rules given with warmth, and a home where children are never afraid of the people who love them most.","bn":"অনেকে বড় হয়েছেন এই ধারণা নিয়ে যে কঠোর, দূরত্ব রাখা বাবা-মা — বিশেষ করে বাবা — ই ভালো মুসলিম অভিভাবক। সুন্নাহ ঠিক উল্টোটা দেখায়।\n\n## তিনি হাসানকে চুমু দিয়েছিলেন\n\nরাসূলুল্লাহ ﷺ নাতি হাসান ইবনে আলী (রা.)-কে চুমু দিলেন, তখন আকরা ইবনে হাবিস তাঁর পাশে বসা ছিলেন। আকরা বললেন: আমার দশটি সন্তান, আমি তাদের কাউকে কখনো চুমু দিইনি। রাসূলুল্লাহ ﷺ তাঁর দিকে তাকিয়ে বললেন: যে দয়া করে না, তাকে দয়া করা হয় না (সহিহ বুখারি ও সহিহ মুসলিম)।\n\nকিছু বেদুইন যখন বলল, আপনারা কি শিশুদের চুমু দেন? আমরা তো দিই না — তিনি বললেন: আল্লাহ যদি তোমাদের অন্তর থেকে দয়া তুলে নেন, আমি তোমাদের জন্য কী করতে পারি? (সহিহ বুখারি ও সহিহ মুসলিম)।\n\n## প্রতিদিনের মুহূর্তে দয়া\n\n- তিনি লম্বা করার নিয়তে নামাজ শুরু করতেন, তারপর শিশুর কান্না শুনে সংক্ষেপ করতেন, কারণ জানতেন মা কতটা অস্থির হবেন (সহিহ বুখারি ও সহিহ মুসলিম)।\n- তিনি নাতনি উমামাকে কোলে নিয়ে নামাজ পড়েছেন — রুকুতে নামিয়ে রাখতেন, দাঁড়ালে আবার তুলে নিতেন (সহিহ বুখারি ও সহিহ মুসলিম)।\n- আবু উমাইর নামে এক ছোট ছেলের একটি পোষা পাখি ছিল। পাখিটি মারা গেলে রাসূলুল্লাহ ﷺ আদর করে তাকে পাখির কথা জিজ্ঞেস করতেন, তার ছোট্ট দুঃখে শরিক হতেন (সহিহ বুখারি ও সহিহ মুসলিম)।\n- আনাস ইবনে মালিক (রা.) ছোটবেলা থেকে দশ বছর তাঁর খেদমত করেছেন। তিনি বলেছেন, রাসূলুল্লাহ ﷺ কখনো তাঁকে “উফ” বলেননি, কোনো কাজ কেন করলে বা কেন করলে না, তা-ও বলেননি (সহিহ বুখারি ও সহিহ মুসলিম)।\n\nতিনি আরও বলেছেন: যে আমাদের ছোটদের দয়া করে না এবং বড়দের সম্মান করে না, সে আমাদের দলভুক্ত নয় (জামে তিরমিজি)। আর: আল্লাহ কোমল, তিনি সব বিষয়ে কোমলতা পছন্দ করেন (সহিহ বুখারি ও সহিহ মুসলিম)।\n\n## ঘরে এর চেহারা\n\n- সন্তানকে জড়িয়ে ধরুন, চুমু দিন — মেয়েকেও, ছেলেকেও — যে বয়সে সে তা পছন্দ করে।\n- বাবারা: শিশুকে কোলে নিন, মেঝেতে বসে খেলুন, ঘুমের আগে আদর করুন। এতে সম্মান কমে না, বরং সুন্নাহ পালন হয়।\n- ছোট দুঃখগুলো খেয়াল করুন: ভাঙা খেলনা, হেরে যাওয়া খেলা, বন্ধুর খারাপ ব্যবহার।\n- চিৎকার, গালি বা লজ্জা না দিয়ে ভুল শুধরে দিন, বিশেষ করে অন্যদের সামনে।\n- সন্তান বোঝে এমন ভাষায় বলুন “তোমাকে ভালোবাসি”, “তোমাকে নিয়ে আমি গর্বিত”।\n\nদয়া মানে নিয়ম না থাকা নয়। এর মানে উষ্ণতার সাথে নিয়ম, আর এমন একটি ঘর যেখানে শিশু তাকে সবচেয়ে বেশি ভালোবাসে এমন মানুষদের কখনো ভয় পায় না।"}'::jsonb, '{}'::jsonb, 3, 0, NULL, '{}'::text[], 'any', ARRAY['mercy', 'affection', 'kissing', 'hugging', 'gentleness', 'fathers']::text[], false, 'in_review'::lp_review_status, 9014),
  ('isl-justice-between-children', 'article', 'islamic', 'shared', 'educational', 'religious', '⚖️', '{"en":"Justice between your children","bn":"সন্তানদের মধ্যে ইনসাফ"}'::jsonb, '{"en":"“Fear Allah and be just between your children.” What fairness means with sons and daughters, older and younger, and children with different needs.","bn":"“আল্লাহকে ভয় করো এবং সন্তানদের মধ্যে ইনসাফ করো।” ছেলে-মেয়ে, বড়-ছোট আর ভিন্ন প্রয়োজনের সন্তানদের মধ্যে ন্যায্যতা মানে কী।"}'::jsonb, '{"en":"## The hadith of an-Nu''man ibn Bashir\n\nWhen an-Nu''man ibn Bashir was a boy, his father gave him a gift. His mother asked that the Prophet ﷺ be made a witness to it. So his father went to the Prophet ﷺ, who asked: have you given the same to all your children? He said no. The Prophet ﷺ said: fear Allah and be just between your children. His father went back and took the gift back (Sahih al-Bukhari and Sahih Muslim).\n\nThe Prophet ﷺ cared that a child should not feel less loved than a brother or sister.\n\n## What happens when a child feels less loved\n\nThe story of Yusuf (peace be upon him) begins with his brothers saying that Yusuf and his brother were more loved by their father than they were (Surah Yusuf 12:8). Their jealousy grew into something terrible. Even the feeling of unfairness can hurt a family deeply.\n\n## Fair does not always mean the same\n\n- **Gifts and money:** give fairly. Scholars agree on being fair; they differ on whether sons and daughters should get exactly equal gifts or follow the shares of inheritance. Ask a trusted scholar if you are giving large gifts such as land.\n- **Needs:** a baby needs more time, a sick child needs more care, a child with a disability may need more support. That is justice, not favouritism. Explain it kindly to the others.\n- **Love and attention:** you may feel closer to one child at times. That is human. What matters is that your words, time and affection are shared.\n\n## Common traps in our homes\n\n- Comparing: “Look at your cousin''s results,” or “Why can''t you be like your brother?”\n- Letting sons rest while daughters do all the housework, or giving sons the better food.\n- Praising the clever or fair-skinned child in front of guests.\n- Always blaming the older child in a fight.\n\n## What helps\n\n- Spend a little one-to-one time with each child, even ten minutes.\n- Praise effort and character, not only marks or looks.\n- Share chores between sons and daughters.\n- When siblings fight, listen to both before deciding.\n- If a child says “you love him more,” do not argue. Listen, hug, and show your love in action.","bn":"## নুমান ইবনে বাশির (রা.)-এর হাদিস\n\nনুমান ইবনে বাশির (রা.) যখন ছোট, তাঁর বাবা তাঁকে একটি উপহার দিলেন। তাঁর মা চাইলেন রাসূলুল্লাহ ﷺ-কে এর সাক্ষী বানানো হোক। বাবা রাসূলুল্লাহ ﷺ-এর কাছে গেলে তিনি জিজ্ঞেস করলেন: তুমি কি তোমার সব সন্তানকে এমন দিয়েছ? তিনি বললেন, না। রাসূলুল্লাহ ﷺ বললেন: আল্লাহকে ভয় করো এবং তোমার সন্তানদের মধ্যে ইনসাফ করো। তাঁর বাবা ফিরে গিয়ে উপহারটি ফেরত নিলেন (সহিহ বুখারি ও সহিহ মুসলিম)।\n\nকোনো সন্তান যেন ভাই বা বোনের চেয়ে নিজেকে কম ভালোবাসার পাত্র মনে না করে — রাসূলুল্লাহ ﷺ এ বিষয়ে যত্নশীল ছিলেন।\n\n## সন্তান নিজেকে কম প্রিয় ভাবলে কী হয়\n\nইউসুফ (আ.)-এর ঘটনা শুরু হয় তাঁর ভাইদের এই কথা দিয়ে যে, ইউসুফ ও তার ভাই আমাদের চেয়ে বাবার কাছে বেশি প্রিয় (সূরা ইউসুফ ১২:৮)। তাদের হিংসা ভয়ংকর রূপ নেয়। অন্যায়ের অনুভূতিটুকুও একটি পরিবারকে গভীরভাবে আঘাত করতে পারে।\n\n## ন্যায্য মানে সবসময় একরকম নয়\n\n- **উপহার ও টাকা:** ন্যায্যভাবে দিন। ইনসাফের ব্যাপারে আলেমরা একমত; তবে ছেলে-মেয়েকে হুবহু সমান উপহার দিতে হবে নাকি মিরাসের অংশ অনুযায়ী, তা নিয়ে মতভেদ আছে। জমির মতো বড় উপহার দিলে বিশ্বস্ত আলেমকে জিজ্ঞেস করুন।\n- **প্রয়োজন:** শিশুর বেশি সময় লাগে, অসুস্থ সন্তানের বেশি যত্ন লাগে, প্রতিবন্ধী সন্তানের বেশি সহায়তা লাগতে পারে। এটা ইনসাফ, পক্ষপাত নয়। অন্যদের আদর করে বুঝিয়ে বলুন।\n- **ভালোবাসা ও মনোযোগ:** কখনো কোনো সন্তানের প্রতি বেশি টান অনুভব করতে পারেন। এটা মানবিক। আসল কথা হলো আপনার কথা, সময় আর আদর যেন সবাই পায়।\n\n## আমাদের ঘরের পরিচিত ফাঁদ\n\n- তুলনা: “দেখো তোমার কাজিনের রেজাল্ট,” বা “ভাইয়ের মতো হতে পারো না কেন?”\n- ছেলেরা বিশ্রাম নেয় আর মেয়েরা সব কাজ করে, বা ছেলেদের ভালো খাবার দেওয়া।\n- অতিথিদের সামনে মেধাবী বা ফর্সা সন্তানের প্রশংসা।\n- ঝগড়া হলে সবসময় বড় সন্তানকে দোষ দেওয়া।\n\n## যা সাহায্য করে\n\n- প্রতিটি সন্তানের সাথে আলাদা করে একটু সময় কাটান, দশ মিনিট হলেও।\n- শুধু নম্বর বা চেহারা নয়, চেষ্টা ও চরিত্রের প্রশংসা করুন।\n- ছেলে-মেয়ের মধ্যে ঘরের কাজ ভাগ করে দিন।\n- ভাই-বোন ঝগড়া করলে সিদ্ধান্ত নেওয়ার আগে দুজনের কথাই শুনুন।\n- সন্তান যদি বলে “তুমি ওকে বেশি ভালোবাসো,” তর্ক করবেন না। শুনুন, জড়িয়ে ধরুন, আর কাজে ভালোবাসা দেখান।"}'::jsonb, '{}'::jsonb, 3, 730, NULL, '{}'::text[], 'any', ARRAY['fairness', 'justice', 'siblings', 'favouritism', 'comparison', 'jealousy']::text[], false, 'in_review'::lp_review_status, 9015),
  ('isl-luqman-advice', 'article', 'islamic', 'shared', 'educational', 'religious', '🧔', '{"en":"Luqman''s advice to his son: a parenting model from the Quran","bn":"ছেলের প্রতি লুকমানের উপদেশ: কুরআনের প্যারেন্টিং মডেল"}'::jsonb, '{"en":"Surah Luqman 31:13–19 records a father''s advice to his son. Look at what he taught, and also how he said it.","bn":"সূরা লুকমান ৩১:১৩–১৯-এ ছেলের প্রতি এক বাবার উপদেশ আছে। তিনি কী শিখিয়েছেন, আর কীভাবে বলেছেন — দুটোই দেখার মতো।"}'::jsonb, '{"en":"Allah calls Luqman wise (Surah Luqman 31:12) and records his advice to his son. It is a complete short course in raising a child.\n\n## How he spoke: “Ya bunayya”\n\nLuqman calls his son **يَا بُنَيَّ (ya bunayya)**, an affectionate way to say “my dear son”. Every piece of advice starts with love. Before you correct or teach, let your child hear that they are dear to you.\n\n## What he taught, step by step\n\n1. **Faith first (31:13).** Do not associate anything with Allah; that is a great wrong. He starts with the foundation, not with rules.\n2. **Parents (31:14–15).** Here Allah''s own words come in: be grateful to Allah and to your parents; your mother carried you with hardship. If parents push you to associate others with Allah, do not obey that, but still keep their company in this world with kindness.\n3. **Allah knows everything (31:16).** Even a deed the weight of a mustard seed, inside a rock or anywhere in the heavens or earth, Allah will bring it out. He is Subtle and Aware. This builds a conscience: doing right even when no one is watching.\n4. **Prayer, good and patience (31:17).** Keep up the prayer, encourage what is right, discourage what is wrong, and be patient with what befalls you.\n5. **Humility (31:18).** Do not turn your face away from people in pride, and do not walk on the earth arrogantly. Allah does not love the proud boaster.\n6. **Manners (31:19).** Be moderate in your walk and lower your voice. The harshest of sounds is the braying of a donkey.\n\n## Lessons for parents\n\n- **Start with love and meaning.** Faith in Allah gives every rule its reason.\n- **Explain why.** Luqman gives reasons, not just orders.\n- **Teach conscience, not fear.** “Allah sees” is a comfort and a guide, not a threat to scare children with.\n- **Big things and small things.** He moves from belief to prayer to how to walk and speak. Daily manners are part of faith.\n- **Respect does not mean blind obedience.** Even parents must not be obeyed in wrongdoing, but must still be treated kindly.\n- **Practise what you teach.** A raised voice telling a child to lower their voice does not work.\n\n## Try this\n\nRead one verse with your child each week, in Arabic or translation. Ask: what is Luqman asking here? Why do you think it matters? Let your child give an example from their own day.","bn":"আল্লাহ লুকমানকে প্রজ্ঞাবান বলেছেন (সূরা লুকমান ৩১:১২) এবং ছেলের প্রতি তাঁর উপদেশ কুরআনে রেখে দিয়েছেন। এটি সন্তান মানুষ করার একটি পূর্ণাঙ্গ ছোট পাঠ।\n\n## তিনি কীভাবে বলতেন: “ইয়া বুনাইয়্যা”\n\nলুকমান ছেলেকে ডাকেন **يَا بُنَيَّ (ইয়া বুনাইয়্যা)** বলে — আদর করে “আমার প্রিয় ছেলে”। প্রতিটি উপদেশ শুরু হয় ভালোবাসা দিয়ে। শুধরে দেওয়া বা শেখানোর আগে সন্তানকে শুনতে দিন যে সে আপনার প্রিয়।\n\n## তিনি ধাপে ধাপে কী শিখিয়েছেন\n\n1. **আগে ঈমান (৩১:১৩)।** আল্লাহর সাথে কাউকে শরিক কোরো না; এটা বড় জুলুম। তিনি নিয়ম দিয়ে নয়, ভিত্তি দিয়ে শুরু করেছেন।\n2. **বাবা-মা (৩১:১৪–১৫)।** এখানে আল্লাহর নিজের কথা এসেছে: আল্লাহর ও বাবা-মায়ের প্রতি কৃতজ্ঞ হও; মা কষ্ট করে তোমাকে গর্ভে ধারণ করেছেন। বাবা-মা যদি আল্লাহর সাথে শরিক করতে চাপ দেন, সে কথা মানবে না, তবু দুনিয়াতে তাঁদের সাথে সদ্ভাবে থাকবে।\n3. **আল্লাহ সব জানেন (৩১:১৬)।** সরিষার দানা পরিমাণ কোনো কাজ যদি পাথরের ভেতরে বা আসমান-জমিনের কোথাও থাকে, আল্লাহ তা বের করে আনবেন। তিনি সূক্ষ্মদর্শী, সব খবর রাখেন। এতে বিবেক তৈরি হয়: কেউ না দেখলেও ঠিক কাজ করা।\n4. **নামাজ, সৎকাজ ও ধৈর্য (৩১:১৭)।** নামাজ কায়েম করো, ভালো কাজে উৎসাহ দাও, মন্দ কাজে বাধা দাও, আর বিপদে ধৈর্য ধরো।\n5. **বিনয় (৩১:১৮)।** অহংকারে মানুষের দিক থেকে মুখ ফিরিয়ে নিয়ো না, পৃথিবীতে দম্ভভরে হেঁটো না। আল্লাহ দাম্ভিক অহংকারীকে পছন্দ করেন না।\n6. **আদব (৩১:১৯)।** চলাফেরায় মধ্যম পন্থা অবলম্বন করো, কণ্ঠস্বর নিচু রাখো। সবচেয়ে অপ্রীতিকর আওয়াজ গাধার আওয়াজ।\n\n## বাবা-মায়ের জন্য শিক্ষা\n\n- **ভালোবাসা ও অর্থ দিয়ে শুরু করুন।** আল্লাহর প্রতি ঈমানই প্রতিটি নিয়মের কারণ বুঝিয়ে দেয়।\n- **কারণ বুঝিয়ে বলুন।** লুকমান শুধু আদেশ দেননি, কারণও বলেছেন।\n- **ভয় নয়, বিবেক শেখান।** “আল্লাহ দেখছেন” কথাটি সান্ত্বনা ও পথনির্দেশ, শিশুকে ভয় দেখানোর হুমকি নয়।\n- **বড় বিষয়, ছোট বিষয়।** তিনি ঈমান থেকে নামাজ, তারপর হাঁটা ও কথা বলার ধরনে গেছেন। প্রতিদিনের আদবও ঈমানের অংশ।\n- **সম্মান মানে অন্ধ আনুগত্য নয়।** অন্যায় কাজে বাবা-মাকেও মানা যাবে না, তবু তাঁদের সাথে সদ্ব্যবহার করতে হবে।\n- **যা শেখান, নিজে করুন।** চিৎকার করে সন্তানকে আস্তে কথা বলতে বললে কাজ হয় না।\n\n## চেষ্টা করুন\n\nপ্রতি সপ্তাহে সন্তানের সাথে একটি আয়াত পড়ুন, আরবিতে বা অনুবাদে। জিজ্ঞেস করুন: লুকমান এখানে কী বলছেন? তোমার কী মনে হয়, এটা কেন জরুরি? সন্তানকে তার নিজের দিনের একটি উদাহরণ দিতে দিন।"}'::jsonb, '{}'::jsonb, 4, 1096, 7305, '{}'::text[], 'any', ARRAY['luqman', 'advice', 'quran', 'character', 'tawhid', 'manners']::text[], false, 'in_review'::lp_review_status, 9016),
  ('isl-kindness-to-parents', 'article', 'islamic', 'family', 'educational', 'religious', '👵', '{"en":"Kindness to parents, and the dua “Rabbir-hamhuma”","bn":"বাবা-মায়ের প্রতি সদ্ব্যবহার এবং “রব্বির হামহুমা” দোয়া"}'::jsonb, '{"en":"Surah Al-Isra 17:23–24 places kindness to parents right after worshipping Allah. Children learn it best by watching how you treat their grandparents.","bn":"সূরা আল-ইসরা ১৭:২৩–২৪ আল্লাহর ইবাদতের ঠিক পরেই বাবা-মায়ের প্রতি সদ্ব্যবহারের কথা বলেছে। সন্তান এটা সবচেয়ে ভালো শেখে, আপনি তার দাদা-দাদি বা নানা-নানির সাথে কেমন আচরণ করেন তা দেখে।"}'::jsonb, '{"en":"## The verses\n\nYour Lord has commanded that you worship none but Him, and that you be kind to your parents. If one or both of them reach old age with you, do not say even “uff” to them, do not push them away, and speak to them with honour. Lower to them the wing of humility out of mercy, and say: (Surah Al-Isra 17:23–24)\n\nرَّبِّ ارْحَمْهُمَا كَمَا رَبَّيَانِي صَغِيرًا\n\n**Rabbir-hamhuma kama rabbayani saghira.**\n\nMeaning: My Lord, have mercy on them both, as they raised me when I was small. (Surah Al-Isra 17:24)\n\n## A high place in Islam\n\n- These verses put kindness to parents right after the worship of Allah.\n- A man came wanting to go out and fight in the way of Allah. The Prophet ﷺ asked if his parents were alive. When he said yes, the Prophet ﷺ told him to strive in serving them (Sahih al-Bukhari and Sahih Muslim).\n- When asked who most deserves good company, he said: your mother, three times, then your father (Sahih al-Bukhari and Sahih Muslim).\n\n## How children learn it\n\nChildren will treat you the way they see you treat your own parents.\n\n- Let them see you call your parents, visit them, and speak gently to them, even when they are difficult.\n- Give children small roles: bringing water to Dadi, reading to Nana, helping an older relative to walk.\n- Teach them the dua above. Say it together after salah or at bedtime, for both sets of grandparents and for yourselves.\n- If a grandparent has passed away, make dua for them as a family and talk about their good qualities.\n\n## Respect with wisdom\n\nKindness to parents does not mean obeying them in something wrong (Surah Luqman 31:15), and it does not mean a parent can hurt a child. It means honour, gentle words and care, especially in old age.\n\n## For parents of young children\n\nYou do not need to demand respect with fear. Children who feel loved and respected usually grow up to love and respect their parents. A warm relationship now is the best preparation for the day you are old and need their gentleness.","bn":"## আয়াতগুলো\n\nতোমার রব আদেশ দিয়েছেন, তোমরা তিনি ছাড়া কারও ইবাদত করবে না এবং বাবা-মায়ের সাথে সদ্ব্যবহার করবে। তাঁদের একজন বা দুজনই যদি তোমার কাছে বার্ধক্যে পৌঁছান, তাঁদের “উফ” পর্যন্ত বোলো না, ধমক দিয়ো না, আর তাঁদের সাথে সম্মানের সাথে কথা বলো। দয়ায় তাঁদের প্রতি বিনয়ের ডানা নামিয়ে দাও এবং বলো: (সূরা আল-ইসরা ১৭:২৩–২৪)\n\nرَّبِّ ارْحَمْهُمَا كَمَا رَبَّيَانِي صَغِيرًا\n\n**উচ্চারণ: রব্বির হামহুমা কামা রব্বাইয়ানি সাগিরা।**\n\nঅর্থ: হে আমার রব, তাঁদের দুজনের প্রতি দয়া করুন, যেভাবে তাঁরা ছোটবেলায় আমাকে লালন-পালন করেছেন। (সূরা আল-ইসরা ১৭:২৪)\n\n## ইসলামে উঁচু মর্যাদা\n\n- এই আয়াতগুলো আল্লাহর ইবাদতের ঠিক পরেই বাবা-মায়ের প্রতি সদ্ব্যবহারের কথা বলেছে।\n- এক ব্যক্তি আল্লাহর পথে যুদ্ধে যেতে চেয়ে এসেছিল। রাসূলুল্লাহ ﷺ জিজ্ঞেস করলেন, তোমার বাবা-মা কি বেঁচে আছেন? সে বলল, হ্যাঁ। তিনি বললেন, তাহলে তাঁদের খেদমতে চেষ্টা করো (সহিহ বুখারি ও সহিহ মুসলিম)।\n- সদ্ব্যবহারের সবচেয়ে বেশি হকদার কে — জিজ্ঞেস করা হলে তিনি তিনবার বলেছেন তোমার মা, তারপর তোমার বাবা (সহিহ বুখারি ও সহিহ মুসলিম)।\n\n## সন্তান কীভাবে শেখে\n\nআপনি নিজের বাবা-মায়ের সাথে কেমন আচরণ করেন, সন্তান আপনার সাথে তেমনই করবে।\n\n- তারা দেখুক আপনি বাবা-মাকে ফোন করছেন, দেখতে যাচ্ছেন, আর তাঁরা কঠিন হলেও নরম করে কথা বলছেন।\n- সন্তানকে ছোট ছোট দায়িত্ব দিন: দাদিকে পানি এনে দেওয়া, নানাকে পড়ে শোনানো, বয়স্ক আত্মীয়কে হাঁটতে সাহায্য করা।\n- ওপরের দোয়াটি শেখান। নামাজের পর বা ঘুমানোর আগে দুই পক্ষের দাদা-দাদি, নানা-নানি ও নিজেদের জন্য একসাথে পড়ুন।\n- দাদা-দাদি বা নানা-নানি মারা গিয়ে থাকলে পরিবার মিলে তাঁদের জন্য দোয়া করুন এবং তাঁদের ভালো গুণগুলোর গল্প বলুন।\n\n## প্রজ্ঞার সাথে সম্মান\n\nবাবা-মায়ের প্রতি সদ্ব্যবহার মানে অন্যায় কাজে তাঁদের মানা নয় (সূরা লুকমান ৩১:১৫), আর এর মানে এটাও নয় যে বাবা-মা সন্তানকে কষ্ট দিতে পারেন। এর মানে সম্মান, নরম কথা ও যত্ন — বিশেষ করে বার্ধক্যে।\n\n## ছোট সন্তানের বাবা-মায়ের জন্য\n\nভয় দেখিয়ে সম্মান আদায়ের দরকার নেই। যে সন্তান ভালোবাসা ও সম্মান পায়, সে সাধারণত বড় হয়ে বাবা-মাকে ভালোবাসে ও সম্মান করে। আজকের উষ্ণ সম্পর্কই সেই দিনের সবচেয়ে ভালো প্রস্তুতি, যেদিন আপনি বৃদ্ধ হবেন এবং তার কোমলতার প্রয়োজন হবে।"}'::jsonb, '{}'::jsonb, 3, 1461, 7305, '{}'::text[], 'any', ARRAY['parents', 'grandparents', 'birr al walidayn', 'respect', 'dua']::text[], false, 'in_review'::lp_review_status, 9017),
  ('isl-truthfulness', 'article', 'islamic', 'shared', 'educational', 'religious', '🤝', '{"en":"Raising a truthful child","bn":"সত্যবাদী সন্তান গড়ে তোলা"}'::jsonb, '{"en":"Truthfulness leads to goodness. Children learn it from parents who keep promises, never lie to them, and make it safe to tell the truth.","bn":"সত্য কল্যাণের পথ দেখায়। সন্তান তা শেখে এমন বাবা-মায়ের কাছ থেকে, যাঁরা কথা রাখেন, তাকে মিথ্যা বলেন না, আর সত্য বলাকে নিরাপদ করে তোলেন।"}'::jsonb, '{"en":"## Why truth matters so much\n\nThe Prophet ﷺ said: truthfulness leads to righteousness, and righteousness leads to Paradise. A person keeps telling the truth until they are recorded with Allah as truthful. Lying leads to wrongdoing, and wrongdoing leads to the Fire (Sahih al-Bukhari and Sahih Muslim).\n\nAllah says: O you who believe, be mindful of Allah and be with the truthful (Surah At-Tawbah 9:119). Even before prophethood, the people of Makkah called Muhammad ﷺ al-Amin, the trustworthy.\n\n## Do not lie to children, even small lies\n\n''Abdullah ibn ''Amir said that when he was a boy, his mother called him: come here, I will give you something. The Prophet ﷺ, who was in their house, asked her what she meant to give. She said a date. He said: if you had not given him anything, it would have been written against you as a lie (Sunan Abi Dawud).\n\nThink of the small lies adults often tell children:\n\n- “The injection won''t hurt at all.”\n- “If you don''t sleep, the police will take you.”\n- “I''ll buy it tomorrow,” with no plan to.\n- “Tell them I''m not home.”\n\nEach one teaches a child that lying is normal. Say instead: “It will hurt a little, and I will hold you.” Make fewer promises, and keep the ones you make.\n\n## Make telling the truth safe\n\nIf a child is punished harshly every time they admit a mistake, they learn to hide. When your child confesses:\n\n- Thank them first: “Thank you for telling me the truth. That took courage.”\n- Then deal with the problem calmly, and help them fix it.\n- Avoid traps: if you already know they broke the cup, do not ask “Who broke this?” Say “I see the cup broke. Let''s clean it together.”\n\n## Understand their age\n\nLittle children of three or four mix imagination and reality. A story about a dragon in the garden is play, not a sin. Gently show the difference: “That''s a fun story! What really happened?”\n\n## Daily practice\n\n- Praise honesty out loud when you see it.\n- Tell stories of truthful people, like the Prophet ﷺ being called al-Amin.\n- Admit your own mistakes: “I was wrong, I''m sorry.” It teaches that truth is stronger than pride.","bn":"## সত্য কেন এত জরুরি\n\nরাসূলুল্লাহ ﷺ বলেছেন: সত্য নেককাজের পথ দেখায়, আর নেককাজ জান্নাতের পথ দেখায়। মানুষ সত্য বলতে থাকে, অবশেষে আল্লাহর কাছে সত্যবাদী হিসেবে লেখা হয়। মিথ্যা পাপের পথ দেখায়, আর পাপ জাহান্নামের পথ দেখায় (সহিহ বুখারি ও সহিহ মুসলিম)।\n\nআল্লাহ বলেন: হে মুমিনগণ, আল্লাহকে ভয় করো এবং সত্যবাদীদের সাথে থাকো (সূরা আত-তাওবা ৯:১১৯)। নবুওয়াতের আগেই মক্কার মানুষ মুহাম্মাদ ﷺ-কে আল-আমিন, অর্থাৎ বিশ্বস্ত বলে ডাকত।\n\n## শিশুকে মিথ্যা বলবেন না, ছোট মিথ্যাও না\n\nআবদুল্লাহ ইবনে আমির (রা.) বলেছেন, তিনি ছোট থাকতে তাঁর মা তাঁকে ডাকলেন: এসো, তোমাকে একটা জিনিস দেব। রাসূলুল্লাহ ﷺ তখন তাঁদের ঘরে ছিলেন। তিনি জিজ্ঞেস করলেন, তুমি তাকে কী দিতে চেয়েছ? মা বললেন, একটি খেজুর। তিনি বললেন: যদি তুমি তাকে কিছু না দিতে, তাহলে তোমার নামে একটি মিথ্যা লেখা হতো (সুনান আবু দাউদ)।\n\nবড়রা শিশুদের প্রায়ই যে ছোট মিথ্যাগুলো বলেন, ভাবুন:\n\n- “ইনজেকশনে একটুও ব্যথা লাগবে না।”\n- “না ঘুমালে পুলিশ ধরে নিয়ে যাবে।”\n- “কাল কিনে দেব,” অথচ কেনার কোনো ইচ্ছা নেই।\n- “বলো আমি বাসায় নেই।”\n\nপ্রতিটি কথা শিশুকে শেখায় মিথ্যা বলা স্বাভাবিক। বরং বলুন: “একটু ব্যথা লাগবে, আমি তোমাকে ধরে রাখব।” কম প্রতিশ্রুতি দিন, আর যা দেন তা রাখুন।\n\n## সত্য বলাকে নিরাপদ করুন\n\nভুল স্বীকার করলেই যদি কঠোর শাস্তি পায়, শিশু লুকাতে শেখে। সন্তান যখন স্বীকার করে:\n\n- আগে ধন্যবাদ দিন: “সত্যি বলার জন্য ধন্যবাদ। এতে সাহস লাগে।”\n- তারপর শান্তভাবে সমস্যাটা সামলান এবং ঠিক করতে সাহায্য করুন।\n- ফাঁদ পাতবেন না: আপনি যদি জানেন সে কাপ ভেঙেছে, “কে ভাঙল?” জিজ্ঞেস না করে বলুন, “দেখছি কাপটা ভেঙে গেছে। চলো একসাথে পরিষ্কার করি।”\n\n## বয়সটা বুঝুন\n\nতিন-চার বছরের শিশুরা কল্পনা আর বাস্তব মিশিয়ে ফেলে। বাগানে ড্রাগনের গল্প খেলা, গুনাহ নয়। আলতো করে পার্থক্য দেখান: “দারুণ গল্প! আসলে কী হয়েছিল?”\n\n## প্রতিদিনের চর্চা\n\n- সততা দেখলে মুখে প্রশংসা করুন।\n- সত্যবাদী মানুষের গল্প বলুন, যেমন রাসূলুল্লাহ ﷺ-কে আল-আমিন ডাকা হতো।\n- নিজের ভুল স্বীকার করুন: “আমার ভুল হয়েছে, দুঃখিত।” এতে শেখে যে সত্য অহংকারের চেয়ে শক্তিশালী।"}'::jsonb, '{}'::jsonb, 3, 1096, 7305, '{}'::text[], 'any', ARRAY['truthfulness', 'honesty', 'lying', 'promises', 'trust']::text[], false, 'in_review'::lp_review_status, 9018),
  ('isl-dua-for-your-children', 'article', 'islamic', 'shared', 'educational', 'religious', '🤲', '{"en":"Making dua for your children","bn":"সন্তানের জন্য দোয়া"}'::jsonb, '{"en":"A parent''s dua for a child is answered, so guard your words, especially in anger. Duas from the Quran and Sunnah, and simple times to say them.","bn":"সন্তানের জন্য বাবা-মায়ের দোয়া কবুল হয়, তাই কথার ব্যাপারে সাবধান থাকুন — বিশেষ করে রাগের সময়। কুরআন ও সুন্নাহর দোয়া, আর পড়ার সহজ সময়।"}'::jsonb, '{"en":"## A powerful gift\n\nThe Prophet ﷺ said that three duas are answered without doubt: the dua of the one who has been wronged, the dua of the traveller, and the dua of a parent for their child (Sunan Abi Dawud, Jami'' at-Tirmidhi, Al-Adab al-Mufrad).\n\nThe other side of this is a warning given with love. He said: do not make dua against yourselves, your children or your wealth, in case it matches a moment when Allah grants what is asked (Sahih Muslim). In anger, many of us say hurtful things to children. Train your tongue instead to say: “May Allah guide you,” or “May Allah make you good.”\n\n## Duas from the Quran\n\nوَأَصْلِحْ لِي فِي ذُرِّيَّتِي\n\n**Wa aslih li fi dhurriyyati.**\n\nMeaning: And make my children righteous for me. (Surah Al-Ahqaf 46:15)\n\nYou can also say the duas of Ibrahim (14:40) and of the servants of the Most Merciful (25:74), found in our guide on duas for righteous children.\n\n## A dua of protection from the Sunnah\n\nThe Prophet ﷺ used to seek protection for his grandsons al-Hasan and al-Husayn with these words, and said that Ibrahim (peace be upon him) used to say them for his sons Isma''il and Ishaq (Sahih al-Bukhari):\n\nأُعِيذُكُمَا بِكَلِمَاتِ اللَّهِ التَّامَّةِ مِنْ كُلِّ شَيْطَانٍ وَهَامَّةٍ وَمِنْ كُلِّ عَيْنٍ لَامَّةٍ\n\n**U''idhukuma bi kalimatillahit-tammah, min kulli shaytanin wa hammah, wa min kulli ''aynin lammah.**\n\nMeaning: I seek protection for you both in the perfect words of Allah, from every devil and every harmful creature, and from every evil eye. This form is for two children; many families adapt the ending for one child. Ask a scholar if you want to learn the exact forms.\n\n## The Prophet''s ﷺ dua for a young boy\n\nHe prayed for the young Ibn ''Abbas: O Allah, give him understanding of the religion (Sahih al-Bukhari). Ask for your children what matters most: faith, wisdom, good character and good health.\n\n## Simple times to make dua\n\n- After each salah, name each child.\n- While they sleep, with a hand on their head.\n- When they leave for school or an exam.\n- In the last part of the night if you wake to feed a baby.\n- In front of them sometimes, so they hear how much you care.\n\nYou do not need perfect Arabic. Speak to Allah in Bangla, English or any language, from the heart. Keep making dua even when a child is going through a hard time. It is one thing no parent ever runs out of.","bn":"## এক শক্তিশালী উপহার\n\nরাসূলুল্লাহ ﷺ বলেছেন, তিনটি দোয়া নিঃসন্দেহে কবুল হয়: মজলুমের দোয়া, মুসাফিরের দোয়া এবং সন্তানের জন্য বাবা-মায়ের দোয়া (সুনান আবু দাউদ, জামে তিরমিজি, আল-আদাবুল মুফরাদ)।\n\nএর অন্য দিকটি ভালোবাসার সাথে দেওয়া একটি সতর্কতা। তিনি বলেছেন: নিজেদের, সন্তানদের বা সম্পদের বিরুদ্ধে বদদোয়া কোরো না; হয়তো তা এমন মুহূর্তে মিলে যাবে যখন আল্লাহ চাওয়া জিনিস দিয়ে দেন (সহিহ মুসলিম)। রাগের মাথায় আমরা অনেকেই সন্তানকে কষ্টদায়ক কথা বলে ফেলি। তার বদলে জিহ্বাকে অভ্যস্ত করুন: “আল্লাহ তোমাকে হেদায়েত দিন,” বা “আল্লাহ তোমাকে ভালো মানুষ বানান।”\n\n## কুরআনের দোয়া\n\nوَأَصْلِحْ لِي فِي ذُرِّيَّتِي\n\n**উচ্চারণ: ওয়া আসলিহ লি ফি যুররিয়্যাতি।**\n\nঅর্থ: আর আমার জন্য আমার সন্তানদের নেককার বানিয়ে দিন। (সূরা আল-আহকাফ ৪৬:১৫)\n\nইবরাহিম (আ.)-এর দোয়া (১৪:৪০) এবং রহমানের বান্দাদের দোয়াও (২৫:৭৪) পড়তে পারেন — “নেক সন্তানের জন্য কুরআনের দোয়া” লেখায় পাবেন।\n\n## সুন্নাহ থেকে সুরক্ষার দোয়া\n\nরাসূলুল্লাহ ﷺ নাতি হাসান ও হুসাইন (রা.)-এর জন্য এই কথাগুলো দিয়ে আল্লাহর আশ্রয় চাইতেন, এবং বলেছেন ইবরাহিম (আ.) তাঁর ছেলে ইসমাইল ও ইসহাক (আ.)-এর জন্য এটি পড়তেন (সহিহ বুখারি):\n\nأُعِيذُكُمَا بِكَلِمَاتِ اللَّهِ التَّامَّةِ مِنْ كُلِّ شَيْطَانٍ وَهَامَّةٍ وَمِنْ كُلِّ عَيْنٍ لَامَّةٍ\n\n**উচ্চারণ: উইযুকুমা বিকালিমাতিল্লাহিত তাম্মাহ, মিন কুল্লি শাইতানিও ওয়া হাম্মাহ, ওয়া মিন কুল্লি আইনিল লাম্মাহ।**\n\nঅর্থ: আমি তোমাদের দুজনকে আল্লাহর পরিপূর্ণ বাণীর আশ্রয়ে দিচ্ছি — সব শয়তান ও ক্ষতিকর প্রাণী থেকে, এবং সব কুদৃষ্টি থেকে। এই রূপটি দুই সন্তানের জন্য; অনেক পরিবার এক সন্তানের জন্য শেষাংশ বদলে পড়ে। সঠিক রূপগুলো শিখতে চাইলে আলেমকে জিজ্ঞেস করুন।\n\n## এক কিশোরের জন্য রাসূলুল্লাহ ﷺ-এর দোয়া\n\nতিনি কিশোর ইবনে আব্বাস (রা.)-এর জন্য দোয়া করেছিলেন: হে আল্লাহ, তাকে দ্বীনের বুঝ দান করুন (সহিহ বুখারি)। সন্তানের জন্য সবচেয়ে জরুরি জিনিসগুলো চান: ঈমান, প্রজ্ঞা, সুন্দর চরিত্র আর সুস্বাস্থ্য।\n\n## দোয়ার সহজ সময়\n\n- প্রতি নামাজের পর, প্রতিটি সন্তানের নাম ধরে।\n- সে ঘুমিয়ে থাকলে, মাথায় হাত রেখে।\n- স্কুলে বা পরীক্ষায় যাওয়ার সময়।\n- শিশুকে খাওয়াতে রাতের শেষভাগে জাগলে।\n- মাঝে মাঝে তার সামনে, যেন সে শোনে আপনি তাকে কতটা ভালোবাসেন।\n\nনিখুঁত আরবি লাগবে না। মন থেকে বাংলা, ইংরেজি বা যেকোনো ভাষায় আল্লাহর সাথে কথা বলুন। সন্তান কঠিন সময় পার করলেও দোয়া চালিয়ে যান। এটি এমন জিনিস যা কোনো বাবা-মায়ের কখনো ফুরায় না।"}'::jsonb, '{}'::jsonb, 4, NULL, NULL, '{}'::text[], 'any', ARRAY['dua', 'parents dua', 'protection', 'anger', 'children']::text[], false, 'in_review'::lp_review_status, 9019),
  ('isl-daily-duas-checklist', 'checklist', 'islamic', 'family', 'routine', 'religious', '📿', '{"en":"Daily duas for children: a checklist","bn":"শিশুদের প্রতিদিনের দোয়া: চেকলিস্ট"}'::jsonb, '{"en":"Eleven short duas for eating, sleeping, the toilet, going out, coming home, sneezing and greeting, with Arabic, transliteration and meaning. Learn one a week.","bn":"খাওয়া, ঘুম, টয়লেট, বাইরে যাওয়া, ঘরে ফেরা, হাঁচি ও সালামের এগারোটি ছোট দোয়া — আরবি, উচ্চারণ ও অর্থসহ। সপ্তাহে একটি করে শিখুন।"}'::jsonb, '{"en":"Children learn duas by hearing them at the right moment, again and again. Say the dua aloud yourself every time, and soon your child will join in.\n\n- Start with the shortest: Bismillah and Alhamdulillah. A two-year-old can say these.\n- Learn one new dua a week. Practise it at the real moment, not only as a lesson.\n- Explain the meaning in Bangla, so it is a conversation with Allah, not just sounds.\n- Praise effort. Never scold a child for forgetting; just say it together.\n- A chart on the wall with a tick for each dua learned works well for children of four and up.\n\nThese duas are collected in Hisn al-Muslim. Pronunciation is best learned by listening to a teacher or a trusted recording.","bn":"শিশুরা ঠিক সময়ে বারবার শুনে শুনে দোয়া শেখে। প্রতিবার নিজে জোরে দোয়াটি পড়ুন, দেখবেন শিগগিরই আপনার সন্তানও সাথে পড়ছে।\n\n- সবচেয়ে ছোটগুলো দিয়ে শুরু করুন: বিসমিল্লাহ আর আলহামদুলিল্লাহ। দুই বছরের শিশুও এগুলো বলতে পারে।\n- সপ্তাহে একটি নতুন দোয়া শিখুন। শুধু পাঠ হিসেবে নয়, আসল মুহূর্তে অনুশীলন করুন।\n- অর্থটা বাংলায় বুঝিয়ে দিন, যেন এটা আল্লাহর সাথে কথা হয়, শুধু শব্দ নয়।\n- চেষ্টার প্রশংসা করুন। ভুলে গেলে কখনো বকবেন না; শুধু একসাথে পড়ে নিন।\n- চার বছর বা তার বেশি বয়সী শিশুর জন্য দেয়ালে একটি চার্ট রাখুন, প্রতিটি শেখা দোয়ায় টিক দিন।\n\nএই দোয়াগুলো হিসনুল মুসলিমে সংকলিত আছে। সঠিক উচ্চারণ শিক্ষকের কাছে বা নির্ভরযোগ্য রেকর্ডিং শুনে শেখা সবচেয়ে ভালো।"}'::jsonb, '{"items":{"en":["Before eating: بِسْمِ اللَّهِ — Bismillah — In the name of Allah. (Sahih al-Bukhari and Sahih Muslim)","If you forgot at the start: بِسْمِ اللَّهِ أَوَّلَهُ وَآخِرَهُ — Bismillahi awwalahu wa akhirahu — In the name of Allah, at its beginning and its end. (Sunan Abi Dawud, Jami'' at-Tirmidhi)","After eating: الْحَمْدُ لِلَّهِ — Alhamdulillah — All praise is for Allah.","Before sleep: بِاسْمِكَ اللَّهُمَّ أَمُوتُ وَأَحْيَا — Bismika Allahumma amutu wa ahya — In Your name, O Allah, I die and I live. (Sahih al-Bukhari)","On waking: الْحَمْدُ لِلَّهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا وَإِلَيْهِ النُّشُورُ — Alhamdu lillahil-ladhi ahyana ba''da ma amatana wa ilayhin-nushur — All praise is for Allah, who gave us life after taking it away in sleep, and to Him we will return. (Sahih al-Bukhari)","Before entering the toilet (left foot first): اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْخُبُثِ وَالْخَبَائِثِ — Allahumma inni a''udhu bika minal-khubuthi wal-khaba''ith — O Allah, I seek Your protection from all evil and evil beings. (Sahih al-Bukhari and Sahih Muslim)","After leaving the toilet (right foot first): غُفْرَانَكَ — Ghufranak — I ask for Your forgiveness. (Sunan Abi Dawud, Jami'' at-Tirmidhi)","Leaving home: بِسْمِ اللَّهِ تَوَكَّلْتُ عَلَى اللَّهِ وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ — Bismillahi tawakkaltu ''alallah, wa la hawla wa la quwwata illa billah — In the name of Allah, I trust in Allah; there is no power and no strength except with Allah. (Sunan Abi Dawud, Jami'' at-Tirmidhi)","Entering home: say Bismillah, then greet everyone with السَّلَامُ عَلَيْكُمْ — Assalamu ''alaykum — Peace be upon you. (Remembering Allah on entering: Sahih Muslim; greeting when entering houses: Surah An-Nur 24:61)","When sneezing: the one who sneezes says الْحَمْدُ لِلَّهِ — Alhamdulillah; the listener says يَرْحَمُكَ اللَّهُ — Yarhamukallah — May Allah have mercy on you; the sneezer replies يَهْدِيكُمُ اللَّهُ وَيُصْلِحُ بَالَكُمْ — Yahdikumullahu wa yuslihu balakum — May Allah guide you and set your affairs right. (Sahih al-Bukhari)","Greeting: السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ — Assalamu ''alaykum wa rahmatullahi wa barakatuh — Peace be upon you, and the mercy and blessings of Allah. Reply: وَعَلَيْكُمُ السَّلَامُ — Wa ''alaykumus-salam — And upon you be peace."],"bn":["খাওয়ার আগে: بِسْمِ اللَّهِ — উচ্চারণ: বিসমিল্লাহ — অর্থ: আল্লাহর নামে। (সহিহ বুখারি ও সহিহ মুসলিম)","শুরুতে ভুলে গেলে: بِسْمِ اللَّهِ أَوَّلَهُ وَآخِرَهُ — উচ্চারণ: বিসমিল্লাহি আওয়ালাহু ওয়া আখিরাহু — অর্থ: শুরুতে ও শেষে আল্লাহর নামে। (সুনান আবু দাউদ, জামে তিরমিজি)","খাওয়ার পরে: الْحَمْدُ لِلَّهِ — উচ্চারণ: আলহামদুলিল্লাহ — অর্থ: সব প্রশংসা আল্লাহর।","ঘুমানোর আগে: بِاسْمِكَ اللَّهُمَّ أَمُوتُ وَأَحْيَا — উচ্চারণ: বিসমিকা আল্লাহুম্মা আমুতু ওয়া আহইয়া — অর্থ: হে আল্লাহ, আপনার নামেই আমি মরি ও বাঁচি। (সহিহ বুখারি)","ঘুম থেকে উঠে: الْحَمْدُ لِلَّهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا وَإِلَيْهِ النُّشُورُ — উচ্চারণ: আলহামদু লিল্লাহিল্লাযি আহইয়ানা বা''দা মা আমাতানা ওয়া ইলাইহিন নুশুর — অর্থ: সব প্রশংসা আল্লাহর, যিনি ঘুমের মাধ্যমে মৃত্যুর মতো অবস্থার পর আমাদের জীবিত করেছেন, আর তাঁর কাছেই ফিরে যেতে হবে। (সহিহ বুখারি)","টয়লেটে ঢোকার আগে (বাম পা আগে): اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْخُبُثِ وَالْخَبَائِثِ — উচ্চারণ: আল্লাহুম্মা ইন্নি আউযু বিকা মিনাল খুবুসি ওয়াল খাবায়িস — অর্থ: হে আল্লাহ, আমি সব অপবিত্র ও ক্ষতিকর সত্তা থেকে আপনার আশ্রয় চাই। (সহিহ বুখারি ও সহিহ মুসলিম)","টয়লেট থেকে বের হয়ে (ডান পা আগে): غُفْرَانَكَ — উচ্চারণ: গুফরানাকা — অর্থ: আপনার ক্ষমা চাই। (সুনান আবু দাউদ, জামে তিরমিজি)","ঘর থেকে বের হওয়ার সময়: بِسْمِ اللَّهِ تَوَكَّلْتُ عَلَى اللَّهِ وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ — উচ্চারণ: বিসমিল্লাহি তাওয়াক্কালতু আলাল্লাহ, ওয়া লা হাওলা ওয়া লা কুওয়াতা ইল্লা বিল্লাহ — অর্থ: আল্লাহর নামে, আল্লাহর ওপর ভরসা করলাম; আল্লাহ ছাড়া কোনো শক্তি ও সামর্থ্য নেই। (সুনান আবু দাউদ, জামে তিরমিজি)","ঘরে ঢোকার সময়: বিসমিল্লাহ বলুন, তারপর সবাইকে সালাম দিন — السَّلَامُ عَلَيْكُمْ — উচ্চারণ: আসসালামু আলাইকুম — অর্থ: আপনাদের ওপর শান্তি বর্ষিত হোক। (ঘরে ঢোকার সময় আল্লাহর স্মরণ: সহিহ মুসলিম; ঘরে ঢুকে সালাম: সূরা আন-নূর ২৪:৬১)","হাঁচি দিলে: যে হাঁচি দেয় সে বলবে الْحَمْدُ لِلَّهِ — আলহামদুলিল্লাহ; যে শোনে সে বলবে يَرْحَمُكَ اللَّهُ — ইয়ারহামুকাল্লাহ — আল্লাহ আপনার প্রতি দয়া করুন; হাঁচিদাতা উত্তরে বলবে يَهْدِيكُمُ اللَّهُ وَيُصْلِحُ بَالَكُمْ — ইয়াহদিকুমুল্লাহু ওয়া ইউসলিহু বালাকুম — আল্লাহ আপনাকে হেদায়েত দিন ও আপনার অবস্থা ভালো করুন। (সহিহ বুখারি)","সালাম: السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ — উচ্চারণ: আসসালামু আলাইকুম ওয়া রাহমাতুল্লাহি ওয়া বারাকাতুহ — অর্থ: আপনার ওপর শান্তি, আল্লাহর রহমত ও বরকত বর্ষিত হোক। উত্তর: وَعَلَيْكُمُ السَّلَامُ — ওয়া আলাইকুমুস সালাম — আপনার ওপরও শান্তি বর্ষিত হোক।"]}}'::jsonb, 4, 730, 4748, '{}'::text[], 'any', ARRAY['dua', 'daily duas', 'adhkar', 'children', 'eating', 'sleep', 'toilet', 'sneezing', 'salam']::text[], false, 'in_review'::lp_review_status, 9020),
  ('isl-eating-etiquette', 'article', 'islamic', 'family', 'routine', 'religious', '🍽️', '{"en":"Eating manners from the Sunnah","bn":"সুন্নাহ থেকে খাওয়ার আদব"}'::jsonb, '{"en":"“Say Bismillah, eat with your right hand, and eat from what is near you.” The Prophet ﷺ taught a young boy at the table, gently and simply.","bn":"“বিসমিল্লাহ বলো, ডান হাতে খাও, আর তোমার কাছ থেকে খাও।” রাসূলুল্লাহ ﷺ খাবারের সময় এক ছোট ছেলেকে কোমল ও সহজভাবে শিখিয়েছিলেন।"}'::jsonb, '{"en":"## The hadith of ''Umar ibn Abi Salamah\n\n''Umar ibn Abi Salamah grew up in the Prophet''s ﷺ care. He said: I was a boy, and my hand used to wander all over the dish. The Messenger of Allah ﷺ said to me: young boy, say Bismillah, eat with your right hand, and eat from what is near you (Sahih al-Bukhari and Sahih Muslim). ''Umar said that this stayed his way of eating ever after.\n\nNotice how he taught: he called the boy kindly, gave three short, clear instructions, and did not shame him in front of others.\n\n## Three simple manners\n\n1. **Say Bismillah.** If your child forgets, teach them to say “Bismillahi awwalahu wa akhirahu” when they remember.\n2. **Eat with the right hand.** Gently guide the hand again and again. Little children will use both hands for a while; that is part of learning.\n3. **Eat from what is near you.** Do not reach across others or pick through the dish. This teaches care for the people you share with.\n\n## More from the Sunnah\n\n- **No complaining about food.** The Prophet ﷺ never criticised food. If he liked it he ate it, and if not he left it (Sahih al-Bukhari and Sahih Muslim). So a child who does not want something can leave it politely, without “Yuck!”\n- **Do not waste.** Allah says: eat and drink, but do not waste (Surah Al-A''raf 7:31). Serve small portions and let children ask for more.\n- **Clean the plate and fingers.** The Prophet ﷺ encouraged wiping the plate and licking the fingers, saying you do not know which part of the food holds the blessing (Sahih Muslim).\n- **Drink in sips.** He used to pause for breath three times while drinking, and he discouraged breathing into the cup (Sahih al-Bukhari and Sahih Muslim).\n- **Say Alhamdulillah at the end.**\n\n## If a child is left-handed or has a disability\n\nUsing the right hand for eating is the Sunnah, so encourage it gently. A naturally left-handed child can still write and play with the left hand. If a disability makes the right hand hard to use, remember that Allah does not burden anyone beyond their capacity (Surah Al-Baqarah 2:286). Never shame a child for this.\n\n## Make mealtimes warm\n\n- Eat together at least once a day if you can, without phones or television.\n- Fathers, sit with the children and model the manners yourself.\n- Talk, smile, and thank whoever cooked. Good manners grow best at a happy table.","bn":"## উমর ইবনে আবি সালামা (রা.)-এর হাদিস\n\nউমর ইবনে আবি সালামা (রা.) রাসূলুল্লাহ ﷺ-এর তত্ত্বাবধানে বড় হয়েছিলেন। তিনি বলেছেন: আমি তখন ছোট ছেলে, আমার হাত পুরো থালায় ঘুরে বেড়াত। রাসূলুল্লাহ ﷺ আমাকে বললেন: হে বালক, বিসমিল্লাহ বলো, ডান হাতে খাও, আর তোমার কাছ থেকে খাও (সহিহ বুখারি ও সহিহ মুসলিম)। উমর (রা.) বলেছেন, এরপর থেকে এটাই তাঁর খাওয়ার নিয়ম হয়ে যায়।\n\nলক্ষ করুন তিনি কীভাবে শিখিয়েছেন: আদর করে ডেকেছেন, ছোট ও স্পষ্ট তিনটি কথা বলেছেন, আর অন্যদের সামনে লজ্জা দেননি।\n\n## তিনটি সহজ আদব\n\n1. **বিসমিল্লাহ বলা।** সন্তান ভুলে গেলে মনে পড়ার সময় “বিসমিল্লাহি আওয়ালাহু ওয়া আখিরাহু” বলতে শেখান।\n2. **ডান হাতে খাওয়া।** বারবার আলতো করে হাতটা ঠিক করে দিন। ছোট শিশুরা কিছুদিন দুই হাতেই খাবে; এটা শেখারই অংশ।\n3. **নিজের কাছ থেকে খাওয়া।** অন্যের সামনে দিয়ে হাত বাড়ানো বা থালা ঘাঁটাঘাঁটি নয়। এতে যাদের সাথে খাচ্ছে তাদের প্রতি খেয়াল রাখা শেখে।\n\n## সুন্নাহ থেকে আরও\n\n- **খাবারের দোষ না ধরা।** রাসূলুল্লাহ ﷺ কখনো খাবারের দোষ ধরেননি। পছন্দ হলে খেতেন, না হলে রেখে দিতেন (সহিহ বুখারি ও সহিহ মুসলিম)। তাই কোনো খাবার না চাইলে সন্তান ভদ্রভাবে রেখে দিতে পারে, “ছি!” না বলে।\n- **অপচয় না করা।** আল্লাহ বলেন: খাও ও পান করো, কিন্তু অপচয় কোরো না (সূরা আল-আ''রাফ ৭:৩১)। অল্প করে দিন, শিশু চাইলে আরও দিন।\n- **থালা ও আঙুল পরিষ্কার।** রাসূলুল্লাহ ﷺ থালা মুছে নিতে ও আঙুল চেটে খেতে উৎসাহ দিয়েছেন, বলেছেন তোমরা জানো না খাবারের কোন অংশে বরকত আছে (সহিহ মুসলিম)।\n- **থেমে থেমে পান করা।** তিনি পান করার সময় তিনবার শ্বাস নিতেন, আর পাত্রের ভেতরে শ্বাস ফেলতে নিষেধ করেছেন (সহিহ বুখারি ও সহিহ মুসলিম)।\n- **শেষে আলহামদুলিল্লাহ বলা।**\n\n## সন্তান বাঁহাতি বা প্রতিবন্ধী হলে\n\nডান হাতে খাওয়া সুন্নাহ, তাই আলতো করে উৎসাহ দিন। স্বভাবগতভাবে বাঁহাতি শিশু লেখা ও খেলায় বাঁ হাতই ব্যবহার করতে পারে। প্রতিবন্ধিতার কারণে ডান হাত ব্যবহার কঠিন হলে মনে রাখুন, আল্লাহ কারও ওপর সাধ্যের বাইরে বোঝা চাপান না (সূরা আল-বাকারা ২:২৮৬)। এ নিয়ে কখনো শিশুকে লজ্জা দেবেন না।\n\n## খাবারের সময়টা উষ্ণ রাখুন\n\n- সম্ভব হলে দিনে অন্তত একবার ফোন বা টিভি ছাড়া একসাথে খান।\n- বাবারা, সন্তানদের সাথে বসুন এবং নিজে আদবগুলো মেনে দেখান।\n- কথা বলুন, হাসুন, আর যিনি রান্না করেছেন তাঁকে ধন্যবাদ দিন। আনন্দময় দস্তরখানেই সবচেয়ে ভালো আদব গড়ে ওঠে।"}'::jsonb, '{}'::jsonb, 3, 730, 4748, '{}'::text[], 'any', ARRAY['eating', 'manners', 'bismillah', 'right hand', 'food waste', 'family meals']::text[], false, 'in_review'::lp_review_status, 9021),
  ('isl-salam-kind-words', 'activity', 'islamic', 'family', 'routine', 'religious', '👋', '{"en":"Salam and kind words: a family practice","bn":"সালাম ও সুন্দর কথা: পরিবারের অনুশীলন"}'::jsonb, '{"en":"Spread salam, say a good word, smile. Simple games to make greeting and kind speech a habit at home.","bn":"সালাম ছড়িয়ে দিন, ভালো কথা বলুন, হাসুন। ঘরে সালাম ও সুন্দর কথাকে অভ্যাস বানানোর সহজ খেলা।"}'::jsonb, '{}'::jsonb, '{"why":{"en":"The Prophet ﷺ said: you will not enter Paradise until you believe, and you will not believe until you love one another. Shall I tell you something that, if you do it, you will love one another? Spread salam among yourselves (Sahih Muslim). He greeted children with salam when he passed them (Sahih al-Bukhari and Sahih Muslim), and he said that a good word is charity (Sahih al-Bukhari and Sahih Muslim) and that smiling at your brother is charity (Jami'' at-Tirmidhi). He also said: whoever believes in Allah and the Last Day, let them say something good or stay silent (Sahih al-Bukhari and Sahih Muslim). Greeting and kind words build love in the family before they build it anywhere else.","bn":"রাসূলুল্লাহ ﷺ বলেছেন: তোমরা ঈমান না আনা পর্যন্ত জান্নাতে যাবে না, আর পরস্পরকে না ভালোবাসা পর্যন্ত ঈমানদার হবে না। আমি কি তোমাদের এমন কিছু বলব, যা করলে তোমরা একে অপরকে ভালোবাসবে? নিজেদের মধ্যে সালাম ছড়িয়ে দাও (সহিহ মুসলিম)। তিনি শিশুদের পাশ দিয়ে যাওয়ার সময় তাদের সালাম দিতেন (সহিহ বুখারি ও সহিহ মুসলিম), এবং বলেছেন ভালো কথা সদকা (সহিহ বুখারি ও সহিহ মুসলিম), আর ভাইয়ের দিকে তাকিয়ে হাসাও সদকা (জামে তিরমিজি)। তিনি আরও বলেছেন: যে আল্লাহ ও আখিরাতে বিশ্বাস করে, সে যেন ভালো কথা বলে অথবা চুপ থাকে (সহিহ বুখারি ও সহিহ মুসলিম)। সালাম আর সুন্দর কথা আগে পরিবারে ভালোবাসা গড়ে, তারপর বাইরে।"},"items":{"en":["A small jar or box","Paper slips and a pen or crayons","Optional: a sticker chart for younger children"],"bn":["একটি ছোট বয়াম বা বাক্স","কাগজের টুকরো আর কলম বা রং পেনসিল","ঐচ্ছিক: ছোটদের জন্য স্টিকার চার্ট"]},"steps":{"en":["Greet your children first. When you come home or they wake up, say “Assalamu ''alaykum” with a smile, just as the Prophet ﷺ greeted children.","Practise at the door: take turns coming in and greeting, and answering “Wa ''alaykumus-salam”. Little ones love this game.","Teach the Sunnah order: the younger greets the older, the one walking greets the one sitting, and the smaller group greets the larger (Sahih al-Bukhari). Anyone may greet first, and the one who starts gets extra reward.","Add kind words: please, thank you, sorry, and “Jazakallahu khayran” (May Allah reward you with good), which the Prophet ﷺ praised as a fine way to thank someone (Jami'' at-Tirmidhi).","Start a kind-words jar: each time someone hears a family member say something kind, write it on a slip and put it in.","Once a week, read the slips out together at dinner and enjoy them.","When someone says something hurtful, pause and ask: can you say that in a kind way? Let them try again rather than punishing.","Fathers and mothers: greet each other with salam in front of the children. They copy how you speak to each other most of all."],"bn":["আগে আপনি সন্তানদের সালাম দিন। ঘরে ফিরে বা তারা ঘুম থেকে উঠলে হাসিমুখে বলুন “আসসালামু আলাইকুম” — যেভাবে রাসূলুল্লাহ ﷺ শিশুদের সালাম দিতেন।","দরজায় অনুশীলন: পালা করে ঘরে ঢুকে সালাম দিন, আর উত্তর দিন “ওয়া আলাইকুমুস সালাম”। ছোটরা এই খেলাটা খুব পছন্দ করে।","সুন্নাহর ক্রম শেখান: ছোট বড়কে সালাম দেবে, যে হাঁটছে সে বসে থাকা ব্যক্তিকে, আর ছোট দল বড় দলকে (সহিহ বুখারি)। যে কেউ আগে সালাম দিতে পারে, আর যে আগে দেয় তার সওয়াব বেশি।","সুন্দর কথা যোগ করুন: প্লিজ, ধন্যবাদ, দুঃখিত, আর “জাযাকাল্লাহু খাইরান” (আল্লাহ আপনাকে উত্তম প্রতিদান দিন) — রাসূলুল্লাহ ﷺ একে কৃতজ্ঞতা জানানোর সুন্দর উপায় বলেছেন (জামে তিরমিজি)।","একটি সুন্দর-কথার বয়াম শুরু করুন: পরিবারের কেউ সুন্দর কিছু বললে যে শুনেছে সে কাগজে লিখে বয়ামে রাখবে।","সপ্তাহে একবার রাতের খাবারের সময় সবাই মিলে কাগজগুলো পড়ুন এবং উপভোগ করুন।","কেউ কষ্টদায়ক কিছু বললে থামুন এবং জিজ্ঞেস করুন: কথাটা কি সুন্দর করে বলা যায়? শাস্তি না দিয়ে আবার চেষ্টা করতে দিন।","বাবা-মা: সন্তানদের সামনে একে অপরকে সালাম দিন। আপনারা নিজেরা কীভাবে কথা বলেন, সন্তান সবচেয়ে বেশি সেটাই অনুকরণ করে।"]},"example":{"en":"Rafi, four, ran in from playing and grabbed a biscuit. His father smiled and said, “Assalamu ''alaykum, Rafi!” Rafi laughed, went back to the door, came in again and said, “Assalamu ''alaykum, Abbu!” His father answered, hugged him, and said, “Jazakallahu khayran for the lovely salam.” By the end of the week, Rafi was greeting everyone who came home.","bn":"চার বছরের রাফি খেলা থেকে দৌড়ে এসে একটা বিস্কুট তুলে নিল। তার বাবা হেসে বললেন, “আসসালামু আলাইকুম, রাফি!” রাফি হেসে দরজায় ফিরে গেল, আবার ঢুকে বলল, “আসসালামু আলাইকুম, আব্বু!” বাবা উত্তর দিয়ে তাকে জড়িয়ে ধরলেন, বললেন, “এত সুন্দর সালামের জন্য জাযাকাল্লাহু খাইরান।” সপ্তাহ শেষে রাফি ঘরে আসা সবাইকে সালাম দিচ্ছিল।"}}'::jsonb, 3, 730, 4748, '{}'::text[], 'any', ARRAY['salam', 'greeting', 'kind words', 'manners', 'jazakallah', 'kindness']::text[], false, 'in_review'::lp_review_status, 9022),
  ('isl-teaching-salah-gently', 'article', 'islamic', 'shared', 'important', 'religious', '🧎', '{"en":"Teaching salah gently: from love at four to a habit at ten","bn":"কোমলভাবে নামাজ শেখানো: চার বছরে ভালোবাসা থেকে দশে অভ্যাস"}'::jsonb, '{"en":"The Prophet ﷺ told parents to teach children salah from seven (Abu Dawud 495). Before that, let them fall in love with it; after that, build the habit with patience, not pressure.","bn":"রাসূলুল্লাহ ﷺ সাত বছর বয়স থেকে সন্তানকে নামাজ শেখাতে বলেছেন (আবু দাউদ ৪৯৫)। তার আগে নামাজকে ভালোবাসতে দিন; তারপর চাপ নয়, ধৈর্য দিয়ে অভ্যাস গড়ুন।"}'::jsonb, '{"en":"## The hadith\n\nThe Prophet ﷺ said: instruct your children to pray when they are seven years old, discipline them for it when they are ten, and separate their beds (Sunan Abi Dawud 495).\n\nAllah also says to the Prophet ﷺ:\n\nوَأْمُرْ أَهْلَكَ بِالصَّلَاةِ وَاصْطَبِرْ عَلَيْهَا\n\n**Wa''mur ahlaka bis-salati wastabir ''alayha.**\n\nMeaning: And instruct your family to pray, and be patient in it yourself. (Surah Ta-Ha 20:132)\n\nNotice the word patience. Teaching salah is a long, gentle project.\n\n## Before seven: let them love it\n\n- Pray where your little one can see you. Small children copy, and a three-year-old on a tiny prayer mat beside you is learning.\n- Never push them off the mat or scold them for climbing on you. The Prophet ﷺ prayed carrying his granddaughter Umamah (Sahih al-Bukhari and Sahih Muslim).\n- Talk about Allah with warmth: He made the rain, the mangoes and Ammu''s smile, and salah is our way of saying thank you.\n- Teach Allahu Akbar, Al-Fatiha and short surahs as songs and games.\n\n## From seven: teach and invite\n\n- Explain the steps of wudu and salah slowly, one part at a time.\n- Start with one prayer a day together, often Maghrib or Isha when the family is home. Add more over months.\n- Link prayers to daily life: Fajr before school, Asr after play, Maghrib when the adhan comes.\n- Praise effort, not perfection. A crooked line of children in sujud is beautiful.\n- Use reminders, charts and a pleasant voice. Never make salah a punishment, or the child will learn to dislike it.\n\n## About “discipline at ten”\n\nThe same hadith speaks of firmer discipline at ten. Scholars explain that this comes only after three years of patient teaching, that it must never injure, humiliate or be done in anger, and many teachers today stress that encouragement works far better. The Prophet ﷺ himself was gentle with children: Anas ibn Malik served him from boyhood for ten years and was never even told “uff” (Sahih al-Bukhari and Sahih Muslim). If you are unsure how to apply this, ask a trusted local scholar.\n\n## Girls and boys, every ability\n\nThe hadith is for all children. A child with a disability prays in the way they are able, sitting or with help, and their effort is precious. A child who finds reading hard can start with the shortest surahs.\n\n## Fathers\n\nTake your son and daughter by the hand to pray. In many homes children see their mother pray but rarely their father. Let them see you pray, and pray with them.","bn":"## হাদিসটি\n\nরাসূলুল্লাহ ﷺ বলেছেন: তোমাদের সন্তানদের বয়স সাত হলে নামাজের নির্দেশ দাও, দশ হলে এর জন্য শাসন করো, আর তাদের বিছানা আলাদা করে দাও (সুনান আবু দাউদ ৪৯৫)।\n\nআল্লাহ রাসূলুল্লাহ ﷺ-কে বলেছেন:\n\nوَأْمُرْ أَهْلَكَ بِالصَّلَاةِ وَاصْطَبِرْ عَلَيْهَا\n\n**উচ্চারণ: ওয়া''মুর আহলাকা বিস সালাতি ওয়াসতাবির আলাইহা।**\n\nঅর্থ: আর তোমার পরিবারকে নামাজের নির্দেশ দাও এবং নিজেও এতে ধৈর্যশীল থাকো। (সূরা ত্বাহা ২০:১৩২)\n\nধৈর্য শব্দটি লক্ষ করুন। নামাজ শেখানো একটি দীর্ঘ ও কোমল কাজ।\n\n## সাতের আগে: ভালোবাসতে দিন\n\n- ছোট সন্তান দেখতে পায় এমন জায়গায় নামাজ পড়ুন। শিশুরা অনুকরণ করে; আপনার পাশে ছোট্ট জায়নামাজে তিন বছরের শিশুটি শিখছে।\n- জায়নামাজ থেকে সরিয়ে দেবেন না, গায়ে উঠলে বকবেন না। রাসূলুল্লাহ ﷺ নাতনি উমামাকে কোলে নিয়ে নামাজ পড়েছেন (সহিহ বুখারি ও সহিহ মুসলিম)।\n- আল্লাহর কথা আদর দিয়ে বলুন: তিনি বৃষ্টি দিয়েছেন, আম দিয়েছেন, আম্মুর হাসি দিয়েছেন — নামাজ হলো তাঁকে ধন্যবাদ দেওয়ার উপায়।\n- আল্লাহু আকবার, সূরা ফাতিহা ও ছোট সূরাগুলো ছড়া ও খেলার মতো করে শেখান।\n\n## সাত থেকে: শেখান ও ডাকুন\n\n- অজু ও নামাজের ধাপগুলো ধীরে ধীরে, একবারে একটি অংশ করে বুঝিয়ে দিন।\n- দিনে এক ওয়াক্ত একসাথে দিয়ে শুরু করুন, প্রায়ই মাগরিব বা এশা, যখন সবাই ঘরে থাকে। মাসের পর মাস ধীরে ধীরে বাড়ান।\n- নামাজকে দিনের রুটিনের সাথে জুড়ে দিন: স্কুলের আগে ফজর, খেলার পর আসর, আজান হলে মাগরিব।\n- নিখুঁত হওয়া নয়, চেষ্টার প্রশংসা করুন। সিজদায় শিশুদের আঁকাবাঁকা কাতারও সুন্দর।\n- মনে করিয়ে দিন, চার্ট ব্যবহার করুন, মিষ্টি করে বলুন। নামাজকে কখনো শাস্তি বানাবেন না, তাহলে শিশু নামাজকে অপছন্দ করতে শিখবে।\n\n## “দশ বছরে শাসন” প্রসঙ্গে\n\nএকই হাদিসে দশ বছরে কিছুটা কঠোর শাসনের কথা আছে। আলেমরা ব্যাখ্যা করেন, এটি আসে কেবল তিন বছরের ধৈর্যশীল শিক্ষার পরে; এতে কখনো আঘাত, অপমান বা রাগ থাকতে পারবে না; আর অনেক শিক্ষক আজ জোর দিয়ে বলেন যে উৎসাহই অনেক বেশি কাজ করে। রাসূলুল্লাহ ﷺ নিজে শিশুদের প্রতি কোমল ছিলেন: আনাস ইবনে মালিক (রা.) ছোটবেলা থেকে দশ বছর তাঁর খেদমত করেছেন, অথচ কখনো “উফ” শব্দটিও শোনেননি (সহিহ বুখারি ও সহিহ মুসলিম)। এটি কীভাবে প্রয়োগ করবেন তা নিয়ে নিশ্চিত না হলে বিশ্বস্ত স্থানীয় আলেমকে জিজ্ঞেস করুন।\n\n## মেয়ে-ছেলে, সব সামর্থ্যের শিশু\n\nহাদিসটি সব শিশুর জন্য। প্রতিবন্ধী শিশু যেভাবে পারে সেভাবে নামাজ পড়বে — বসে বা সাহায্য নিয়ে — আর তার চেষ্টা অমূল্য। যে শিশুর পড়তে কষ্ট হয়, সে সবচেয়ে ছোট সূরাগুলো দিয়ে শুরু করতে পারে।\n\n## বাবাদের জন্য\n\nছেলে ও মেয়ের হাত ধরে নামাজে নিয়ে যান। অনেক ঘরে শিশুরা মাকে নামাজ পড়তে দেখে, কিন্তু বাবাকে কম দেখে। তারা আপনাকে নামাজ পড়তে দেখুক, আর তাদের সাথে নিয়ে পড়ুন।"}'::jsonb, '{}'::jsonb, 4, 1461, 4748, '{}'::text[], 'any', ARRAY['salah', 'namaz', 'prayer', 'age seven', 'teaching', 'gentle']::text[], false, 'in_review'::lp_review_status, 9023),
  ('isl-wudu-steps', 'activity', 'islamic', 'child', 'routine', 'religious', '💧', '{"en":"Wudu step by step for children","bn":"শিশুদের জন্য ধাপে ধাপে অজু"}'::jsonb, '{"en":"A simple, child-friendly way to learn wudu, based on Surah Al-Ma''idah 5:6 and the Sunnah, with tips for not wasting water.","bn":"সূরা আল-মায়িদা ৫:৬ ও সুন্নাহ অনুযায়ী শিশুদের জন্য সহজভাবে অজু শেখা, সাথে পানি অপচয় না করার পরামর্শ।"}'::jsonb, '{}'::jsonb, '{"why":{"en":"Wudu prepares us to stand before Allah. The Quran names its main parts: washing the face, the arms up to the elbows, wiping the head, and washing the feet up to the ankles (Surah Al-Ma''idah 5:6). The Prophet ﷺ said that when a believer washes in wudu, their small sins go out with the water (Sahih Muslim), and he used only a little water for it (Sahih al-Bukhari and Sahih Muslim). Small details differ between the schools of law, so if your child learns at a maktab, follow their teacher''s way.","bn":"অজু আমাদের আল্লাহর সামনে দাঁড়ানোর জন্য প্রস্তুত করে। কুরআনে এর মূল অংশগুলো বলা আছে: মুখ ধোয়া, কনুই পর্যন্ত হাত ধোয়া, মাথা মাসেহ করা এবং টাখনু পর্যন্ত পা ধোয়া (সূরা আল-মায়িদা ৫:৬)। রাসূলুল্লাহ ﷺ বলেছেন, মুমিন অজু করলে তার ছোট গুনাহগুলো পানির সাথে বেরিয়ে যায় (সহিহ মুসলিম), আর তিনি অজুতে খুব অল্প পানি ব্যবহার করতেন (সহিহ বুখারি ও সহিহ মুসলিম)। ছোটখাটো বিষয়ে মাজহাবগুলোর মধ্যে পার্থক্য আছে, তাই সন্তান মক্তবে শিখলে শিক্ষকের নিয়ম অনুসরণ করুন।"},"items":{"en":["Clean water from a tap, jug or bodna","A small towel","A step stool if the basin is high","A non-slip mat, as wet floors are slippery"],"bn":["কল, জগ বা বদনার পরিষ্কার পানি","একটি ছোট তোয়ালে","বেসিন উঁচু হলে একটি ছোট টুল","পিছলে না যাওয়ার মতো পাপোশ, কারণ ভেজা মেঝে পিচ্ছিল"]},"steps":{"en":["Make the intention in your heart: I am doing wudu for Allah.","Say Bismillah.","Wash both hands up to the wrists, three times.","Rinse the mouth, three times.","Gently sniff a little water into the nose and blow it out, three times.","Wash the whole face, from the hairline to the chin and from ear to ear, three times.","Wash the right arm from the fingertips up to and including the elbow, three times, then the left arm the same way.","Wet your hands and wipe over the head, from the front to the back and back again, once.","Wipe the ears: index fingers inside, thumbs behind, once.","Wash the right foot up to and including the ankle, three times, getting between the toes; then the left foot the same way.","Afterwards, you may say: أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ — Ash-hadu an la ilaha illallahu wahdahu la sharika lah, wa ash-hadu anna Muhammadan ''abduhu wa rasuluh — I bear witness that there is no god but Allah alone, with no partner, and that Muhammad is His servant and Messenger. (Sahih Muslim)","Water tip: turn the tap down low or use a jug. Wudu needs only a little water.","Remember: going to the toilet, passing wind or falling into a deep sleep means you need a new wudu before salah."],"bn":["মনে মনে নিয়ত করো: আমি আল্লাহর জন্য অজু করছি।","বিসমিল্লাহ বলো।","দুই হাত কবজি পর্যন্ত তিনবার ধোও।","তিনবার কুলি করো।","আলতো করে নাকে একটু পানি টেনে ঝেড়ে ফেলো, তিনবার।","পুরো মুখ ধোও — কপালের চুলের গোড়া থেকে থুতনি পর্যন্ত, এক কান থেকে আরেক কান পর্যন্ত — তিনবার।","ডান হাত আঙুলের ডগা থেকে কনুইসহ তিনবার ধোও, তারপর বাম হাত একইভাবে।","ভেজা হাতে মাথা মাসেহ করো — সামনে থেকে পেছনে, আবার সামনে — একবার।","কান মাসেহ করো: শাহাদাত আঙুল কানের ভেতরে, বুড়ো আঙুল পেছনে — একবার।","ডান পা টাখনুসহ তিনবার ধোও, আঙুলের ফাঁকেও পানি পৌঁছাও; তারপর বাম পা একইভাবে।","শেষে পড়তে পারো: أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ — উচ্চারণ: আশহাদু আল্লা ইলাহা ইল্লাল্লাহু ওয়াহদাহু লা শারিকা লাহু, ওয়া আশহাদু আন্না মুহাম্মাদান আবদুহু ওয়া রাসুলুহ — অর্থ: আমি সাক্ষ্য দিচ্ছি, আল্লাহ ছাড়া কোনো ইলাহ নেই, তিনি এক, তাঁর কোনো শরিক নেই; আর মুহাম্মাদ তাঁর বান্দা ও রাসূল। (সহিহ মুসলিম)","পানির টিপস: কল কম করে খোলো বা জগ ব্যবহার করো। অজুতে খুব অল্প পানিই লাগে।","মনে রেখো: টয়লেটে গেলে, বায়ু বের হলে বা গভীর ঘুমে গেলে নামাজের আগে নতুন করে অজু করতে হয়।"]},"example":{"en":"Every Friday evening, Nusrat''s mother made wudu next to her seven-year-old at the basin, saying each step out loud. At first Nusrat forgot her ears and her left foot. Her mother just smiled and said, “And now?” After a month, Nusrat was the one calling out the steps for her little brother.","bn":"প্রতি শুক্রবার সন্ধ্যায় নুসরাতের মা সাত বছরের মেয়ের পাশে বেসিনে দাঁড়িয়ে প্রতিটি ধাপ মুখে বলে বলে অজু করতেন। প্রথমে নুসরাত কান আর বাম পা ভুলে যেত। মা শুধু হেসে বলতেন, “এবার কী?” এক মাস পর নুসরাতই ছোট ভাইকে ধাপগুলো বলে দিচ্ছিল।"}}'::jsonb, 3, 1826, 4748, '{}'::text[], 'any', ARRAY['wudu', 'ablution', 'oju', 'salah', 'steps', 'water']::text[], false, 'in_review'::lp_review_status, 9024),
  ('isl-salah-steps-fajr', 'activity', 'islamic', 'child', 'routine', 'religious', '🕋', '{"en":"Salah step by step: the 2 rak''ahs of Fajr","bn":"ধাপে ধাপে নামাজ: ফজরের দুই রাকাত"}'::jsonb, '{"en":"A simple walk-through of a two-rak''ah prayer with what to say at each step, in Arabic sounds and meaning. Small details differ between madhhabs; follow your teacher.","bn":"দুই রাকাত নামাজের সহজ বর্ণনা, প্রতিটি ধাপে কী পড়তে হয় — উচ্চারণ ও অর্থসহ। ছোটখাটো বিষয়ে মাজহাবভেদে পার্থক্য আছে; শিক্ষকের নিয়ম মানুন।"}'::jsonb, '{"en":"Fajr has two fard rak''ahs, which makes it the easiest prayer to learn first. The steps below describe praying alone.\n\n## About differences between madhhabs\n\nAll Muslims pray the same prayer, but small details differ between the schools of law: where to place the hands, whether to raise the hands before and after ruku'', saying amin aloud or quietly, reciting Al-Fatiha behind an imam, a qunut dua in Fajr, and small wording differences in the duas. Most families in Bangladesh follow the Hanafi school. None of these differences makes a prayer wrong. Follow the way your family or your child''s teacher uses, and do not argue with others about it.\n\n## Start small\n\nA beginner does not need to learn everything at once. Start with Allahu Akbar, Al-Fatiha and the words for ruku'' and sujud, and pray beside a parent. Add the tashahhud and salawat later.","bn":"ফজরের ফরজ দুই রাকাত, তাই এটিই প্রথমে শেখার সবচেয়ে সহজ নামাজ। নিচের ধাপগুলো একা নামাজ পড়ার বর্ণনা।\n\n## মাজহাবের পার্থক্য প্রসঙ্গে\n\nসব মুসলিম একই নামাজ পড়েন, তবে মাজহাবভেদে কিছু ছোট পার্থক্য আছে: হাত কোথায় বাঁধবেন, রুকুর আগে-পরে হাত তুলবেন কিনা, আমিন জোরে না আস্তে বলবেন, ইমামের পেছনে সূরা ফাতিহা পড়বেন কিনা, ফজরে কুনুত পড়া, আর দোয়ার শব্দে ছোটখাটো পার্থক্য। বাংলাদেশের বেশিরভাগ পরিবার হানাফি মাজহাব অনুসরণ করে। এসব পার্থক্যের কারণে কোনো নামাজ ভুল হয় না। আপনার পরিবার বা সন্তানের শিক্ষক যে নিয়ম মানেন সেটাই অনুসরণ করুন, আর এ নিয়ে অন্যদের সাথে তর্ক করবেন না।\n\n## ছোট করে শুরু\n\nনতুন শিক্ষার্থীর একবারে সব শেখার দরকার নেই। আল্লাহু আকবার, সূরা ফাতিহা এবং রুকু-সিজদার তাসবিহ দিয়ে শুরু করুন, আর বাবা বা মায়ের পাশে দাঁড়িয়ে নামাজ পড়ুক। তাশাহহুদ ও দরুদ পরে যোগ করুন।"}'::jsonb, '{"why":{"en":"Salah is our daily meeting with Allah. Knowing what each part means helps a child pray with the heart, not only the body. Fajr, with its two rak''ahs, is a gentle place to begin.","bn":"নামাজ আল্লাহর সাথে আমাদের প্রতিদিনের সাক্ষাৎ। প্রতিটি অংশের অর্থ জানলে শিশু শুধু শরীর দিয়ে নয়, মন দিয়েও নামাজ পড়তে পারে। দুই রাকাতের ফজর শুরু করার জন্য সহজ জায়গা।"},"items":{"en":["Wudu done","Clean, modest clothes (many girls like their own prayer scarf)","A clean place or prayer mat","The direction of the qibla"],"bn":["অজু করা","পরিষ্কার ও শালীন পোশাক (অনেক মেয়ে নিজের নামাজের ওড়না পছন্দ করে)","পরিষ্কার জায়গা বা জায়নামাজ","কিবলার দিক"]},"steps":{"en":["Stand facing the qibla. Make the intention in your heart: I am praying the two rak''ahs of Fajr for Allah.","Raise your hands and say اللَّهُ أَكْبَرُ — Allahu Akbar — Allah is the Greatest. Then place your hands as your family or teacher shows you.","Say the opening praise: Subhanakallahumma wa bihamdika, wa tabarakasmuka, wa ta''ala jadduka, wa la ilaha ghayruk — Glory and praise be to You, O Allah; blessed is Your name, high is Your majesty, and there is no god but You. (Sunan Abi Dawud, Jami'' at-Tirmidhi; some schools use other opening duas)","Say quietly: A''udhu billahi minash-shaytanir-rajim, Bismillahir-Rahmanir-Rahim — I seek Allah''s protection from Shaytan the rejected; in the name of Allah, the Most Merciful, the Most Kind.","Recite Surah Al-Fatiha, then say Amin.","Recite a short surah, for example Al-Ikhlas.","Say Allahu Akbar and bow (ruku''), back straight, hands on knees. Say three times: سُبْحَانَ رَبِّيَ الْعَظِيمِ — Subhana Rabbiyal-''Azim — Glory be to my Lord, the Most Great.","Rise and say: سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ — Sami''allahu liman hamidah — Allah hears the one who praises Him. Standing straight, say: رَبَّنَا وَلَكَ الْحَمْدُ — Rabbana wa lakal-hamd — Our Lord, all praise is Yours.","Say Allahu Akbar and go down into sujud: forehead and nose, both hands, both knees and the toes on the ground. Say three times: سُبْحَانَ رَبِّيَ الْأَعْلَى — Subhana Rabbiyal-A''la — Glory be to my Lord, the Most High.","Say Allahu Akbar and sit up for a moment. You may say: رَبِّ اغْفِرْ لِي — Rabbighfir li — My Lord, forgive me.","Say Allahu Akbar and make a second sujud, the same as the first. That completes the first rak''ah.","Say Allahu Akbar and stand for the second rak''ah. Say Bismillah, recite Al-Fatiha, Amin, and another short surah, for example Al-Kawthar. Then ruku'', rising, and two sujud, as before.","After the second sujud, sit and recite the tashahhud: At-tahiyyatu lillahi was-salawatu wat-tayyibat. As-salamu ''alayka ayyuhan-nabiyyu wa rahmatullahi wa barakatuh. As-salamu ''alayna wa ''ala ''ibadillahis-salihin. Ash-hadu an la ilaha illallah, wa ash-hadu anna Muhammadan ''abduhu wa rasuluh. Meaning: All greetings, prayers and good words are for Allah. Peace be upon you, O Prophet, and Allah''s mercy and blessings. Peace be upon us and upon the righteous servants of Allah. I bear witness that there is no god but Allah, and that Muhammad is His servant and Messenger. (Sahih al-Bukhari and Sahih Muslim)","Then send blessings on the Prophet ﷺ (as-salah al-Ibrahimiyyah): Allahumma salli ''ala Muhammadin wa ''ala ali Muhammad, kama sallayta ''ala Ibrahima wa ''ala ali Ibrahim, innaka Hamidun Majid. Allahumma barik ''ala Muhammadin wa ''ala ali Muhammad, kama barakta ''ala Ibrahima wa ''ala ali Ibrahim, innaka Hamidun Majid. Meaning: O Allah, send Your grace and blessings on Muhammad and his family, as You did on Ibrahim and his family; You are Praiseworthy and Glorious.","You may add a short dua, for example: Rabbana atina fid-dunya hasanah, wa fil-akhirati hasanah, wa qina ''adhaban-nar — Our Lord, give us good in this world and good in the Hereafter, and protect us from the Fire. (Surah Al-Baqarah 2:201)","Turn your head to the right and say: As-salamu ''alaykum wa rahmatullah. Then turn to the left and say the same. Your prayer is complete. Alhamdulillah!"],"bn":["কিবলার দিকে মুখ করে দাঁড়াও। মনে মনে নিয়ত করো: আমি আল্লাহর জন্য ফজরের দুই রাকাত নামাজ পড়ছি।","দুই হাত তুলে বলো اللَّهُ أَكْبَرُ — উচ্চারণ: আল্লাহু আকবার — অর্থ: আল্লাহ সবচেয়ে বড়। তারপর পরিবার বা শিক্ষক যেভাবে দেখান সেভাবে হাত বাঁধো।","সানা পড়ো: সুবহানাকা আল্লাহুম্মা ওয়া বিহামদিকা, ওয়া তাবারাকাসমুকা, ওয়া তাআলা জাদ্দুকা, ওয়া লা ইলাহা গাইরুক — অর্থ: হে আল্লাহ, আপনার পবিত্রতা ও প্রশংসা; আপনার নাম বরকতময়, আপনার মর্যাদা সুউচ্চ, আপনি ছাড়া কোনো ইলাহ নেই। (সুনান আবু দাউদ, জামে তিরমিজি; কিছু মাজহাবে অন্য দোয়া দিয়ে শুরু করা হয়)","আস্তে বলো: আউযু বিল্লাহি মিনাশ শাইতানির রাজিম, বিসমিল্লাহির রহমানির রহিম — অর্থ: বিতাড়িত শয়তান থেকে আল্লাহর আশ্রয় চাই; পরম দয়ালু, অসীম দাতা আল্লাহর নামে।","সূরা ফাতিহা পড়ো, তারপর বলো আমিন।","একটি ছোট সূরা পড়ো, যেমন সূরা ইখলাস।","আল্লাহু আকবার বলে রুকুতে যাও — পিঠ সোজা, হাত হাঁটুতে। তিনবার বলো: سُبْحَانَ رَبِّيَ الْعَظِيمِ — উচ্চারণ: সুবহানা রব্বিয়াল আযিম — অর্থ: আমার মহান রবের পবিত্রতা ঘোষণা করছি।","উঠতে উঠতে বলো: سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ — উচ্চারণ: সামিআল্লাহু লিমান হামিদাহ — অর্থ: যে আল্লাহর প্রশংসা করে, আল্লাহ তা শোনেন। সোজা দাঁড়িয়ে বলো: رَبَّنَا وَلَكَ الْحَمْدُ — উচ্চারণ: রব্বানা ওয়া লাকাল হামদ — অর্থ: হে আমাদের রব, সব প্রশংসা আপনার।","আল্লাহু আকবার বলে সিজদায় যাও: কপাল ও নাক, দুই হাত, দুই হাঁটু আর পায়ের আঙুল মাটিতে। তিনবার বলো: سُبْحَانَ رَبِّيَ الْأَعْلَى — উচ্চারণ: সুবহানা রব্বিয়াল আ''লা — অর্থ: আমার সর্বোচ্চ রবের পবিত্রতা ঘোষণা করছি।","আল্লাহু আকবার বলে একটু উঠে বসো। বলতে পারো: رَبِّ اغْفِرْ لِي — উচ্চারণ: রব্বিগফিরলি — অর্থ: হে আমার রব, আমাকে ক্ষমা করুন।","আল্লাহু আকবার বলে দ্বিতীয় সিজদা দাও, প্রথমটির মতোই। প্রথম রাকাত শেষ হলো।","আল্লাহু আকবার বলে দ্বিতীয় রাকাতের জন্য দাঁড়াও। বিসমিল্লাহ বলে সূরা ফাতিহা পড়ো, আমিন বলো, তারপর আরেকটি ছোট সূরা, যেমন সূরা কাওসার। এরপর আগের মতো রুকু, দাঁড়ানো আর দুই সিজদা।","দ্বিতীয় সিজদার পর বসে তাশাহহুদ পড়ো: আত্তাহিয়্যাতু লিল্লাহি ওয়াস সালাওয়াতু ওয়াত তাইয়্যিবাতু। আসসালামু আলাইকা আইয়্যুহান নাবিয়্যু ওয়া রাহমাতুল্লাহি ওয়া বারাকাতুহ। আসসালামু আলাইনা ওয়া আলা ইবাদিল্লাহিস সালিহিন। আশহাদু আল্লা ইলাহা ইল্লাল্লাহু ওয়া আশহাদু আন্না মুহাম্মাদান আবদুহু ওয়া রাসুলুহ। অর্থ: সব সম্মান, নামাজ ও পবিত্র কথা আল্লাহর জন্য। হে নবী, আপনার ওপর শান্তি, আল্লাহর রহমত ও বরকত। আমাদের ওপর এবং আল্লাহর নেক বান্দাদের ওপর শান্তি। আমি সাক্ষ্য দিচ্ছি, আল্লাহ ছাড়া কোনো ইলাহ নেই, আর মুহাম্মাদ তাঁর বান্দা ও রাসূল। (সহিহ বুখারি ও সহিহ মুসলিম)","তারপর দরুদে ইবরাহিম পড়ো: আল্লাহুম্মা সাল্লি আলা মুহাম্মাদিও ওয়া আলা আলি মুহাম্মাদ, কামা সাল্লাইতা আলা ইবরাহিমা ওয়া আলা আলি ইবরাহিম, ইন্নাকা হামিদুম মাজিদ। আল্লাহুম্মা বারিক আলা মুহাম্মাদিও ওয়া আলা আলি মুহাম্মাদ, কামা বারাকতা আলা ইবরাহিমা ওয়া আলা আলি ইবরাহিম, ইন্নাকা হামিদুম মাজিদ। অর্থ: হে আল্লাহ, মুহাম্মাদ ও তাঁর পরিবারের ওপর রহমত ও বরকত দিন, যেমন ইবরাহিম ও তাঁর পরিবারের ওপর দিয়েছেন; নিশ্চয়ই আপনি প্রশংসিত, মহিমান্বিত।","চাইলে একটি ছোট দোয়া পড়ো, যেমন: রব্বানা আতিনা ফিদ দুনইয়া হাসানাহ, ওয়া ফিল আখিরাতি হাসানাহ, ওয়া কিনা আযাবান নার — অর্থ: হে আমাদের রব, আমাদের দুনিয়াতে কল্যাণ দিন, আখিরাতে কল্যাণ দিন, আর জাহান্নামের আজাব থেকে রক্ষা করুন। (সূরা আল-বাকারা ২:২০১)","ডান দিকে মুখ ফিরিয়ে বলো: আসসালামু আলাইকুম ওয়া রাহমাতুল্লাহ। তারপর বাম দিকে ফিরে একই কথা বলো। নামাজ শেষ। আলহামদুলিল্লাহ!"]}}'::jsonb, 6, 1826, 4748, '{}'::text[], 'any', ARRAY['salah', 'namaz', 'fajr', 'two rakah', 'steps', 'tashahhud']::text[], false, 'in_review'::lp_review_status, 9025),
  ('isl-masjid-happy-place', 'checklist', 'islamic', 'family', 'routine', 'religious', '🕌', '{"en":"Making the masjid a happy place for children","bn":"শিশুর জন্য মসজিদকে আনন্দের জায়গা বানানো"}'::jsonb, '{"en":"The Prophet ﷺ welcomed children in his masjid. A checklist for parents, and for adults at the masjid, so children grow up loving to go.","bn":"রাসূলুল্লাহ ﷺ তাঁর মসজিদে শিশুদের স্বাগত জানাতেন। বাবা-মা ও মসজিদের বড়দের জন্য একটি চেকলিস্ট, যেন শিশুরা মসজিদে যেতে ভালোবেসে বড় হয়।"}'::jsonb, '{"en":"Children were part of life in the Prophet''s ﷺ masjid. He shortened his prayer when he heard a baby cry, out of care for the mother (Sahih al-Bukhari and Sahih Muslim). He prayed carrying his granddaughter Umamah (Sahih al-Bukhari and Sahih Muslim). Once, while giving a sermon, he saw his grandsons al-Hasan and al-Husayn stumbling towards him in their little red shirts, came down from the minbar, picked them up, and then continued (Sunan Abi Dawud, Jami'' at-Tirmidhi). He also said: do not stop the female servants of Allah from the masjids of Allah (Sahih al-Bukhari and Sahih Muslim), so mothers and girls are welcome too.\n\nA child''s memories of the masjid, a smile or a scolding, can shape how they feel about it for years.\n\nEntering the masjid: اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ — Allahummaftah li abwaba rahmatik — O Allah, open for me the doors of Your mercy. Leaving: اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ — Allahumma inni as''aluka min fadlik — O Allah, I ask You for Your favour. (Sahih Muslim)","bn":"রাসূলুল্লাহ ﷺ-এর মসজিদে শিশুরা ছিল জীবনেরই অংশ। শিশুর কান্না শুনে মায়ের কথা ভেবে তিনি নামাজ সংক্ষেপ করতেন (সহিহ বুখারি ও সহিহ মুসলিম)। নাতনি উমামাকে কোলে নিয়ে নামাজ পড়েছেন (সহিহ বুখারি ও সহিহ মুসলিম)। একবার খুতবা দেওয়ার সময় দেখলেন নাতি হাসান ও হুসাইন (রা.) লাল জামা পরে হোঁচট খেতে খেতে তাঁর দিকে আসছেন; তিনি মিম্বার থেকে নেমে তাদের কোলে তুলে নিলেন, তারপর আবার খুতবা দিলেন (সুনান আবু দাউদ, জামে তিরমিজি)। তিনি আরও বলেছেন: আল্লাহর বান্দিদের আল্লাহর মসজিদে যেতে বাধা দিয়ো না (সহিহ বুখারি ও সহিহ মুসলিম) — তাই মা ও মেয়েরাও স্বাগত।\n\nমসজিদের স্মৃতি — একটি হাসি বা একটি ধমক — বহু বছর শিশুর অনুভূতি গড়ে দিতে পারে।\n\nমসজিদে ঢোকার দোয়া: اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ — উচ্চারণ: আল্লাহুম্মাফতাহ লি আবওয়াবা রাহমাতিক — অর্থ: হে আল্লাহ, আমার জন্য আপনার রহমতের দরজাগুলো খুলে দিন। বের হওয়ার দোয়া: اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ — উচ্চারণ: আল্লাহুম্মা ইন্নি আসআলুকা মিন ফাদলিক — অর্থ: হে আল্লাহ, আমি আপনার অনুগ্রহ চাই। (সহিহ মুসলিম)"}'::jsonb, '{"items":{"en":["Start with short visits at a quiet prayer such as Asr or Maghrib, not a crowded Jumu''ah","Do wudu at home and go to the toilet before leaving","Talk through the manners on the way: soft voices, walking not running in the prayer hall, never walking right in front of someone praying","Let your child stand next to you, not alone at the back","Look for a masjid with a women''s area so mothers and daughters can come too","Bring a small, quiet book for a toddler, and step outside calmly if they cry","Greet the imam and other children, and introduce your child","Afterwards, praise one thing they did well and share a small treat like dates","Never leave a young child unattended at the masjid","If you are an adult at the masjid, smile at children and correct them gently, never by shouting or chasing them out","Keep it joyful: if a visit goes badly, try again another day without scolding"],"bn":["শুরুতে আসর বা মাগরিবের মতো শান্ত ওয়াক্তে অল্প সময়ের জন্য যান, ভিড়ের জুমায় নয়","ঘর থেকে অজু করে যান এবং বের হওয়ার আগে টয়লেট সেরে নিন","যাওয়ার পথে আদবগুলো বলুন: আস্তে কথা, নামাজের জায়গায় দৌড় নয় হাঁটা, নামাজরত কারও ঠিক সামনে দিয়ে কখনো না যাওয়া","সন্তানকে পেছনে একা নয়, আপনার পাশে দাঁড়াতে দিন","নারীদের জায়গা আছে এমন মসজিদ খুঁজুন, যেন মা ও মেয়েরাও যেতে পারেন","ছোট শিশুর জন্য একটি ছোট শান্ত বই নিন, আর কাঁদলে শান্তভাবে বাইরে নিয়ে যান","ইমাম ও অন্য শিশুদের সালাম দিন, সন্তানকে পরিচয় করিয়ে দিন","ফেরার পর সে ভালো করেছে এমন একটা কিছুর প্রশংসা করুন, আর খেজুরের মতো ছোট কিছু খেতে দিন","ছোট শিশুকে কখনো মসজিদে একা রেখে যাবেন না","আপনি মসজিদের একজন বড় মানুষ হলে শিশুদের দিকে হাসুন, আলতো করে শুধরে দিন — কখনো চিৎকার করে বা তাড়িয়ে দিয়ে নয়","আনন্দময় রাখুন: কোনোদিন ভালো না গেলে বকাঝকা না করে আরেকদিন আবার চেষ্টা করুন"]}}'::jsonb, 3, 1096, 4748, '{}'::text[], 'any', ARRAY['masjid', 'mosque', 'children', 'manners', 'girls', 'jumuah']::text[], false, 'in_review'::lp_review_status, 9026),
  ('isl-quran-learning-path', 'article', 'islamic', 'shared', 'educational', 'religious', '📖', '{"en":"A Quran learning path: from Qaida to reading to short surahs","bn":"কুরআন শেখার পথ: কায়দা থেকে তিলাওয়াত, তারপর ছোট সূরা"}'::jsonb, '{"en":"A calm, step-by-step path for learning to read the Quran, how to choose a safe and kind teacher, and why slow and steady is fine.","bn":"কুরআন পড়া শেখার শান্ত, ধাপে ধাপে পথ; নিরাপদ ও সদয় শিক্ষক কীভাবে বাছবেন; আর কেন ধীরে ধীরে এগোনোই ভালো।"}'::jsonb, '{"en":"## Why it matters\n\nThe Prophet ﷺ said: the best of you are those who learn the Quran and teach it (Sahih al-Bukhari). He also said that the one who is skilled in reciting it will be with the noble, righteous angels, and the one who recites it with difficulty, stumbling over it, gets a double reward (Sahih al-Bukhari and Sahih Muslim). That second promise is for every child who struggles. Allah says that He has made the Quran easy to remember (Surah Al-Qamar 54:17).\n\n## The path, step by step\n\n1. **Listening (birth to 3 years).** Recite and play the Quran softly at home. Babies and toddlers absorb its sound.\n2. **Short surahs by ear (3–5 years).** Al-Fatiha and the short surahs, learned by repeating after you.\n3. **The letters (around 4–6 years).** A Qaida book, such as the Noorani Qaida, teaches the Arabic letters, how each sounds (makhraj), and the short vowels.\n4. **Joining letters.** Reading words with harakat, sukun, shaddah and long vowels, still in the Qaida.\n5. **Reading from the Mushaf.** Usually starting with Juz ''Amma, the last part of the Quran, with a teacher listening.\n6. **Basic tajwid.** Rules for beautiful, correct recitation, learned gradually while reading.\n7. **Understanding.** Alongside reading, learn the meaning in Bangla, a few ayat at a time, so the Quran speaks to the heart.\n\nThe ages are only a guide. Some children move fast, some slowly. Both are fine.\n\n## Choosing a teacher\n\nMany children learn at a morning maktab in the local masjid, with a home tutor, or in an online class. Whichever you choose:\n\n- Choose a teacher you know and trust, with good character and correct recitation.\n- Lessons should be in an open place where another adult can see or hear.\n- No hitting, no harsh punishment, no humiliation. Tell the teacher this kindly at the start.\n- Ask your child often how lessons feel. If they seem afraid, upset or do not want to go, listen carefully and find out why.\n\n## Making it work at home\n\n- Ten to fifteen minutes every day is better than an hour once a week.\n- Sit with your child while they practise, even if you are still learning yourself. Parents learning alongside children is a beautiful example.\n- Celebrate milestones: finishing the Qaida, the first page of the Mushaf, finishing Juz ''Amma.\n- If a child has dyslexia, attention difficulties or another learning difference, go slower, use more listening, and remember the double reward.","bn":"## কেন জরুরি\n\nরাসূলুল্লাহ ﷺ বলেছেন: তোমাদের মধ্যে সেই উত্তম, যে কুরআন শেখে ও শেখায় (সহিহ বুখারি)। তিনি আরও বলেছেন, যে দক্ষতার সাথে কুরআন পড়ে সে সম্মানিত নেককার ফেরেশতাদের সাথে থাকবে, আর যে আটকে আটকে কষ্ট করে পড়ে সে দ্বিগুণ সওয়াব পাবে (সহিহ বুখারি ও সহিহ মুসলিম)। দ্বিতীয় প্রতিশ্রুতিটি প্রত্যেক সেই শিশুর জন্য, যার শিখতে কষ্ট হয়। আল্লাহ বলেন, তিনি কুরআনকে মনে রাখার জন্য সহজ করে দিয়েছেন (সূরা আল-কামার ৫৪:১৭)।\n\n## ধাপে ধাপে পথ\n\n1. **শোনা (জন্ম থেকে ৩ বছর)।** ঘরে আস্তে কুরআন তিলাওয়াত করুন বা চালান। শিশুরা এর সুর আত্মস্থ করে।\n2. **শুনে শুনে ছোট সূরা (৩–৫ বছর)।** সূরা ফাতিহা ও ছোট সূরাগুলো আপনার পরে পরে বলে শেখা।\n3. **হরফ (প্রায় ৪–৬ বছর)।** নূরানী কায়দার মতো কায়দা বই আরবি হরফ, প্রতিটির উচ্চারণস্থান (মাখরাজ) ও হরকত শেখায়।\n4. **হরফ জোড়া দেওয়া।** কায়দাতেই হরকত, সাকিন, তাশদিদ ও মদসহ শব্দ পড়া।\n5. **কুরআন শরিফ থেকে পড়া।** সাধারণত আমপারা (কুরআনের শেষ পারা) দিয়ে শুরু, শিক্ষক শুনবেন।\n6. **প্রাথমিক তাজবিদ।** সুন্দর ও শুদ্ধ তিলাওয়াতের নিয়ম, পড়তে পড়তে ধীরে ধীরে শেখা।\n7. **অর্থ বোঝা।** পড়ার পাশাপাশি কয়েক আয়াত করে বাংলায় অর্থ শিখুন, যেন কুরআন মনের সাথে কথা বলে।\n\nবয়সগুলো শুধু একটা ধারণা। কেউ দ্রুত এগোয়, কেউ ধীরে। দুটোই ঠিক আছে।\n\n## শিক্ষক বাছাই\n\nঅনেক শিশু মহল্লার মসজিদের সকালের মক্তবে, বাসায় হুজুর বা আপার কাছে, বা অনলাইন ক্লাসে শেখে। যেটাই বাছুন:\n\n- চেনা ও বিশ্বস্ত শিক্ষক বাছুন, যাঁর চরিত্র ভালো ও তিলাওয়াত শুদ্ধ।\n- পড়া হবে খোলা জায়গায়, যেখানে আরেকজন বড় মানুষ দেখতে বা শুনতে পান।\n- মারধর নয়, কঠোর শাস্তি নয়, অপমান নয়। শুরুতেই শিক্ষককে বিনয়ের সাথে এটা জানিয়ে দিন।\n- সন্তানকে প্রায়ই জিজ্ঞেস করুন পড়া কেমন লাগছে। সে ভয় পেলে, মন খারাপ করলে বা যেতে না চাইলে মন দিয়ে শুনুন এবং কারণ খুঁজে বের করুন।\n\n## ঘরে কীভাবে চালাবেন\n\n- সপ্তাহে একবার এক ঘণ্টার চেয়ে প্রতিদিন দশ-পনেরো মিনিট ভালো।\n- সন্তান অনুশীলন করার সময় পাশে বসুন, আপনি নিজে এখনও শিখছেন হলেও। সন্তানের সাথে বাবা-মায়ের শেখা এক সুন্দর দৃষ্টান্ত।\n- ছোট ছোট সাফল্য উদযাপন করুন: কায়দা শেষ, কুরআন শরিফের প্রথম পৃষ্ঠা, আমপারা শেষ।\n- ডিসলেক্সিয়া, মনোযোগের সমস্যা বা অন্য শেখার ভিন্নতা থাকলে ধীরে চলুন, বেশি শোনান, আর দ্বিগুণ সওয়াবের কথা মনে রাখুন।"}'::jsonb, '{"steps":{"en":["Choose a Qaida book and a trusted teacher or maktab","Set a fixed daily time of 10 to 15 minutes","Sit with your child during home practice","Move to the Mushaf (Juz ''Amma) when the teacher says they are ready","Learn the meaning of what they read, a few ayat at a time","Celebrate each milestone together"],"bn":["একটি কায়দা বই আর বিশ্বস্ত শিক্ষক বা মক্তব বাছুন","প্রতিদিন ১০–১৫ মিনিটের একটি নির্দিষ্ট সময় ঠিক করুন","ঘরে অনুশীলনের সময় সন্তানের পাশে বসুন","শিক্ষক প্রস্তুত বললে কুরআন শরিফে (আমপারা) যান","যা পড়ছে তার অর্থ কয়েক আয়াত করে শিখুন","প্রতিটি ধাপ পার হলে একসাথে উদযাপন করুন"]}}'::jsonb, 4, 1461, 4748, '{}'::text[], 'any', ARRAY['quran', 'qaida', 'noorani', 'reading', 'tajweed', 'maktab', 'teacher']::text[], false, 'in_review'::lp_review_status, 9027),
  ('isl-short-surahs-list', 'checklist', 'islamic', 'family', 'routine', 'religious', '🌟', '{"en":"First short surahs to memorise: order and tips","bn":"প্রথমে মুখস্থ করার ছোট সূরা: ক্রম ও পরামর্শ"}'::jsonb, '{"en":"Eleven short surahs in a suggested order, with their number, length and a one-line meaning, plus tips that make memorising joyful.","bn":"প্রস্তাবিত ক্রমে এগারোটি ছোট সূরা — নম্বর, আয়াত সংখ্যা ও এক লাইনের অর্থসহ — আর মুখস্থকে আনন্দময় করার পরামর্শ।"}'::jsonb, '{"en":"These surahs are short, used every day in salah, and full of meaning children can understand.\n\n- Learn one ayah at a time. Say it together many times through the day: in the car, at bath time, before sleep.\n- Listen often to a clear, slow reciter, so your child hears the correct sounds.\n- Tell the story or meaning behind each surah in Bangla before memorising it.\n- Use new surahs in salah straight away. That is what they are for.\n- Review old surahs once a week so they are not forgotten.\n- A new surah every month or so is a good pace for young children. Some need longer, and that is fine.\n- Never compare with cousins or classmates. Praise effort and celebrate each surah finished.\n\nThe Prophet ﷺ said that Al-Ikhlas is equal to a third of the Quran (Sahih al-Bukhari), and before sleeping he would recite Al-Ikhlas, Al-Falaq and An-Nas, blow into his hands and wipe over his body (Sahih al-Bukhari). Doing this at bedtime is a lovely way to practise.","bn":"এই সূরাগুলো ছোট, প্রতিদিন নামাজে পড়া হয়, আর এমন অর্থে ভরা যা শিশুরা বুঝতে পারে।\n\n- একবারে একটি আয়াত শিখুন। সারাদিন একসাথে বারবার বলুন: গাড়িতে, গোসলের সময়, ঘুমানোর আগে।\n- স্পষ্ট ও ধীর কোনো কারির তিলাওয়াত প্রায়ই শোনান, যেন শিশু সঠিক উচ্চারণ শোনে।\n- মুখস্থ শুরুর আগে প্রতিটি সূরার ঘটনা বা অর্থ বাংলায় বলুন।\n- নতুন সূরা সাথে সাথে নামাজে পড়ুন। এগুলো তো এজন্যই।\n- সপ্তাহে একবার পুরনো সূরাগুলো ঝালাই করুন, যেন ভুলে না যায়।\n- ছোট শিশুর জন্য মাসে একটি করে নতুন সূরা ভালো গতি। কারও বেশি সময় লাগে, তাতে সমস্যা নেই।\n- কাজিন বা সহপাঠীর সাথে কখনো তুলনা করবেন না। চেষ্টার প্রশংসা করুন, প্রতিটি সূরা শেষ হলে উদযাপন করুন।\n\nরাসূলুল্লাহ ﷺ বলেছেন, সূরা ইখলাস কুরআনের এক-তৃতীয়াংশের সমান (সহিহ বুখারি), আর ঘুমানোর আগে তিনি সূরা ইখলাস, ফালাক ও নাস পড়ে হাতে ফুঁ দিয়ে শরীরে বুলিয়ে নিতেন (সহিহ বুখারি)। ঘুমের আগে এভাবে করা অনুশীলনের সুন্দর উপায়।"}'::jsonb, '{"items":{"en":["1. Al-Fatiha (Surah 1), 7 ayat: The Opening; praise of Allah and asking for the straight path. Recited in every rak''ah.","2. Al-Ikhlas (Surah 112), 4 ayat: Allah is One; He has no parent, no child and no equal.","3. Al-Falaq (Surah 113), 5 ayat: seeking Allah''s protection from the harm of what He created, darkness, and envy.","4. An-Nas (Surah 114), 6 ayat: seeking protection with the Lord of people from the whisperer who sneaks away.","5. Al-Kawthar (Surah 108), 3 ayat: the shortest surah; Allah''s gift of abundant good, so pray and sacrifice for Him.","6. Al-''Asr (Surah 103), 3 ayat: by time, people are at a loss except those who believe, do good, and encourage truth and patience.","7. An-Nasr (Surah 110), 3 ayat: when Allah''s help comes, glorify Him and ask His forgiveness.","8. Al-Kafirun (Surah 109), 6 ayat: a clear, calm statement of faith: for you your religion, and for me mine.","9. Al-Ma''un (Surah 107), 7 ayat: caring for orphans and the poor, praying sincerely, and not holding back small kindnesses.","10. Quraysh (Surah 106), 4 ayat: thank the Lord of the Ka''bah, who gave food against hunger and safety against fear.","11. Al-Fil (Surah 105), 5 ayat: the people of the elephant, and how Allah protected His House with flocks of birds."],"bn":["১. আল-ফাতিহা (সূরা ১), ৭ আয়াত: সূচনা; আল্লাহর প্রশংসা আর সরল পথ চাওয়া। প্রতি রাকাতে পড়া হয়।","২. আল-ইখলাস (সূরা ১১২), ৪ আয়াত: আল্লাহ এক; তাঁর কোনো পিতা-মাতা নেই, সন্তান নেই, সমকক্ষ নেই।","৩. আল-ফালাক (সূরা ১১৩), ৫ আয়াত: আল্লাহর সৃষ্টির অনিষ্ট, অন্ধকার ও হিংসা থেকে তাঁর আশ্রয় চাওয়া।","৪. আন-নাস (সূরা ১১৪), ৬ আয়াত: মানুষের রবের কাছে আশ্রয় চাওয়া, সেই কুমন্ত্রণাদাতা থেকে যে আড়ালে সরে যায়।","৫. আল-কাওসার (সূরা ১০৮), ৩ আয়াত: সবচেয়ে ছোট সূরা; আল্লাহর দেওয়া অফুরন্ত কল্যাণ, তাই তাঁর জন্য নামাজ পড়ো ও কুরবানি করো।","৬. আল-আসর (সূরা ১০৩), ৩ আয়াত: সময়ের কসম, মানুষ ক্ষতির মধ্যে, তারা ছাড়া যারা ঈমান আনে, ভালো কাজ করে, আর সত্য ও ধৈর্যের উপদেশ দেয়।","৭. আন-নাসর (সূরা ১১০), ৩ আয়াত: আল্লাহর সাহায্য এলে তাঁর পবিত্রতা ঘোষণা করো ও ক্ষমা চাও।","৮. আল-কাফিরুন (সূরা ১০৯), ৬ আয়াত: ঈমানের স্পষ্ট ও শান্ত ঘোষণা: তোমাদের দ্বীন তোমাদের, আমার দ্বীন আমার।","৯. আল-মাউন (সূরা ১০৭), ৭ আয়াত: এতিম ও গরিবের যত্ন, আন্তরিকভাবে নামাজ, আর ছোট ছোট সাহায্য আটকে না রাখা।","১০. কুরাইশ (সূরা ১০৬), ৪ আয়াত: কাবার রবের শুকরিয়া, যিনি ক্ষুধায় খাবার আর ভয়ে নিরাপত্তা দিয়েছেন।","১১. আল-ফিল (সূরা ১০৫), ৫ আয়াত: হাতিওয়ালাদের ঘটনা, আর আল্লাহ কীভাবে ঝাঁকে ঝাঁকে পাখি দিয়ে তাঁর ঘর রক্ষা করেছেন।"]}}'::jsonb, 3, 1096, 4748, '{}'::text[], 'any', ARRAY['quran', 'memorisation', 'hifz', 'short surahs', 'juz amma']::text[], false, 'in_review'::lp_review_status, 9028),
  ('isl-quran-listening-together', 'activity', 'islamic', 'family', 'routine', 'religious', '🎧', '{"en":"Listening to and reciting the Quran together","bn":"একসাথে কুরআন শোনা ও তিলাওয়াত"}'::jsonb, '{"en":"A few calm minutes of Quran each day, from a baby in your arms to a teen reciting to you. Simple ways to make it a family habit.","bn":"প্রতিদিন কয়েক মিনিট শান্তভাবে কুরআন — কোলের শিশু থেকে শুরু করে আপনাকে তিলাওয়াত শোনানো কিশোর পর্যন্ত। পরিবারের অভ্যাস বানানোর সহজ উপায়।"}'::jsonb, '{}'::jsonb, '{"why":{"en":"Allah says: when the Quran is recited, listen to it and be silent, so that you may receive mercy (Surah Al-A''raf 7:204). The Prophet ﷺ loved to hear it from others: he asked Ibn Mas''ud to recite to him, and as he listened to Surah An-Nisa his eyes filled with tears (Sahih al-Bukhari and Sahih Muslim). He said: recite the Quran, for it will come on the Day of Resurrection as an intercessor for its companions (Sahih Muslim), and that Shaytan runs from a house in which Surah Al-Baqarah is recited (Sahih Muslim). Listening together fills the home with peace and gives children a memory of the Quran in their parents'' voices.","bn":"আল্লাহ বলেন: যখন কুরআন তিলাওয়াত করা হয়, মনোযোগ দিয়ে শোনো ও চুপ থাকো, যেন তোমাদের প্রতি রহমত করা হয় (সূরা আল-আ''রাফ ৭:২০৪)। রাসূলুল্লাহ ﷺ অন্যের কাছ থেকে কুরআন শুনতে ভালোবাসতেন: তিনি ইবনে মাসউদ (রা.)-কে তিলাওয়াত করতে বলেছিলেন, আর সূরা আন-নিসা শুনতে শুনতে তাঁর চোখ অশ্রুতে ভরে গিয়েছিল (সহিহ বুখারি ও সহিহ মুসলিম)। তিনি বলেছেন: কুরআন পড়ো, কিয়ামতের দিন এটি তার পাঠকদের জন্য সুপারিশকারী হয়ে আসবে (সহিহ মুসলিম); আর যে ঘরে সূরা আল-বাকারা পড়া হয়, শয়তান সেখান থেকে পালায় (সহিহ মুসলিম)। একসাথে শোনা ঘরকে শান্তিতে ভরে দেয়, আর শিশুর মনে বাবা-মায়ের কণ্ঠে কুরআনের স্মৃতি গেঁথে দেয়।"},"items":{"en":["A Mushaf, or a trusted Quran app or recording","A quiet corner without the television on","Five to fifteen minutes at the same time each day"],"bn":["কুরআন শরিফ, অথবা নির্ভরযোগ্য কুরআন অ্যাপ বা রেকর্ডিং","টিভি বন্ধ রেখে একটি শান্ত কোণ","প্রতিদিন একই সময়ে পাঁচ থেকে পনেরো মিনিট"]},"steps":{"en":["Pick a daily time that already exists, such as after Fajr or after Maghrib.","With a baby: recite softly while feeding or rocking. Your voice is the best recording.","With a toddler: recite one short surah together, slowly, and let them join in on the words they know.","With a school-age child: take turns, one ayah each. Listen kindly; correct mistakes gently afterwards, not in the middle.","With a teen: ask them to recite to you, as the Prophet ﷺ asked Ibn Mas''ud. Tell them how much you enjoy hearing them.","Choose one ayah and talk about its meaning in Bangla for a minute or two.","Use audio, not video, for small children, and keep it as a focused time rather than background noise.","On busy or hard days, even one ayah together counts. Keep the habit alive without pressure."],"bn":["দিনের এমন একটি সময় বাছুন যা আগেই রুটিনে আছে, যেমন ফজরের পর বা মাগরিবের পর।","শিশুর সাথে: দুধ খাওয়ানো বা দোলানোর সময় আস্তে তিলাওয়াত করুন। আপনার কণ্ঠই সবচেয়ে ভালো রেকর্ডিং।","ছোট বাচ্চার সাথে: একসাথে ধীরে একটি ছোট সূরা পড়ুন, আর যে শব্দগুলো সে জানে সেগুলোতে তাকে যোগ দিতে দিন।","স্কুলপড়ুয়া সন্তানের সাথে: পালা করে এক আয়াত করে পড়ুন। আদর করে শুনুন; ভুল হলে মাঝখানে না থামিয়ে পরে আলতো করে শুধরে দিন।","কিশোরের সাথে: তাকে আপনাকে তিলাওয়াত শোনাতে বলুন, যেমন রাসূলুল্লাহ ﷺ ইবনে মাসউদ (রা.)-কে বলেছিলেন। বলুন তার তিলাওয়াত শুনতে আপনার কত ভালো লাগে।","একটি আয়াত বেছে নিয়ে এক-দুই মিনিট বাংলায় তার অর্থ নিয়ে কথা বলুন।","ছোট শিশুদের জন্য ভিডিও নয়, অডিও ব্যবহার করুন; আর এটাকে পেছনের আওয়াজ না বানিয়ে মনোযোগের সময় রাখুন।","ব্যস্ত বা কঠিন দিনে একসাথে এক আয়াতও গোনা হয়। চাপ ছাড়া অভ্যাসটা বাঁচিয়ে রাখুন।"]},"example":{"en":"After Maghrib, Shirin''s family sits on the bed for ten minutes. Her father recites Surah Al-Mulk a few ayat at a time, her daughter of nine reads one ayah, and the two-year-old shouts the “Allah” she recognises. Some evenings it lasts three minutes. It still counts.","bn":"মাগরিবের পর শিরিনের পরিবার দশ মিনিট খাটে বসে। বাবা কয়েক আয়াত করে সূরা মুলক পড়েন, নয় বছরের মেয়ে এক আয়াত পড়ে, আর দুই বছরের ছেলেটা চেনা শব্দ “আল্লাহ” শুনে জোরে বলে ওঠে। কোনো কোনো সন্ধ্যায় তিন মিনিটেই শেষ হয়। তবু সেটাও গোনা হয়।"}}'::jsonb, 3, NULL, NULL, '{}'::text[], 'any', ARRAY['quran', 'listening', 'recitation', 'family time', 'tilawah']::text[], false, 'in_review'::lp_review_status, 9029),
  ('isl-story-adam', 'story', 'islamic', 'child', 'educational', 'religious', '🌱', '{"en":"Adam (peace be upon him): the first person, and the first “sorry”","bn":"আদম (আ.): প্রথম মানুষ, আর প্রথম “দুঃখিত”"}'::jsonb, '{"en":"How Allah created Adam, honoured him with knowledge, and forgave him when he said sorry. A story about pride and forgiveness.","bn":"আল্লাহ কীভাবে আদম (আ.)-কে সৃষ্টি করলেন, জ্ঞান দিয়ে সম্মানিত করলেন, আর তিনি দুঃখিত বললে ক্ষমা করলেন। অহংকার আর ক্ষমার গল্প।"}'::jsonb, '{"en":"Long, long ago, before there was a single person on the earth, Allah told the angels that He was going to place a new creation there (Surah Al-Baqarah 2:30).\n\nAllah made Adam from clay. He shaped him, and then He breathed life into him (Surah Sad 38:71–72). Adam opened his eyes. He was the very first human being.\n\nThen Allah taught Adam the names of all things (Surah Al-Baqarah 2:31). When Allah asked the angels about those names, they said: Glory be to You! We only know what You have taught us (Surah Al-Baqarah 2:32). But Adam knew, and he told them. Knowledge was Allah''s special gift to people.\n\nAllah told the angels to bow down to Adam to honour him. All the angels bowed. But Iblis refused. He was proud and said: I am better than him. You made me from fire, and You made him from clay (Surah Al-A''raf 7:12). Because of his pride, Iblis was sent away, and he became the enemy of people.\n\nAllah let Adam and his wife live in a beautiful garden. They could eat anything they liked, except for one tree. Allah said: do not go near this tree (Surah Al-Baqarah 2:35).\n\nBut Shaytan whispered to them. He told them the tree was good for them, and he even swore that he only wanted to help (Surah Al-A''raf 7:20–21). Adam and his wife forgot Allah''s warning, and they ate from the tree.\n\nStraight away they felt sorry. They did not blame anyone else. They said: Rabbana zalamna anfusana, wa in lam taghfir lana wa tarhamna lanakunanna minal-khasirin. Our Lord, we have wronged ourselves. If You do not forgive us and have mercy on us, we will surely be lost (Surah Al-A''raf 7:23).\n\nAnd Allah forgave them. He is the One who accepts repentance, the Most Merciful (Surah Al-Baqarah 2:37). Then Allah sent them to live on the earth, to grow food, to raise children, and to worship Him, and He promised to send guidance to them (Surah Al-Baqarah 2:38).\n\n## The lesson\n\nEveryone makes mistakes, even the very first person. Iblis was proud and would not say sorry. Adam admitted his mistake and asked Allah to forgive him. When we do something wrong, we can say sorry to Allah and to the people we hurt. Allah loves to forgive.","bn":"অনেক অনেক দিন আগে, পৃথিবীতে যখন একজন মানুষও ছিল না, আল্লাহ ফেরেশতাদের জানালেন যে তিনি সেখানে এক নতুন সৃষ্টি পাঠাবেন (সূরা আল-বাকারা ২:৩০)।\n\nআল্লাহ মাটি দিয়ে আদমকে বানালেন। তাঁকে আকৃতি দিলেন, তারপর তাঁর মধ্যে প্রাণ ফুঁকে দিলেন (সূরা সোয়াদ ৩৮:৭১–৭২)। আদম চোখ মেললেন। তিনিই ছিলেন সবচেয়ে প্রথম মানুষ।\n\nতারপর আল্লাহ আদমকে সবকিছুর নাম শেখালেন (সূরা আল-বাকারা ২:৩১)। আল্লাহ যখন ফেরেশতাদের সেই নামগুলো জিজ্ঞেস করলেন, তাঁরা বললেন: আপনি পবিত্র! আপনি যা শিখিয়েছেন তার বাইরে আমরা কিছুই জানি না (সূরা আল-বাকারা ২:৩২)। কিন্তু আদম জানতেন, আর তিনি নামগুলো বলে দিলেন। জ্ঞান ছিল মানুষের জন্য আল্লাহর বিশেষ উপহার।\n\nআদমকে সম্মান জানাতে আল্লাহ ফেরেশতাদের সিজদা করতে বললেন। সব ফেরেশতা সিজদা করলেন। কিন্তু ইবলিস করল না। সে অহংকার করে বলল: আমি তার চেয়ে ভালো। আপনি আমাকে আগুন দিয়ে বানিয়েছেন, আর তাকে মাটি দিয়ে (সূরা আল-আ''রাফ ৭:১২)। অহংকারের কারণে ইবলিসকে বের করে দেওয়া হলো, আর সে মানুষের শত্রু হয়ে গেল।\n\nআল্লাহ আদম ও তাঁর স্ত্রীকে একটি সুন্দর বাগানে থাকতে দিলেন। তাঁরা যা খুশি খেতে পারতেন, শুধু একটি গাছ ছাড়া। আল্লাহ বললেন: এই গাছের কাছে যেয়ো না (সূরা আল-বাকারা ২:৩৫)।\n\nকিন্তু শয়তান তাঁদের কানে কানে কুমন্ত্রণা দিল। বলল, গাছটা তাঁদের জন্য ভালো, এমনকি কসম খেয়ে বলল যে সে শুধু উপকার করতে চায় (সূরা আল-আ''রাফ ৭:২০–২১)। আদম ও তাঁর স্ত্রী আল্লাহর সতর্কবাণী ভুলে গেলেন, আর গাছ থেকে খেয়ে ফেললেন।\n\nসাথে সাথে তাঁদের খুব খারাপ লাগল। তাঁরা অন্য কাউকে দোষ দিলেন না। তাঁরা বললেন: রব্বানা যালামনা আনফুসানা, ওয়া ইল্লাম তাগফির লানা ওয়া তারহামনা লানাকুনান্না মিনাল খাসিরিন। হে আমাদের রব, আমরা নিজেদের ওপর জুলুম করেছি। আপনি যদি আমাদের ক্ষমা না করেন আর দয়া না করেন, আমরা অবশ্যই ক্ষতিগ্রস্ত হব (সূরা আল-আ''রাফ ৭:২৩)।\n\nআর আল্লাহ তাঁদের ক্ষমা করে দিলেন। তিনিই তওবা কবুলকারী, পরম দয়ালু (সূরা আল-বাকারা ২:৩৭)। তারপর আল্লাহ তাঁদের পৃথিবীতে পাঠালেন — সেখানে ফসল ফলাতে, সন্তান বড় করতে আর তাঁর ইবাদত করতে — আর কথা দিলেন যে তাঁদের কাছে পথনির্দেশ পাঠাবেন (সূরা আল-বাকারা ২:৩৮)।\n\n## শিক্ষা\n\nসবাই ভুল করে, এমনকি সবচেয়ে প্রথম মানুষটিও। ইবলিস অহংকার করেছিল, দুঃখিত বলেনি। আদম (আ.) নিজের ভুল স্বীকার করে আল্লাহর কাছে ক্ষমা চেয়েছিলেন। আমরা কোনো ভুল করলে আল্লাহর কাছে আর যাকে কষ্ট দিয়েছি তার কাছে দুঃখিত বলতে পারি। আল্লাহ ক্ষমা করতে ভালোবাসেন।"}'::jsonb, '{}'::jsonb, 4, 1096, 4748, '{}'::text[], 'any', ARRAY['prophet story', 'adam', 'saying sorry', 'forgiveness', 'pride', 'bedtime story']::text[], false, 'in_review'::lp_review_status, 9030),
  ('isl-story-nuh', 'story', 'islamic', 'child', 'educational', 'religious', '⛵', '{"en":"Nuh (peace be upon him) and the great ship","bn":"নূহ (আ.) আর বিশাল নৌকা"}'::jsonb, '{"en":"Nuh called his people to Allah for hundreds of years, kept building when they laughed, and Allah kept the believers safe. A story about patience.","bn":"নূহ (আ.) শত শত বছর মানুষকে আল্লাহর দিকে ডেকেছেন, তারা হাসলেও নৌকা বানানো থামাননি, আর আল্লাহ ঈমানদারদের নিরাপদ রেখেছেন। ধৈর্যের গল্প।"}'::jsonb, '{"en":"A long time after Adam, people began to forget Allah. They made statues and worshipped them instead. So Allah sent a prophet named Nuh to remind them.\n\nNuh said to his people: worship Allah alone. Ask Him to forgive you, for He is always ready to forgive. He will send you rain, and give you gardens and rivers (Surah Nuh 71:10–12).\n\nNuh spoke to them by day and by night. He spoke to them in groups and one by one (Surah Nuh 71:5–9). But most of them put their fingers in their ears and pulled their clothes over their heads so they would not hear (Surah Nuh 71:7). Nuh did not give up. He kept calling them for nine hundred and fifty years (Surah Al-''Ankabut 29:14). Still, only a few people believed.\n\nThen Allah told Nuh to build a ship (Surah Hud 11:37). Nuh began to work. Every time the chiefs of his people walked past, they laughed at him (Surah Hud 11:38). Nuh did not stop. He kept building, trusting Allah.\n\nWhen the time came, water poured down from the sky and gushed up from the earth (Surah Al-Qamar 54:11–12). Allah told Nuh to bring onto the ship a pair of every kind of animal, his family, and the people who believed (Surah Hud 11:40). Nuh said: Bismillahi majreha wa mursaha. In the name of Allah it sails and it stops (Surah Hud 11:41).\n\nThe ship sailed on waves as big as mountains (Surah Hud 11:42). Sadly, not everyone listened, not even one of Nuh''s own sons. Nuh called to him with love: my son, come with us! But he refused, and the waves came between them (Surah Hud 11:42–43).\n\nAt last Allah said: O earth, swallow your water. O sky, stop. The water went down, and the ship came to rest on Mount al-Judi (Surah Hud 11:44). Nuh and the believers stepped out safely, with peace and blessings from Allah (Surah Hud 11:48).\n\n## The lesson\n\nNuh kept doing what was right for a very long time, even when people laughed at him and did not listen. He was patient and kind, and he trusted Allah. When others laugh at us for doing good, we can be patient like Nuh and keep going.","bn":"আদম (আ.)-এর অনেক পরে মানুষ আল্লাহকে ভুলে যেতে শুরু করল। তারা মূর্তি বানিয়ে সেগুলোর পূজা করতে লাগল। তাই আল্লাহ তাদের মনে করিয়ে দিতে নূহ নামে একজন নবী পাঠালেন।\n\nনূহ (আ.) তাঁর জাতিকে বললেন: শুধু আল্লাহর ইবাদত করো। তাঁর কাছে ক্ষমা চাও, তিনি সবসময় ক্ষমা করতে প্রস্তুত। তিনি তোমাদের বৃষ্টি দেবেন, বাগান আর নদী দেবেন (সূরা নূহ ৭১:১০–১২)।\n\nনূহ (আ.) দিনে-রাতে তাদের সাথে কথা বলতেন। দল বেঁধে বলতেন, আবার একজন একজন করেও বলতেন (সূরা নূহ ৭১:৫–৯)। কিন্তু তাদের বেশিরভাগ কানে আঙুল দিত আর কাপড় দিয়ে মাথা ঢেকে ফেলত, যেন শুনতে না হয় (সূরা নূহ ৭১:৭)। নূহ (আ.) হাল ছাড়েননি। সাড়ে নয়শো বছর ধরে তিনি তাদের ডেকেছেন (সূরা আল-আনকাবুত ২৯:১৪)। তবু অল্প কয়েকজনই ঈমান আনল।\n\nতারপর আল্লাহ নূহ (আ.)-কে একটি নৌকা বানাতে বললেন (সূরা হুদ ১১:৩৭)। নূহ (আ.) কাজ শুরু করলেন। তাঁর জাতির সর্দাররা যতবার পাশ দিয়ে যেত, ততবার তাঁকে নিয়ে হাসত (সূরা হুদ ১১:৩৮)। নূহ (আ.) থামেননি। আল্লাহর ওপর ভরসা করে বানিয়েই চললেন।\n\nসময় যখন এল, আকাশ থেকে পানি ঝরতে লাগল আর মাটি থেকে পানি উথলে উঠল (সূরা আল-কামার ৫৪:১১–১২)। আল্লাহ নূহ (আ.)-কে বললেন প্রত্যেক প্রকার প্রাণীর এক জোড়া, তাঁর পরিবার আর ঈমানদারদের নৌকায় তুলতে (সূরা হুদ ১১:৪০)। নূহ (আ.) বললেন: বিসমিল্লাহি মাজরেহা ওয়া মুরসাহা। আল্লাহর নামেই এর চলা আর থামা (সূরা হুদ ১১:৪১)।\n\nপাহাড়ের মতো বড় বড় ঢেউয়ের ওপর দিয়ে নৌকা চলল (সূরা হুদ ১১:৪২)। দুঃখের কথা, সবাই কথা শোনেনি — এমনকি নূহ (আ.)-এর এক ছেলেও না। নূহ (আ.) ভালোবাসা দিয়ে তাকে ডাকলেন: বাবা, আমাদের সাথে চলে এসো! কিন্তু সে রাজি হলো না, আর ঢেউ তাদের মাঝে আড়াল হয়ে দাঁড়াল (সূরা হুদ ১১:৪২–৪৩)।\n\nশেষে আল্লাহ বললেন: হে জমিন, তোমার পানি শুষে নাও। হে আকাশ, থামো। পানি নেমে গেল, আর নৌকা জুদি পাহাড়ে এসে থামল (সূরা হুদ ১১:৪৪)। নূহ (আ.) আর ঈমানদাররা আল্লাহর দেওয়া শান্তি ও বরকত নিয়ে নিরাপদে নেমে এলেন (সূরা হুদ ১১:৪৮)।\n\n## শিক্ষা\n\nমানুষ হাসলেও, কথা না শুনলেও নূহ (আ.) অনেক অনেক দিন ধরে ঠিক কাজটাই করে গেছেন। তিনি ধৈর্যশীল ও দয়ালু ছিলেন, আর আল্লাহর ওপর ভরসা রাখতেন। ভালো কাজ করার জন্য কেউ আমাদের নিয়ে হাসলে আমরাও নূহ (আ.)-এর মতো ধৈর্য ধরে এগিয়ে যেতে পারি।"}'::jsonb, '{}'::jsonb, 4, 1096, 4748, '{}'::text[], 'any', ARRAY['prophet story', 'nuh', 'noah', 'ark', 'patience', 'bedtime story']::text[], false, 'in_review'::lp_review_status, 9031),
  ('isl-story-ibrahim', 'story', 'islamic', 'child', 'educational', 'religious', '🔥', '{"en":"Ibrahim (peace be upon him): the young man who thought","bn":"ইবরাহিম (আ.): যে তরুণ ভেবে দেখেছিলেন"}'::jsonb, '{"en":"Ibrahim looked at the stars, the moon and the sun, and found the One who made them. He stayed gentle with his father and brave before the fire.","bn":"ইবরাহিম (আ.) তারা, চাঁদ আর সূর্যের দিকে তাকিয়ে সেগুলোর স্রষ্টাকে খুঁজে পেয়েছিলেন। বাবার সাথে নরম ছিলেন, আর আগুনের সামনে সাহসী।"}'::jsonb, '{"en":"When Ibrahim was a young man, his people worshipped statues made of stone and wood. Even his own father made and served them. Ibrahim wondered: how can something we carve with our own hands be our Lord?\n\nOne night Ibrahim looked up and saw a bright star. Is this my Lord? he said. But the star set and disappeared. I do not love things that disappear, he said. Then the moon rose, shining. Is this my Lord? But the moon set too. In the morning the great sun rose. This is the biggest! But in the evening the sun set as well. Ibrahim said: I turn my face to the One who created the heavens and the earth (Surah Al-An''am 6:76–79).\n\nIbrahim spoke to his father gently. O my dear father, why do you worship something that cannot hear, cannot see, and cannot help you at all? (Surah Maryam 19:42). His father became angry and told him to go away. But Ibrahim answered: peace be upon you. I will ask my Lord to forgive you (Surah Maryam 19:46–47). Even when they disagreed, he stayed kind.\n\nOne day, while the people were away, Ibrahim went to their temple and broke the statues into pieces, all except the biggest one (Surah Al-Anbiya 21:57–58). When the people came back, they cried: who did this? They brought Ibrahim. He pointed to the biggest statue and said: ask them, if they can speak! (Surah Al-Anbiya 21:62–63).\n\nThe people knew that statues cannot speak. For a moment they felt ashamed. But instead of thinking, they became angry. Burn him! they shouted (Surah Al-Anbiya 21:68). They built a huge fire and threw Ibrahim into it.\n\nBut Allah said: O fire, be cool and safe for Ibrahim (Surah Al-Anbiya 21:69). And the fire did not hurt him at all. Ibrahim came out safe.\n\n## The lesson\n\nIbrahim used his mind to think about Allah''s creation, and it led him to Allah. He was brave and stood up for the truth. And even when he disagreed with his father, he spoke to him with love and respect. We can think, be brave, and stay kind, just like Ibrahim.","bn":"ইবরাহিম (আ.) যখন তরুণ, তাঁর জাতি পাথর আর কাঠের মূর্তির পূজা করত। এমনকি তাঁর নিজের বাবাও মূর্তি বানাতেন ও সেবা করতেন। ইবরাহিম (আ.) ভাবতেন: নিজের হাতে খোদাই করা জিনিস কীভাবে আমাদের রব হতে পারে?\n\nএক রাতে ইবরাহিম (আ.) ওপরে তাকিয়ে একটি উজ্জ্বল তারা দেখলেন। বললেন, এটা কি আমার রব? কিন্তু তারাটি ডুবে মিলিয়ে গেল। তিনি বললেন, যা হারিয়ে যায় তাকে আমি ভালোবাসি না। তারপর ঝলমলে চাঁদ উঠল। এটা কি আমার রব? কিন্তু চাঁদও ডুবে গেল। সকালে বিশাল সূর্য উঠল। এটা তো সবচেয়ে বড়! কিন্তু সন্ধ্যায় সূর্যও ডুবে গেল। ইবরাহিম (আ.) বললেন: আমি সেই সত্তার দিকে মুখ ফেরালাম, যিনি আসমান ও জমিন সৃষ্টি করেছেন (সূরা আল-আনআম ৬:৭৬–৭৯)।\n\nইবরাহিম (আ.) বাবার সাথে নরম করে কথা বললেন। আব্বাজান, আপনি এমন কিছুর ইবাদত কেন করেন, যা শোনে না, দেখে না, আর আপনার কোনো কাজেই আসে না? (সূরা মারইয়াম ১৯:৪২)। বাবা রেগে গিয়ে তাঁকে চলে যেতে বললেন। কিন্তু ইবরাহিম (আ.) উত্তর দিলেন: আপনার ওপর শান্তি হোক। আমি আমার রবের কাছে আপনার জন্য ক্ষমা চাইব (সূরা মারইয়াম ১৯:৪৬–৪৭)। মতের অমিল হলেও তিনি দয়ালুই রইলেন।\n\nএকদিন সবাই যখন বাইরে, ইবরাহিম (আ.) তাদের মন্দিরে গিয়ে মূর্তিগুলো ভেঙে টুকরো টুকরো করলেন — শুধু সবচেয়ে বড়টা ছাড়া (সূরা আল-আম্বিয়া ২১:৫৭–৫৮)। লোকেরা ফিরে এসে চিৎকার করল: কে করেছে এটা? তারা ইবরাহিম (আ.)-কে ধরে আনল। তিনি বড় মূর্তিটার দিকে দেখিয়ে বললেন: ওদেরকেই জিজ্ঞেস করো, যদি ওরা কথা বলতে পারে! (সূরা আল-আম্বিয়া ২১:৬২–৬৩)।\n\nলোকেরা জানত মূর্তি কথা বলতে পারে না। এক মুহূর্তের জন্য তারা লজ্জা পেল। কিন্তু ভেবে দেখার বদলে তারা রেগে গেল। ওকে পুড়িয়ে দাও! তারা চিৎকার করল (সূরা আল-আম্বিয়া ২১:৬৮)। তারা বিশাল আগুন জ্বালিয়ে ইবরাহিম (আ.)-কে তাতে ছুড়ে ফেলল।\n\nকিন্তু আল্লাহ বললেন: হে আগুন, ইবরাহিমের জন্য শীতল ও নিরাপদ হয়ে যাও (সূরা আল-আম্বিয়া ২১:৬৯)। আগুন তাঁর একটুও ক্ষতি করল না। ইবরাহিম (আ.) নিরাপদে বেরিয়ে এলেন।\n\n## শিক্ষা\n\nইবরাহিম (আ.) আল্লাহর সৃষ্টি নিয়ে বুদ্ধি খাটিয়ে ভেবেছিলেন, আর সেই ভাবনা তাঁকে আল্লাহর কাছে নিয়ে গেছে। তিনি সাহসী ছিলেন, সত্যের পক্ষে দাঁড়িয়েছিলেন। আর বাবার সাথে মতের অমিল হলেও ভালোবাসা ও সম্মান দিয়ে কথা বলেছেন। আমরাও ইবরাহিম (আ.)-এর মতো ভাবতে পারি, সাহসী হতে পারি, আর দয়ালু থাকতে পারি।"}'::jsonb, '{}'::jsonb, 4, 1096, 4748, '{}'::text[], 'any', ARRAY['prophet story', 'ibrahim', 'abraham', 'thinking', 'courage', 'kindness to parents']::text[], false, 'in_review'::lp_review_status, 9032),
  ('isl-story-yusuf', 'story', 'islamic', 'child', 'educational', 'religious', '🌾', '{"en":"Yusuf (peace be upon him): from the well to forgiveness","bn":"ইউসুফ (আ.): কুয়া থেকে ক্ষমা পর্যন্ত"}'::jsonb, '{"en":"Yusuf''s jealous brothers threw him in a well, but Allah raised him up, and in the end he forgave them. A story about patience and forgiveness.","bn":"হিংসুটে ভাইয়েরা ইউসুফ (আ.)-কে কুয়ায় ফেলে দিয়েছিল, কিন্তু আল্লাহ তাঁকে উঁচুতে তুললেন, আর শেষে তিনি তাদের ক্ষমা করলেন। ধৈর্য ও ক্ষমার গল্প।"}'::jsonb, '{"en":"When Yusuf was a boy, he had a special dream. He told his father, Ya''qub: I saw eleven stars, the sun and the moon bowing down to me. His father said gently: my son, do not tell your brothers, in case they become jealous (Surah Yusuf 12:4–5).\n\nBut his older brothers were already jealous. They felt their father loved Yusuf more (Surah Yusuf 12:8). One day they took Yusuf out and threw him into a deep well. Allah comforted Yusuf in the dark: one day you will tell them about this (Surah Yusuf 12:15). The brothers went home crying and showed their father Yusuf''s shirt with false blood on it. A wolf ate him, they said. Ya''qub''s heart was broken, but he said: beautiful patience. Allah is the One whose help I seek (Surah Yusuf 12:16–18).\n\nTravellers came to the well, pulled Yusuf out, and took him to Egypt (Surah Yusuf 12:19–21). There he grew up good, wise and honest. Even though he had done nothing wrong, he was put in prison for years. In prison he was kind to others, told them about Allah, and explained the meaning of their dreams (Surah Yusuf 12:35–42).\n\nOne night the King of Egypt had a strange dream: seven fat cows were eaten by seven thin cows. Yusuf explained it: there will be seven good years of harvest, then seven hard years. Store the grain in the good years (Surah Yusuf 12:43–49). The king put Yusuf in charge of all the storehouses of the land (Surah Yusuf 12:54–55).\n\nWhen the hard years came, Yusuf''s brothers came to Egypt to buy food. Yusuf knew them, but they did not know him (Surah Yusuf 12:58). In the end Yusuf told them who he was. The brothers were ashamed. But Yusuf said: no blame on you today. May Allah forgive you; He is the Most Merciful of the merciful (Surah Yusuf 12:92).\n\nYa''qub had cried so much that his eyes had grown weak. Yusuf sent his shirt home, and when it was placed on his father''s face, he could see again (Surah Yusuf 12:84, 12:93–96). The whole family came to Egypt and was together again. Yusuf said: this is the meaning of my dream long ago (Surah Yusuf 12:99–100).\n\n## The lesson\n\nYusuf was patient in the well and in prison, and he trusted Allah. When he became powerful, he did not take revenge; he forgave. Jealousy can hurt a family, but patience and forgiveness can bring it back together.","bn":"ইউসুফ (আ.) যখন ছোট, তিনি একটি বিশেষ স্বপ্ন দেখলেন। বাবা ইয়াকুব (আ.)-কে বললেন: আমি দেখলাম এগারোটি তারা, সূর্য আর চাঁদ আমাকে সিজদা করছে। বাবা আদর করে বললেন: বাবা, তোমার ভাইদের এ কথা বোলো না, তারা হয়তো হিংসা করবে (সূরা ইউসুফ ১২:৪–৫)।\n\nকিন্তু বড় ভাইয়েরা আগেই হিংসা করত। তাদের মনে হতো বাবা ইউসুফকে বেশি ভালোবাসেন (সূরা ইউসুফ ১২:৮)। একদিন তারা ইউসুফকে বাইরে নিয়ে গিয়ে একটা গভীর কুয়ায় ফেলে দিল। অন্ধকারে আল্লাহ ইউসুফকে সান্ত্বনা দিলেন: একদিন তুমি তাদের এ কাজের কথা জানাবে (সূরা ইউসুফ ১২:১৫)। ভাইয়েরা কাঁদতে কাঁদতে বাড়ি ফিরে বাবাকে ইউসুফের জামা দেখাল, তাতে মিথ্যা রক্ত লাগানো। বলল, নেকড়ে ওকে খেয়ে ফেলেছে। ইয়াকুব (আ.)-এর মন ভেঙে গেল, তবু তিনি বললেন: সুন্দর ধৈর্যই ভালো। আল্লাহর কাছেই সাহায্য চাই (সূরা ইউসুফ ১২:১৬–১৮)।\n\nএকদল মুসাফির কুয়ার কাছে এসে ইউসুফকে তুলে মিসরে নিয়ে গেল (সূরা ইউসুফ ১২:১৯–২১)। সেখানে তিনি ভালো, জ্ঞানী আর সৎ মানুষ হয়ে বড় হলেন। কোনো অন্যায় না করেও তাঁকে বছরের পর বছর জেলে থাকতে হলো। জেলেও তিনি অন্যদের সাথে দয়া করতেন, তাদের আল্লাহর কথা বলতেন, আর তাদের স্বপ্নের অর্থ বুঝিয়ে দিতেন (সূরা ইউসুফ ১২:৩৫–৪২)।\n\nএক রাতে মিসরের রাজা একটা অদ্ভুত স্বপ্ন দেখলেন: সাতটি মোটা গাভীকে সাতটি রোগা গাভী খেয়ে ফেলছে। ইউসুফ (আ.) বুঝিয়ে দিলেন: সাত বছর ভালো ফসল হবে, তারপর সাত বছর কঠিন সময়। ভালো বছরগুলোতে শস্য জমিয়ে রাখুন (সূরা ইউসুফ ১২:৪৩–৪৯)। রাজা ইউসুফ (আ.)-কে দেশের সব গুদামের দায়িত্ব দিলেন (সূরা ইউসুফ ১২:৫৪–৫৫)।\n\nকঠিন বছরগুলো এলে ইউসুফ (আ.)-এর ভাইয়েরা খাবার কিনতে মিসরে এল। ইউসুফ (আ.) তাদের চিনলেন, কিন্তু তারা তাঁকে চিনল না (সূরা ইউসুফ ১২:৫৮)। শেষে ইউসুফ (আ.) নিজের পরিচয় দিলেন। ভাইয়েরা লজ্জা পেল। কিন্তু ইউসুফ (আ.) বললেন: আজ তোমাদের কোনো দোষ নেই। আল্লাহ তোমাদের ক্ষমা করুন; তিনি দয়ালুদের মধ্যে সবচেয়ে দয়ালু (সূরা ইউসুফ ১২:৯২)।\n\nকাঁদতে কাঁদতে ইয়াকুব (আ.)-এর চোখ দুর্বল হয়ে গিয়েছিল। ইউসুফ (আ.) নিজের জামা বাড়িতে পাঠালেন; বাবার মুখের ওপর রাখতেই তিনি আবার দেখতে পেলেন (সূরা ইউসুফ ১২:৮৪, ১২:৯৩–৯৬)। পুরো পরিবার মিসরে এসে আবার একসাথে হলো। ইউসুফ (আ.) বললেন: এটাই আমার সেই পুরনো স্বপ্নের অর্থ (সূরা ইউসুফ ১২:৯৯–১০০)।\n\n## শিক্ষা\n\nইউসুফ (আ.) কুয়ায় আর জেলে ধৈর্য ধরেছিলেন, আর আল্লাহর ওপর ভরসা রেখেছিলেন। ক্ষমতা পাওয়ার পর তিনি প্রতিশোধ নেননি; ক্ষমা করেছেন। হিংসা পরিবারকে কষ্ট দিতে পারে, কিন্তু ধৈর্য আর ক্ষমা আবার সবাইকে একসাথে করতে পারে।"}'::jsonb, '{}'::jsonb, 4, 1096, 4748, '{}'::text[], 'any', ARRAY['prophet story', 'yusuf', 'joseph', 'patience', 'forgiveness', 'siblings', 'jealousy']::text[], false, 'in_review'::lp_review_status, 9033),
  ('isl-story-musa', 'story', 'islamic', 'child', 'educational', 'religious', '🧺', '{"en":"Baby Musa (peace be upon him) and the river","bn":"শিশু মূসা (আ.) আর নদী"}'::jsonb, '{"en":"A worried mother, a basket on the river, a kind queen and a clever sister. How Allah kept His promise and brought baby Musa home.","bn":"এক চিন্তিত মা, নদীতে একটি ঝুড়ি, এক দয়ালু রানি আর এক বুদ্ধিমতী বোন। আল্লাহ কীভাবে কথা রাখলেন আর শিশু মূসা (আ.)-কে মায়ের কোলে ফিরিয়ে দিলেন।"}'::jsonb, '{"en":"Long ago in Egypt there lived a cruel king called Pharaoh. He was afraid of the people of Bani Isra''il, and he ordered that their baby boys be taken away and harmed (Surah Al-Qasas 28:4).\n\nAt that time, a baby boy was born to a woman of Bani Isra''il. His name was Musa. His mother loved him very much, and she was very afraid.\n\nAllah put a message into her heart: feed your baby. And when you fear for him, put him in the river. Do not be afraid and do not be sad. We will bring him back to you, and We will make him one of Our messengers (Surah Al-Qasas 28:7).\n\nSo Musa''s mother placed him in a box and set it on the river (Surah Ta-Ha 20:39). The water carried it away. Her heart felt empty, and she almost cried out, but Allah made her heart strong (Surah Al-Qasas 28:10). She told Musa''s sister: follow him. The sister walked along the riverbank, watching from a distance, and no one noticed her (Surah Al-Qasas 28:11).\n\nThe river carried the box right to Pharaoh''s palace, and his family lifted it out of the water (Surah Al-Qasas 28:8). Pharaoh''s wife looked at the baby and loved him at once. She said: he will be a joy for me and for you. Do not kill him. Perhaps he will be useful to us, or we may take him as our son (Surah Al-Qasas 28:9). The Prophet ﷺ later praised her as one of the best of women, and named her Asiyah (Sahih al-Bukhari and Sahih Muslim).\n\nBaby Musa was hungry, but he refused to drink from any of the nurses they brought. Then his sister stepped forward: shall I show you a family who will look after him well? (Surah Al-Qasas 28:12).\n\nAnd so Musa was brought back to his own mother. She held him and fed him, her eyes were comforted, and she was no longer sad. She knew that Allah''s promise is always true (Surah Al-Qasas 28:13).\n\nMusa grew up in the palace, and one day Allah made him a great prophet. Many years later, Allah split the sea for him and saved his people (Surah Ash-Shu''ara 26:63–65).\n\n## The lesson\n\nMusa''s mother was afraid, but she trusted Allah, and Allah kept His promise. His sister was brave and clever, and Asiyah was kind to a baby who needed her. When we are worried, we can trust Allah, and we can be the helper someone else needs.","bn":"অনেক দিন আগে মিসরে ফেরাউন নামে এক নিষ্ঠুর রাজা ছিল। সে বনি ইসরাইলের মানুষদের ভয় পেত, আর তাদের ছেলেশিশুদের ধরে নিয়ে ক্ষতি করার হুকুম দিয়েছিল (সূরা আল-কাসাস ২৮:৪)।\n\nসেই সময় বনি ইসরাইলের এক নারীর একটি ছেলে হলো। তার নাম মূসা। মা তাকে খুব ভালোবাসতেন, আর খুব ভয়ও পেতেন।\n\nআল্লাহ তাঁর মনে একটি বার্তা দিলেন: শিশুকে দুধ খাওয়াও। আর যখন তার জন্য ভয় পাবে, তাকে নদীতে ভাসিয়ে দিয়ো। ভয় পেয়ো না, দুঃখও কোরো না। আমি তাকে তোমার কাছে ফিরিয়ে দেব, আর তাকে আমার রাসূলদের একজন বানাব (সূরা আল-কাসাস ২৮:৭)।\n\nতাই মূসা (আ.)-এর মা তাঁকে একটি বাক্সে রেখে নদীতে ভাসিয়ে দিলেন (সূরা ত্বাহা ২০:৩৯)। পানি বাক্সটাকে দূরে নিয়ে গেল। মায়ের মন একেবারে খালি হয়ে গেল, তিনি প্রায় চিৎকার করে ফেলছিলেন, কিন্তু আল্লাহ তাঁর মনকে শক্ত করে দিলেন (সূরা আল-কাসাস ২৮:১০)। তিনি মূসার বোনকে বললেন: ওর পিছে পিছে যাও। বোনটি নদীর পাড় ধরে হাঁটতে হাঁটতে দূর থেকে নজর রাখল, কেউ তাকে খেয়াল করল না (সূরা আল-কাসাস ২৮:১১)।\n\nনদী বাক্সটাকে একেবারে ফেরাউনের প্রাসাদে নিয়ে গেল, আর তার পরিবারের লোকেরা পানি থেকে সেটা তুলে নিল (সূরা আল-কাসাস ২৮:৮)। ফেরাউনের স্ত্রী শিশুটিকে দেখেই ভালোবেসে ফেললেন। বললেন: এ আমার আর তোমার চোখের শীতলতা হবে। একে মেরো না। হয়তো আমাদের কাজে আসবে, বা আমরা তাকে ছেলে হিসেবে নেব (সূরা আল-কাসাস ২৮:৯)। পরে রাসূলুল্লাহ ﷺ তাঁকে শ্রেষ্ঠ নারীদের একজন বলে প্রশংসা করেছেন, আর তাঁর নাম বলেছেন আসিয়া (সহিহ বুখারি ও সহিহ মুসলিম)।\n\nশিশু মূসার খিদে পেল, কিন্তু যত দুধমা আনা হলো, কারও দুধই সে খেল না। তখন তাঁর বোন এগিয়ে এসে বলল: আমি কি আপনাদের এমন এক পরিবারের খোঁজ দেব, যারা ওকে যত্ন করে দেখবে? (সূরা আল-কাসাস ২৮:১২)।\n\nএভাবে মূসা (আ.) নিজের মায়ের কাছেই ফিরে এলেন। মা তাঁকে কোলে নিয়ে দুধ খাওয়ালেন, তাঁর চোখ জুড়াল, দুঃখ চলে গেল। তিনি জানলেন, আল্লাহর ওয়াদা সবসময় সত্য (সূরা আল-কাসাস ২৮:১৩)।\n\nমূসা (আ.) প্রাসাদে বড় হলেন, আর একদিন আল্লাহ তাঁকে মহান নবী বানালেন। অনেক বছর পর আল্লাহ তাঁর জন্য সাগর দুই ভাগ করে দিলেন এবং তাঁর জাতিকে রক্ষা করলেন (সূরা আশ-শুআরা ২৬:৬৩–৬৫)।\n\n## শিক্ষা\n\nমূসা (আ.)-এর মা ভয় পেয়েছিলেন, কিন্তু আল্লাহর ওপর ভরসা রেখেছিলেন, আর আল্লাহ কথা রেখেছেন। তাঁর বোন ছিল সাহসী ও বুদ্ধিমতী, আর আসিয়া একটি অসহায় শিশুর প্রতি দয়া করেছিলেন। আমরা চিন্তায় পড়লে আল্লাহর ওপর ভরসা রাখতে পারি, আর অন্য কারও প্রয়োজনে সাহায্যকারী হতে পারি।"}'::jsonb, '{}'::jsonb, 4, 1096, 4748, '{}'::text[], 'any', ARRAY['prophet story', 'musa', 'moses', 'trust', 'mother', 'river', 'bedtime story']::text[], false, 'in_review'::lp_review_status, 9034),
  ('isl-story-yunus', 'story', 'islamic', 'child', 'educational', 'religious', '🐋', '{"en":"Yunus (peace be upon him) and the big fish","bn":"ইউনুস (আ.) আর বিশাল মাছ"}'::jsonb, '{"en":"Inside the dark belly of a great fish, Yunus called on Allah with a short dua, and Allah saved him. A story about turning back to Allah.","bn":"বিশাল মাছের অন্ধকার পেটের ভেতরে ইউনুস (আ.) একটি ছোট দোয়া দিয়ে আল্লাহকে ডেকেছিলেন, আর আল্লাহ তাঁকে বাঁচিয়েছিলেন। আল্লাহর দিকে ফিরে আসার গল্প।"}'::jsonb, '{"en":"Allah sent the prophet Yunus to a town with a very large number of people, more than a hundred thousand (Surah As-Saffat 37:147). Yunus told them to worship Allah alone. But they did not listen.\n\nYunus became angry and upset, and he went away from his people before Allah told him to (Surah Al-Anbiya 21:87). He went down to the sea and climbed onto a ship that was full of people (Surah As-Saffat 37:140).\n\nOut at sea, the ship was in danger. The sailors drew lots to choose who would leave the ship, and the lot fell on Yunus (Surah As-Saffat 37:141). He went into the sea, and a great fish swallowed him (Surah As-Saffat 37:142).\n\nNow Yunus was in darkness upon darkness: the dark of the night, the dark of the deep sea, and the dark inside the fish. He knew he had made a mistake. And in that darkness he called out to Allah (Surah Al-Anbiya 21:87):\n\nلَا إِلَٰهَ إِلَّا أَنتَ سُبْحَانَكَ إِنِّي كُنتُ مِنَ الظَّالِمِينَ\n\n**La ilaha illa anta, subhanaka, inni kuntu minaz-zalimin.**\n\nThere is no god but You. Glory be to You! I was wrong.\n\nAllah heard him. Allah answered his call and saved him from his sadness, and Allah says that He saves the believers in the same way (Surah Al-Anbiya 21:88).\n\nThe great fish put Yunus out onto the open shore. He was weak and ill. Allah made a leafy gourd plant grow over him, to give him shade (Surah As-Saffat 37:145–146). Slowly, Yunus grew strong again.\n\nAnd here is the wonderful part: while he was away, his people had believed! Allah removed the punishment from them, and they enjoyed their lives (Surah Yunus 10:98; Surah As-Saffat 37:148). Yunus went back to a town full of believers.\n\n## The lesson\n\nYunus made a mistake, but he did not give up. Even in the darkest place, he turned to Allah, admitted he was wrong, and praised Him. Allah heard him. When we feel sad, stuck or sorry, we can say Yunus''s dua too. No place is too dark for Allah to hear us.","bn":"আল্লাহ নবী ইউনুস (আ.)-কে এমন এক শহরে পাঠালেন যেখানে অনেক মানুষ — এক লাখেরও বেশি (সূরা আস-সাফফাত ৩৭:১৪৭)। ইউনুস (আ.) তাদের শুধু আল্লাহর ইবাদত করতে বললেন। কিন্তু তারা কথা শুনল না।\n\nইউনুস (আ.) রেগে ও মন খারাপ করে, আল্লাহর অনুমতির আগেই তাঁর জাতিকে ছেড়ে চলে গেলেন (সূরা আল-আম্বিয়া ২১:৮৭)। তিনি সাগরের কাছে গিয়ে মানুষে ভরা একটা জাহাজে উঠলেন (সূরা আস-সাফফাত ৩৭:১৪০)।\n\nমাঝসাগরে জাহাজটা বিপদে পড়ল। কে জাহাজ ছাড়বে, তা ঠিক করতে নাবিকেরা লটারি করল, আর লটারিতে ইউনুস (আ.)-এর নাম উঠল (সূরা আস-সাফফাত ৩৭:১৪১)। তিনি সাগরে নামলেন, আর এক বিশাল মাছ তাঁকে গিলে ফেলল (সূরা আস-সাফফাত ৩৭:১৪২)।\n\nএখন ইউনুস (আ.) অন্ধকারের ভেতর অন্ধকারে: রাতের অন্ধকার, গভীর সাগরের অন্ধকার, আর মাছের পেটের অন্ধকার। তিনি বুঝলেন তাঁর ভুল হয়েছে। সেই অন্ধকারে তিনি আল্লাহকে ডাকলেন (সূরা আল-আম্বিয়া ২১:৮৭):\n\nلَا إِلَٰهَ إِلَّا أَنتَ سُبْحَانَكَ إِنِّي كُنتُ مِنَ الظَّالِمِينَ\n\n**উচ্চারণ: লা ইলাহা ইল্লা আনতা, সুবহানাকা, ইন্নি কুনতু মিনায যালিমিন।**\n\nঅর্থ: আপনি ছাড়া কোনো ইলাহ নেই। আপনি পবিত্র! আমি ভুল করেছি।\n\nআল্লাহ তাঁর ডাক শুনলেন। আল্লাহ সাড়া দিলেন এবং তাঁকে দুঃখ থেকে বাঁচালেন, আর আল্লাহ বলেন, তিনি ঈমানদারদের এভাবেই বাঁচান (সূরা আল-আম্বিয়া ২১:৮৮)।\n\nবিশাল মাছটা ইউনুস (আ.)-কে খোলা তীরে ফেলে দিল। তিনি দুর্বল আর অসুস্থ ছিলেন। আল্লাহ তাঁর ওপর একটা পাতাওয়ালা লাউ জাতীয় গাছ গজিয়ে দিলেন, যেন ছায়া পান (সূরা আস-সাফফাত ৩৭:১৪৫–১৪৬)। ধীরে ধীরে ইউনুস (আ.) আবার সুস্থ হয়ে উঠলেন।\n\nআর এবার সবচেয়ে সুন্দর অংশ: তিনি যখন দূরে ছিলেন, তাঁর জাতি ঈমান এনেছিল! আল্লাহ তাদের ওপর থেকে শাস্তি সরিয়ে নিলেন, আর তারা সুখে জীবন কাটাল (সূরা ইউনুস ১০:৯৮; সূরা আস-সাফফাত ৩৭:১৪৮)। ইউনুস (আ.) ফিরে গেলেন ঈমানদারে ভরা এক শহরে।\n\n## শিক্ষা\n\nইউনুস (আ.) ভুল করেছিলেন, কিন্তু হাল ছাড়েননি। সবচেয়ে অন্ধকার জায়গাতেও তিনি আল্লাহর দিকে ফিরেছেন, নিজের ভুল স্বীকার করেছেন, আর আল্লাহর প্রশংসা করেছেন। আল্লাহ তাঁর কথা শুনেছেন। আমাদের মন খারাপ হলে, আটকে গেছি মনে হলে বা ভুলের জন্য খারাপ লাগলে আমরাও ইউনুস (আ.)-এর দোয়াটি পড়তে পারি। কোনো জায়গাই এত অন্ধকার নয় যে আল্লাহ আমাদের শুনবেন না।"}'::jsonb, '{}'::jsonb, 4, 1096, 4748, '{}'::text[], 'any', ARRAY['prophet story', 'yunus', 'jonah', 'whale', 'dua', 'turning to allah']::text[], false, 'in_review'::lp_review_status, 9035),
  ('isl-story-muhammad', 'story', 'islamic', 'child', 'educational', 'religious', '🌙', '{"en":"The Prophet Muhammad ﷺ: an orphan boy who became the kindest of people","bn":"নবী মুহাম্মাদ ﷺ: এক এতিম বালক, যিনি হলেন সবচেয়ে দয়ালু মানুষ"}'::jsonb, '{"en":"His childhood in Makkah, the boy everyone called “the trustworthy”, and the gentle way he treated children and even animals.","bn":"মক্কায় তাঁর ছোটবেলা, যে বালককে সবাই “বিশ্বস্ত” বলে ডাকত, আর শিশু এমনকি পশুপাখির সাথেও তাঁর কোমল ব্যবহার।"}'::jsonb, '{"en":"Long ago, in the city of Makkah, a baby boy was born. His name was Muhammad ﷺ. His father, ''Abdullah, had died before he was born, so he never saw his father.\n\nAs a tiny baby he was looked after by a kind woman called Halimah, in the open desert, where the air was fresh. When he was about six years old, his mother, Aminah, also died. Now he was an orphan. His loving grandfather, ''Abdul-Muttalib, took care of him, and after his grandfather died, his uncle Abu Talib took him into his home.\n\nAllah later reminded him: did He not find you an orphan and give you shelter? (Surah Ad-Duha 93:6). Allah was looking after him all along.\n\nAs a boy, Muhammad ﷺ helped by looking after sheep on the hills around Makkah. He said that every prophet had been a shepherd (Sahih al-Bukhari). He grew up honest and gentle. He never lied and always kept what people trusted him with, so the people of Makkah called him al-Amin, the trustworthy one.\n\nWhen he grew up and became the Prophet ﷺ, he never forgot what it felt like to be a child.\n\n- He said salam to children when he passed them (Sahih al-Bukhari and Sahih Muslim).\n- A little boy called Abu ''Umayr had a small pet bird. When the bird died, the Prophet ﷺ kindly asked him about it, to share his sadness (Sahih al-Bukhari and Sahih Muslim).\n- He carried his little granddaughter Umamah, even while he prayed (Sahih al-Bukhari and Sahih Muslim).\n- He kissed his grandson al-Hasan and said: whoever is not merciful will not be shown mercy (Sahih al-Bukhari and Sahih Muslim).\n\nHe was kind to animals too. He told the story of a man who found a dog so thirsty it was licking the mud. The man climbed down into a well, filled his shoe with water, and gave the dog a drink. Allah thanked him and forgave him (Sahih al-Bukhari and Sahih Muslim).\n\nAnd Allah told him: so do not be harsh with the orphan (Surah Ad-Duha 93:9). He always took special care of children who had lost a parent, as he once had.\n\n## The lesson\n\nThe Prophet ﷺ knew sadness when he was small, but it made him kinder, not harder. He was honest, gentle with children and kind to animals. We can follow him by telling the truth, being gentle with younger children, and caring for animals and anyone who is alone. And when we hear his name, we say: sallallahu ''alayhi wa sallam, may Allah''s peace and blessings be upon him.","bn":"অনেক দিন আগে মক্কা শহরে একটি ছেলেশিশু জন্ম নিল। তাঁর নাম মুহাম্মাদ ﷺ। তাঁর জন্মের আগেই বাবা আবদুল্লাহ মারা গিয়েছিলেন, তাই তিনি কখনো বাবাকে দেখেননি।\n\nএকেবারে ছোট্ট বয়সে হালিমা নামে এক দয়ালু নারী খোলা মরুভূমিতে, যেখানে বাতাস ছিল নির্মল, তাঁর দেখাশোনা করতেন। প্রায় ছয় বছর বয়সে তাঁর মা আমিনাও মারা গেলেন। তিনি হয়ে গেলেন এতিম। তাঁর স্নেহময় দাদা আবদুল মুত্তালিব তাঁর যত্ন নিলেন, আর দাদা মারা যাওয়ার পর চাচা আবু তালিব তাঁকে নিজের ঘরে নিয়ে গেলেন।\n\nপরে আল্লাহ তাঁকে মনে করিয়ে দিয়েছেন: তিনি কি তোমাকে এতিম অবস্থায় পাননি, তারপর আশ্রয় দেননি? (সূরা আদ-দুহা ৯৩:৬)। আল্লাহ সবসময় তাঁকে দেখে রেখেছিলেন।\n\nছোটবেলায় মুহাম্মাদ ﷺ মক্কার আশপাশের পাহাড়ে ছাগল-ভেড়া চরিয়ে সাহায্য করতেন। তিনি বলেছেন, প্রত্যেক নবীই রাখাল ছিলেন (সহিহ বুখারি)। তিনি সৎ আর কোমল হয়ে বড় হলেন। কখনো মিথ্যা বলতেন না, আর মানুষ যা আমানত রাখত তা সবসময় রক্ষা করতেন। তাই মক্কার মানুষ তাঁকে ডাকত আল-আমিন — বিশ্বস্ত।\n\nবড় হয়ে নবী হওয়ার পরও তিনি ভোলেননি ছোট থাকলে কেমন লাগে।\n\n- শিশুদের পাশ দিয়ে যাওয়ার সময় তিনি তাদের সালাম দিতেন (সহিহ বুখারি ও সহিহ মুসলিম)।\n- আবু উমাইর নামে এক ছোট ছেলের একটি পোষা পাখি ছিল। পাখিটি মারা গেলে রাসূলুল্লাহ ﷺ আদর করে তাকে পাখির কথা জিজ্ঞেস করতেন, তার দুঃখে শরিক হতে (সহিহ বুখারি ও সহিহ মুসলিম)।\n- তিনি ছোট্ট নাতনি উমামাকে কোলে নিতেন, এমনকি নামাজের সময়ও (সহিহ বুখারি ও সহিহ মুসলিম)।\n- তিনি নাতি হাসানকে চুমু দিয়ে বলেছিলেন: যে দয়া করে না, তাকে দয়া করা হয় না (সহিহ বুখারি ও সহিহ মুসলিম)।\n\nপশুপাখির প্রতিও তিনি দয়ালু ছিলেন। তিনি এক লোকের গল্প বলেছেন, যে দেখল একটা কুকুর এত পিপাসার্ত যে কাদা চাটছে। লোকটা কুয়ায় নেমে নিজের জুতায় পানি ভরে কুকুরটাকে খাওয়াল। আল্লাহ তার এই কাজের মূল্য দিলেন এবং তাকে ক্ষমা করে দিলেন (সহিহ বুখারি ও সহিহ মুসলিম)।\n\nআর আল্লাহ তাঁকে বললেন: সুতরাং এতিমের প্রতি কঠোর হয়ো না (সূরা আদ-দুহা ৯৩:৯)। যে শিশুরা বাবা বা মাকে হারিয়েছে, তিনি তাদের বিশেষ যত্ন নিতেন, কারণ তিনি নিজেও একসময় তেমন ছিলেন।\n\n## শিক্ষা\n\nছোটবেলায় রাসূলুল্লাহ ﷺ দুঃখ পেয়েছিলেন, কিন্তু তা তাঁকে কঠিন নয়, আরও দয়ালু বানিয়েছিল। তিনি ছিলেন সৎ, শিশুদের প্রতি কোমল আর পশুপাখির প্রতি দয়ালু। আমরাও তাঁকে অনুসরণ করতে পারি — সত্য বলে, ছোটদের সাথে নরম ব্যবহার করে, আর পশুপাখি ও একা মানুষদের যত্ন নিয়ে। আর তাঁর নাম শুনলে আমরা বলি: সাল্লাল্লাহু আলাইহি ওয়া সাল্লাম — তাঁর ওপর আল্লাহর রহমত ও শান্তি বর্ষিত হোক।"}'::jsonb, '{}'::jsonb, 4, 1096, 4748, '{}'::text[], 'any', ARRAY['prophet story', 'prophet muhammad', 'seerah', 'childhood', 'kindness', 'orphan', 'animals']::text[], false, 'in_review'::lp_review_status, 9036),
  ('isl-ramadan-with-children', 'article', 'islamic', 'shared', 'educational', 'religious', '🌙', '{"en":"Ramadan with children: practice fasts, step by step","bn":"শিশুদের সাথে রমজান: ধাপে ধাপে অনুশীলনের রোজা"}'::jsonb, '{"en":"Fasting becomes obligatory at puberty. Before that, children can practise little by little, with health always first and your doctor''s advice when in doubt.","bn":"বালেগ হলে রোজা ফরজ হয়। তার আগে শিশুরা একটু একটু করে অনুশীলন করতে পারে — সবসময় স্বাস্থ্য আগে, আর সন্দেহ থাকলে ডাক্তারের পরামর্শ।"}'::jsonb, '{"en":"## When fasting becomes obligatory\n\nFasting in Ramadan is a pillar of Islam (Surah Al-Baqarah 2:183). It becomes obligatory when a child reaches puberty. The Prophet ﷺ said that the pen is lifted from three, including the child until they reach puberty (Sunan Abi Dawud, Jami'' at-Tirmidhi). Before that, fasting is practice, and every bit of it is rewarded.\n\nAllah says about fasting:\n\nيُرِيدُ اللَّهُ بِكُمُ الْيُسْرَ وَلَا يُرِيدُ بِكُمُ الْعُسْرَ\n\n**Yuridullahu bikumul-yusra wa la yuridu bikumul-''usr.**\n\nMeaning: Allah wants ease for you, and does not want hardship for you. (Surah Al-Baqarah 2:185)\n\n## How the Companions trained children\n\nAr-Rubayyi'' bint Mu''awwidh said that they used to have their children fast, and made them toys of wool. When a child cried for food, they gave them the toy to play with until it was time to break the fast (Sahih al-Bukhari and Sahih Muslim). Practice was gentle, playful and well supported.\n\n## A gentle path by age\n\nThese are not rules but a common approach. Every child is different.\n\n- **Under 7:** join suhoor or iftar, help set the table, give dates to guests. No fasting needed.\n- **About 7 to 9:** a few practice fasts until Dhuhr or Asr, on days without school or exams.\n- **About 10 and up:** more full fasts on cooler or easier days, if the child is healthy and willing.\n\nHealth comes first. Decide with your doctor''s advice if your child is underweight, has diabetes, kidney problems or any long-term illness, or takes regular medicine. Stop a practice fast if your child feels dizzy, faint, very weak or unwell. A practice fast that ends early is still a success.\n\nMake sure suhoor and iftar include enough water and filling food, and keep children out of the midday heat.\n\n## Ramadan is more than not eating\n\n- Make a Ramadan calendar with one good deed a day.\n- Keep a sadaqah jar, and let children choose where it goes.\n- Cook or carry iftar to a neighbour, a guard or a rickshaw puller.\n- Explain zakat al-fitr: the Prophet ﷺ made it due for every Muslim, young and old (Sahih al-Bukhari and Sahih Muslim), so it is paid for your children too.\n- In the last ten nights, let older children stay up a little to pray and make dua.\n\n## Fathers\n\nWake the children gently for suhoor, take them to tarawih if they want to come, and fast alongside them with patience, not irritability. Children learn what Ramadan feels like from your mood.\n\n## Do not compare\n\nNever shame a child who cannot fast, and do not praise only the one who fasted most. Praise effort, kindness and prayer, too.","bn":"## রোজা কখন ফরজ হয়\n\nরমজানের রোজা ইসলামের একটি স্তম্ভ (সূরা আল-বাকারা ২:১৮৩)। সন্তান বালেগ হলে রোজা ফরজ হয়। রাসূলুল্লাহ ﷺ বলেছেন, তিন ধরনের মানুষের ওপর থেকে কলম তুলে নেওয়া হয়েছে, তাদের একজন হলো শিশু, যতক্ষণ না সে বালেগ হয় (সুনান আবু দাউদ, জামে তিরমিজি)। তার আগে রোজা হলো অনুশীলন, আর এর প্রতিটি অংশেই সওয়াব আছে।\n\nরোজা সম্পর্কে আল্লাহ বলেন:\n\nيُرِيدُ اللَّهُ بِكُمُ الْيُسْرَ وَلَا يُرِيدُ بِكُمُ الْعُسْرَ\n\n**উচ্চারণ: ইউরিদুল্লাহু বিকুমুল ইউসরা ওয়া লা ইউরিদু বিকুমুল উসর।**\n\nঅর্থ: আল্লাহ তোমাদের জন্য সহজ চান, কঠিন চান না। (সূরা আল-বাকারা ২:১৮৫)\n\n## সাহাবিরা কীভাবে শিশুদের অভ্যস্ত করতেন\n\nরুবাইয়ি বিনতে মুআওয়িয (রা.) বলেছেন, তাঁরা শিশুদের রোজা রাখাতেন এবং তাদের জন্য উলের খেলনা বানাতেন। কোনো শিশু খাবারের জন্য কাঁদলে খেলনাটা দিতেন, ইফতারের সময় পর্যন্ত সে খেলত (সহিহ বুখারি ও সহিহ মুসলিম)। অনুশীলন ছিল কোমল, আনন্দময় আর ভালোভাবে সহায়তা করা।\n\n## বয়স অনুযায়ী কোমল পথ\n\nএগুলো নিয়ম নয়, প্রচলিত একটি পদ্ধতি। প্রতিটি শিশু আলাদা।\n\n- **৭ বছরের কম:** সাহরি বা ইফতারে যোগ দেওয়া, দস্তরখান সাজাতে সাহায্য করা, মেহমানদের খেজুর দেওয়া। রোজা রাখার দরকার নেই।\n- **প্রায় ৭ থেকে ৯ বছর:** স্কুল বা পরীক্ষা নেই এমন দিনে জোহর বা আসর পর্যন্ত কয়েকটি অনুশীলনের রোজা।\n- **প্রায় ১০ বছর ও তার বেশি:** সন্তান সুস্থ ও আগ্রহী হলে তুলনামূলক ঠান্ডা বা সহজ দিনে বেশি করে পুরো রোজা।\n\nস্বাস্থ্য সবার আগে। সন্তানের ওজন কম হলে, ডায়াবেটিস, কিডনির সমস্যা বা দীর্ঘমেয়াদি কোনো অসুখ থাকলে, বা নিয়মিত ওষুধ খেলে ডাক্তারের পরামর্শ নিয়ে সিদ্ধান্ত নিন। মাথা ঘোরা, অজ্ঞান ভাব, খুব দুর্বলতা বা অসুস্থ লাগলে অনুশীলনের রোজা ভেঙে দিন। আগে শেষ হওয়া অনুশীলনের রোজাও একটি সাফল্য।\n\nসাহরি ও ইফতারে যেন যথেষ্ট পানি ও পেট ভরার মতো খাবার থাকে, আর দুপুরের রোদ থেকে শিশুদের দূরে রাখুন।\n\n## রমজান শুধু না খাওয়া নয়\n\n- প্রতিদিন একটি ভালো কাজের রমজান ক্যালেন্ডার বানান।\n- একটি সদকার বাক্স রাখুন, আর কোথায় দেওয়া হবে তা শিশুদের বাছতে দিন।\n- প্রতিবেশী, দারোয়ান বা রিকশাচালকের জন্য ইফতার বানান বা পৌঁছে দিন।\n- সদকাতুল ফিতর বুঝিয়ে বলুন: রাসূলুল্লাহ ﷺ ছোট-বড় প্রত্যেক মুসলিমের ওপর এটি নির্ধারণ করেছেন (সহিহ বুখারি ও সহিহ মুসলিম), তাই সন্তানদের পক্ষ থেকেও দিতে হয়।\n- শেষ দশ রাতে বড় সন্তানদের একটু জেগে নামাজ ও দোয়া করতে দিন।\n\n## বাবাদের জন্য\n\nসাহরিতে সন্তানদের আদর করে জাগান, তারা চাইলে তারাবিতে নিয়ে যান, আর বিরক্তি নয়, ধৈর্য নিয়ে তাদের সাথে রোজা রাখুন। রমজান কেমন লাগে, শিশুরা তা আপনার মেজাজ দেখেই শেখে।\n\n## তুলনা করবেন না\n\nযে সন্তান রোজা রাখতে পারে না তাকে কখনো লজ্জা দেবেন না, আর যে সবচেয়ে বেশি রোজা রেখেছে শুধু তার প্রশংসা করবেন না। চেষ্টা, দয়া আর নামাজেরও প্রশংসা করুন।"}'::jsonb, '{}'::jsonb, 4, 2557, 5844, '{}'::text[], 'any', ARRAY['ramadan', 'fasting', 'roza', 'children', 'practice fast', 'health']::text[], false, 'in_review'::lp_review_status, 9037),
  ('isl-eid-joy', 'checklist', 'islamic', 'family', 'routine', 'religious', '🎉', '{"en":"Eid joy: making the day special for children","bn":"ঈদের আনন্দ: শিশুদের জন্য দিনটিকে বিশেষ করা"}'::jsonb, '{"en":"“Every people has its Eid, and this is our Eid.” Sunnah ways to fill both Eids with joy, gifts and generosity.","bn":"“প্রত্যেক জাতির ঈদ আছে, আর এটা আমাদের ঈদ।” দুই ঈদকে আনন্দ, উপহার আর উদারতায় ভরে তোলার সুন্নাহসম্মত উপায়।"}'::jsonb, '{"en":"Eid is meant to be happy. On an Eid day, two young girls were singing in the Prophet''s ﷺ house, and when Abu Bakr objected, the Prophet ﷺ said: leave them. Every people has its Eid, and this is our Eid (Sahih al-Bukhari and Sahih Muslim). On another Eid, he let ''A''ishah stand behind him and watch some Abyssinians playing with spears in the masjid for as long as she liked (Sahih al-Bukhari and Sahih Muslim).\n\nHe asked that women and girls, even those not praying because of their period, come out to the Eid gathering to share in the good and the dua (Sahih al-Bukhari and Sahih Muslim). So bring your daughters as well as your sons.\n\nThe Prophet ﷺ also said: give gifts to one another and you will love one another (Al-Adab al-Mufrad). Eid salami from elders is a much-loved part of Eid in Bangladesh. Let it be a joy, and gently teach children to share some of it.\n\nRemember children who will not have a happy Eid: orphans, children in poor families, and children whose parent is far away or has died. Including them is part of the joy.","bn":"ঈদ আনন্দের জন্য। এক ঈদের দিনে রাসূলুল্লাহ ﷺ-এর ঘরে দুটি ছোট মেয়ে গান গাইছিল; আবু বকর (রা.) আপত্তি করলে রাসূলুল্লাহ ﷺ বললেন: ওদের থাকতে দাও। প্রত্যেক জাতির ঈদ আছে, আর এটা আমাদের ঈদ (সহিহ বুখারি ও সহিহ মুসলিম)। আরেক ঈদে তিনি আয়েশা (রা.)-কে নিজের পেছনে দাঁড়িয়ে মসজিদে হাবশিদের বর্শা নিয়ে খেলা যতক্ষণ খুশি দেখতে দিয়েছিলেন (সহিহ বুখারি ও সহিহ মুসলিম)।\n\nতিনি বলেছেন নারী ও মেয়েরা — এমনকি যারা ঋতুস্রাবের কারণে নামাজ পড়ছে না তারাও — ঈদের জমায়েতে বের হবে, কল্যাণ ও দোয়ায় শরিক হবে (সহিহ বুখারি ও সহিহ মুসলিম)। তাই ছেলেদের মতো মেয়েদেরও সাথে নিন।\n\nরাসূলুল্লাহ ﷺ আরও বলেছেন: পরস্পরকে উপহার দাও, তোমাদের মধ্যে ভালোবাসা বাড়বে (আল-আদাবুল মুফরাদ)। বড়দের কাছ থেকে ঈদের সালামি বাংলাদেশে ঈদের খুব প্রিয় অংশ। এটা আনন্দেরই হোক, আর আলতো করে শিশুদের এর কিছু অংশ ভাগ করে দিতে শেখান।\n\nযে শিশুদের ঈদ আনন্দের হবে না, তাদের কথা মনে রাখুন: এতিম, গরিব পরিবারের শিশু, আর যাদের বাবা বা মা দূরে আছেন বা মারা গেছেন। তাদের সাথে নেওয়াও আনন্দেরই অংশ।"}'::jsonb, '{"items":{"en":["Before Eid al-Fitr prayer, pay zakat al-fitr for every family member, including the children, and let them see you do it","Bathe, wear clean or new clothes, and help children get ready with excitement, not stress","On Eid al-Fitr, eat a few dates before going to the prayer, as the Prophet ﷺ did (Sahih al-Bukhari)","Say the takbir together on the way: Allahu Akbar, Allahu Akbar, la ilaha illallah, wallahu akbar, Allahu Akbar, wa lillahil-hamd","Take daughters and sons to the Eid prayer, and go back by a different route, as the Prophet ﷺ did (Sahih al-Bukhari)","Greet people with “Eid Mubarak” or “Taqabbalallahu minna wa minkum” (May Allah accept from us and from you)","Give gifts and Eid salami, and let children give a gift too, even a drawing","Visit grandparents and relatives, and phone those who are far away","Include a child who might be alone or without new clothes","On Eid al-Adha, share the qurbani meat with relatives, neighbours and the poor; keep young children away from the slaughter if it frightens them","Plan time to play: games, a picnic, or a special family meal"],"bn":["ঈদুল ফিতরের নামাজের আগে সন্তানসহ পরিবারের প্রত্যেকের সদকাতুল ফিতর দিন, আর তাদের দেখতে দিন","গোসল করুন, পরিষ্কার বা নতুন জামা পরুন, আর চাপ নয়, উত্তেজনা নিয়ে শিশুদের তৈরি হতে সাহায্য করুন","ঈদুল ফিতরে নামাজে যাওয়ার আগে কয়েকটি খেজুর খান, যেমন রাসূলুল্লাহ ﷺ খেতেন (সহিহ বুখারি)","পথে একসাথে তাকবির বলুন: আল্লাহু আকবার, আল্লাহু আকবার, লা ইলাহা ইল্লাল্লাহু, ওয়াল্লাহু আকবার, আল্লাহু আকবার, ওয়া লিল্লাহিল হামদ","ছেলে-মেয়ে দুজনকেই ঈদের নামাজে নিন, আর অন্য পথে ফিরুন, যেমন রাসূলুল্লাহ ﷺ করতেন (সহিহ বুখারি)","“ঈদ মোবারক” বা “তাকাব্বালাল্লাহু মিন্না ওয়া মিনকুম” (আল্লাহ আমাদের ও আপনাদের পক্ষ থেকে কবুল করুন) বলে শুভেচ্ছা জানান","উপহার ও ঈদের সালামি দিন, আর শিশুদেরও কিছু উপহার দিতে দিন, একটা আঁকা ছবি হলেও","দাদা-দাদি, নানা-নানি ও আত্মীয়দের বাড়ি যান, দূরে যাঁরা আছেন তাঁদের ফোন করুন","যে শিশু একা থাকতে পারে বা যার নতুন জামা নেই, তাকে সাথে নিন","ঈদুল আজহায় কুরবানির গোশত আত্মীয়, প্রতিবেশী ও গরিবদের সাথে ভাগ করুন; জবাই দেখে ছোট শিশু ভয় পেলে তাকে দূরে রাখুন","খেলার সময় রাখুন: খেলাধুলা, পিকনিক বা পরিবারের বিশেষ খাবার"]}}'::jsonb, 3, 730, 7305, '{}'::text[], 'any', ARRAY['eid', 'eid ul fitr', 'eid ul adha', 'gifts', 'salami', 'joy', 'family']::text[], false, 'in_review'::lp_review_status, 9038),
  ('isl-puberty-girls', 'article', 'islamic', 'shared', 'important', 'religious', '🌸', '{"en":"Puberty in Islam: for daughters and their parents","bn":"ইসলামে বয়ঃসন্ধি: মেয়ে ও তার বাবা-মায়ের জন্য"}'::jsonb, '{"en":"Her first period means she is now accountable before Allah, an honour, not a shame. What changes in worship, the basics of ghusl, and how both parents can help.","bn":"প্রথম মাসিক মানে সে এখন আল্লাহর কাছে নিজের দায়িত্বশীল — এটা সম্মানের, লজ্জার নয়। ইবাদতে কী বদলায়, গোসলের মূল বিষয়, আর বাবা-মা দুজনে কীভাবে সাহায্য করতে পারেন।"}'::jsonb, '{"en":"## Becoming accountable\n\nIn Islam, a child becomes baligh, accountable, at puberty. The Prophet ﷺ said that the pen is lifted from three, including the child until they reach puberty (Sunan Abi Dawud, Jami'' at-Tirmidhi). From then, salah, fasting and other duties are her own.\n\nFor girls, the clearest sign is the first period. Scholars also mention other signs and an age limit if no sign appears; the schools differ on the details, so ask a trusted scholar.\n\n## Periods are natural\n\nWhen ''A''ishah got her period during Hajj and was upset, the Prophet ﷺ comforted her: this is something Allah has decreed for the daughters of Adam (Sahih al-Bukhari and Sahih Muslim). A period is not dirty in a shameful sense and not a punishment.\n\nTalk to your daughter before her first period, gently and simply, so it does not come as a shock. Many girls start between about 9 and 15.\n\n## What changes in worship\n\n- During her period she does not pray and does not fast. Missed prayers are not made up; missed Ramadan fasts are made up later (Sahih Muslim).\n- She can still make dhikr and dua, listen to the Quran, and attend Eid gatherings.\n- Scholars differ on touching the Mushaf and reciting from memory during a period, so ask a trusted scholar.\n- When the period ends, she takes a ghusl and starts praying again.\n\n## Ghusl: the basics\n\n1. Make the intention in your heart.\n2. Say Bismillah and wash your hands.\n3. Wash the private parts.\n4. Do wudu as for prayer.\n5. Pour water over your head three times, making sure it reaches the roots of the hair.\n6. Wash the whole body, the right side and then the left, making sure no part stays dry.\n\nThe obligatory parts and details such as braids differ a little between schools; a trusted female teacher or scholar can explain.\n\n## Asking is never shameful\n\nUmm Sulaym once asked the Prophet ﷺ a private question about ghusl, beginning: Allah is not shy of the truth (Sahih al-Bukhari and Sahih Muslim). Let your daughter know she can ask you anything.\n\n## Mothers and fathers\n\n- Mothers usually lead these talks; if there is no mother at home, a trusted aunt or grandmother can help, but fathers can talk too.\n- Fathers: keep pads ready without embarrassment, never let brothers tease her, and notice when she is tired or in pain.\n- Hijab: the age and the way of starting is discussed among scholars and families. Talk about it with love and give her time; never force it through shame. Ask a trusted local scholar.\n- If she has very painful or very heavy periods, take her to a doctor.","bn":"## দায়িত্বশীল হওয়া\n\nইসলামে সন্তান বয়ঃসন্ধিতে বালেগ বা দায়িত্বশীল হয়। রাসূলুল্লাহ ﷺ বলেছেন, তিন ধরনের মানুষের ওপর থেকে কলম তুলে নেওয়া হয়েছে, তাদের একজন হলো শিশু, যতক্ষণ না সে বালেগ হয় (সুনান আবু দাউদ, জামে তিরমিজি)। তখন থেকে নামাজ, রোজা ও অন্যান্য দায়িত্ব তার নিজের।\n\nমেয়েদের ক্ষেত্রে সবচেয়ে স্পষ্ট লক্ষণ প্রথম মাসিক। আলেমরা আরও কিছু লক্ষণ এবং কোনো লক্ষণ না দেখা দিলে একটি বয়সসীমার কথা বলেন; বিস্তারিত বিষয়ে মাজহাবগুলোর মধ্যে পার্থক্য আছে, তাই বিশ্বস্ত আলেমকে জিজ্ঞেস করুন।\n\n## মাসিক স্বাভাবিক\n\nহজের সময় আয়েশা (রা.)-এর মাসিক শুরু হলে তিনি মন খারাপ করেছিলেন। রাসূলুল্লাহ ﷺ তাঁকে সান্ত্বনা দিয়ে বললেন: এটা এমন বিষয়, যা আল্লাহ আদমের কন্যাদের জন্য নির্ধারণ করেছেন (সহিহ বুখারি ও সহিহ মুসলিম)। মাসিক লজ্জার কিছু নয়, শাস্তিও নয়।\n\nপ্রথম মাসিকের আগেই মেয়ের সাথে কোমল ও সহজভাবে কথা বলুন, যেন হঠাৎ ধাক্কা না লাগে। অনেক মেয়ের প্রায় ৯ থেকে ১৫ বছরের মধ্যে শুরু হয়।\n\n## ইবাদতে কী বদলায়\n\n- মাসিকের সময় সে নামাজ পড়বে না, রোজাও রাখবে না। ছুটে যাওয়া নামাজ কাজা করতে হয় না; রমজানের ছুটে যাওয়া রোজা পরে কাজা করতে হয় (সহিহ মুসলিম)।\n- তখনো সে জিকির ও দোয়া করতে পারে, কুরআন শুনতে পারে, ঈদের জমায়েতে যেতে পারে।\n- মাসিকের সময় কুরআন শরিফ ছোঁয়া ও মুখস্থ থেকে তিলাওয়াত নিয়ে আলেমদের মধ্যে মতভেদ আছে, তাই বিশ্বস্ত আলেমকে জিজ্ঞেস করুন।\n- মাসিক শেষ হলে সে গোসল করে আবার নামাজ শুরু করবে।\n\n## গোসল: মূল বিষয়\n\n1. মনে মনে নিয়ত করো।\n2. বিসমিল্লাহ বলে হাত ধোও।\n3. লজ্জাস্থান ধোও।\n4. নামাজের মতো অজু করো।\n5. মাথায় তিনবার পানি ঢালো, চুলের গোড়া পর্যন্ত যেন পৌঁছায়।\n6. পুরো শরীর ধোও — আগে ডান পাশ, তারপর বাম পাশ — কোনো অংশ যেন শুকনো না থাকে।\n\nফরজ অংশ আর বেণির মতো খুঁটিনাটি বিষয়ে মাজহাবভেদে সামান্য পার্থক্য আছে; বিশ্বস্ত কোনো নারী শিক্ষক বা আলেম বুঝিয়ে দিতে পারবেন।\n\n## প্রশ্ন করা কখনো লজ্জার নয়\n\nউম্মে সুলাইম (রা.) একবার রাসূলুল্লাহ ﷺ-কে গোসল নিয়ে একটি ব্যক্তিগত প্রশ্ন করেছিলেন, শুরু করেছিলেন এই কথা দিয়ে: আল্লাহ সত্য বলতে লজ্জা করেন না (সহিহ বুখারি ও সহিহ মুসলিম)। মেয়েকে জানিয়ে দিন, সে আপনাকে যেকোনো কিছু জিজ্ঞেস করতে পারে।\n\n## মা ও বাবা\n\n- সাধারণত মা এই আলাপগুলো করেন; ঘরে মা না থাকলে বিশ্বস্ত খালা, ফুপু বা নানি-দাদি সাহায্য করতে পারেন, তবে বাবাও কথা বলতে পারেন।\n- বাবারা: অস্বস্তি ছাড়াই প্যাড এনে রাখুন, ভাইয়েরা যেন কখনো তাকে খেপাতে না পারে, আর সে ক্লান্ত বা ব্যথায় থাকলে খেয়াল করুন।\n- হিজাব: কোন বয়সে ও কীভাবে শুরু করবে, তা নিয়ে আলেম ও পরিবারগুলোর মধ্যে আলোচনা আছে। ভালোবাসা দিয়ে কথা বলুন, তাকে সময় দিন; লজ্জা দিয়ে কখনো জোর করবেন না। বিশ্বস্ত স্থানীয় আলেমকে জিজ্ঞেস করুন।\n- মাসিকে খুব ব্যথা হলে বা খুব বেশি রক্ত গেলে তাকে ডাক্তারের কাছে নিয়ে যান।"}'::jsonb, '{}'::jsonb, 4, 2922, 5844, '{}'::text[], 'female', ARRAY['puberty', 'girls', 'periods', 'menstruation', 'ghusl', 'baligh', 'hijab']::text[], false, 'in_review'::lp_review_status, 9039),
  ('isl-puberty-boys', 'article', 'islamic', 'shared', 'important', 'religious', '🌿', '{"en":"Puberty in Islam: for sons and their parents","bn":"ইসলামে বয়ঃসন্ধি: ছেলে ও তার বাবা-মায়ের জন্য"}'::jsonb, '{"en":"Puberty means your son is now accountable before Allah. What wet dreams mean, the basics of ghusl and fitrah hygiene, and how fathers can lead the talk.","bn":"বয়ঃসন্ধি মানে আপনার ছেলে এখন আল্লাহর কাছে নিজের দায়িত্বশীল। স্বপ্নদোষ মানে কী, গোসল ও ফিতরাতের পরিচ্ছন্নতার মূল বিষয়, আর বাবারা কীভাবে আলাপটা শুরু করবেন।"}'::jsonb, '{"en":"## Becoming accountable\n\nIn Islam, a child becomes baligh, accountable, at puberty. The Prophet ﷺ said that the pen is lifted from three, including the child until they reach puberty (Sunan Abi Dawud, Jami'' at-Tirmidhi). From then, salah, fasting and other duties are his own.\n\nFor boys, the clearest sign is a wet dream or the release of sexual fluid (semen). Scholars also mention other signs, such as the growth of pubic hair, and an age limit if no sign appears; the schools differ on the details, so ask a trusted scholar.\n\n## Wet dreams are normal\n\nMany boys have their first wet dream between about 11 and 15. It is a natural part of growing up, not a sin and nothing to be ashamed of. What it means in worship is simple: he needs a ghusl before his next prayer.\n\nTalk to your son before it happens, so he is not confused or frightened, and so he does not learn about it first from friends or the internet.\n\n## Ghusl: the basics\n\n1. Make the intention in your heart.\n2. Say Bismillah and wash your hands.\n3. Wash the private parts.\n4. Do wudu as for prayer.\n5. Pour water over your head three times, making sure it reaches the roots of the hair.\n6. Wash the whole body, the right side and then the left, making sure no part stays dry.\n\nSmall details, such as which parts are obligatory, differ a little between the schools of law. Your son''s teacher or a trusted scholar can explain.\n\n## Fitrah hygiene\n\nThe Prophet ﷺ named five things of the fitrah: circumcision, removing pubic hair, trimming the moustache, clipping the nails and removing underarm hair (Sahih al-Bukhari and Sahih Muslim). Anas said they were given a limit of not leaving these for more than forty nights (Sahih Muslim). Show your son how to do this safely and privately.\n\n## Asking is never shameful\n\nUmm Sulaym once asked the Prophet ﷺ a private question about ghusl, beginning: Allah is not shy of the truth (Sahih al-Bukhari and Sahih Muslim). Let your son know he can ask you anything.\n\n## New responsibilities, with support\n\n- Salah and Ramadan fasting are now obligatory. Encourage him warmly, pray with him, and be patient while the habit grows.\n- Lowering the gaze: Allah tells believing men first to lower their gaze and guard their modesty (Surah An-Nur 24:30). Talk openly about what he sees online.\n- Privacy: from now on he knocks before entering any room (Surah An-Nur 24:59), and others knock before entering his.\n\n## Fathers\n\nThis is a conversation fathers should lead. Choose a calm moment, such as a walk or a drive. If the father is absent, an uncle, grandfather or the mother can step in. Keep the door open: “You can ask me anything, and I will never laugh at you.”","bn":"## দায়িত্বশীল হওয়া\n\nইসলামে সন্তান বয়ঃসন্ধিতে বালেগ বা দায়িত্বশীল হয়। রাসূলুল্লাহ ﷺ বলেছেন, তিন ধরনের মানুষের ওপর থেকে কলম তুলে নেওয়া হয়েছে, তাদের একজন হলো শিশু, যতক্ষণ না সে বালেগ হয় (সুনান আবু দাউদ, জামে তিরমিজি)। তখন থেকে নামাজ, রোজা ও অন্যান্য দায়িত্ব তার নিজের।\n\nছেলেদের ক্ষেত্রে সবচেয়ে স্পষ্ট লক্ষণ স্বপ্নদোষ বা বীর্যপাত। আলেমরা আরও কিছু লক্ষণ, যেমন নাভির নিচে লোম গজানো, এবং কোনো লক্ষণ না দেখা দিলে একটি বয়সসীমার কথা বলেন; বিস্তারিত বিষয়ে মাজহাবগুলোর মধ্যে পার্থক্য আছে, তাই বিশ্বস্ত আলেমকে জিজ্ঞেস করুন।\n\n## স্বপ্নদোষ স্বাভাবিক\n\nঅনেক ছেলের প্রায় ১১ থেকে ১৫ বছরের মধ্যে প্রথম স্বপ্নদোষ হয়। এটা বড় হওয়ার স্বাভাবিক অংশ, গুনাহ নয়, লজ্জারও কিছু নয়। ইবাদতের দিক থেকে এর মানে সহজ: পরের নামাজের আগে তাকে গোসল করতে হবে।\n\nঘটনাটা ঘটার আগেই ছেলের সাথে কথা বলুন, যেন সে বিভ্রান্ত বা ভীত না হয়, আর প্রথমে বন্ধু বা ইন্টারনেট থেকে না শেখে।\n\n## গোসল: মূল বিষয়\n\n1. মনে মনে নিয়ত করো।\n2. বিসমিল্লাহ বলে হাত ধোও।\n3. লজ্জাস্থান ধোও।\n4. নামাজের মতো অজু করো।\n5. মাথায় তিনবার পানি ঢালো, চুলের গোড়া পর্যন্ত যেন পৌঁছায়।\n6. পুরো শরীর ধোও — আগে ডান পাশ, তারপর বাম পাশ — কোনো অংশ যেন শুকনো না থাকে।\n\nকোন অংশগুলো ফরজ — এমন ছোটখাটো বিষয়ে মাজহাবভেদে সামান্য পার্থক্য আছে। ছেলের শিক্ষক বা বিশ্বস্ত আলেম বুঝিয়ে দিতে পারবেন।\n\n## ফিতরাতের পরিচ্ছন্নতা\n\nরাসূলুল্লাহ ﷺ ফিতরাতের পাঁচটি বিষয় বলেছেন: খতনা, নাভির নিচের লোম পরিষ্কার, গোঁফ ছাঁটা, নখ কাটা এবং বগলের লোম পরিষ্কার (সহিহ বুখারি ও সহিহ মুসলিম)। আনাস (রা.) বলেছেন, এগুলো চল্লিশ রাতের বেশি না রেখে দেওয়ার সীমা তাঁদের দেওয়া হয়েছিল (সহিহ মুসলিম)। ছেলেকে নিরাপদে ও গোপনে এগুলো করার নিয়ম দেখিয়ে দিন।\n\n## প্রশ্ন করা কখনো লজ্জার নয়\n\nউম্মে সুলাইম (রা.) একবার রাসূলুল্লাহ ﷺ-কে গোসল নিয়ে একটি ব্যক্তিগত প্রশ্ন করেছিলেন, শুরু করেছিলেন এই কথা দিয়ে: আল্লাহ সত্য বলতে লজ্জা করেন না (সহিহ বুখারি ও সহিহ মুসলিম)। ছেলেকে জানিয়ে দিন, সে আপনাকে যেকোনো কিছু জিজ্ঞেস করতে পারে।\n\n## নতুন দায়িত্ব, সাথে সহায়তা\n\n- নামাজ ও রমজানের রোজা এখন ফরজ। আন্তরিকভাবে উৎসাহ দিন, তার সাথে নামাজ পড়ুন, আর অভ্যাস গড়ে ওঠা পর্যন্ত ধৈর্য ধরুন।\n- দৃষ্টি নত রাখা: আল্লাহ প্রথমে মুমিন পুরুষদের দৃষ্টি নত রাখতে ও লজ্জাস্থান হেফাজত করতে বলেছেন (সূরা আন-নূর ২৪:৩০)। অনলাইনে সে কী দেখে, তা নিয়ে খোলাখুলি কথা বলুন।\n- গোপনীয়তা: এখন থেকে সে যেকোনো ঘরে ঢোকার আগে অনুমতি নেবে (সূরা আন-নূর ২৪:৫৯), আর অন্যরাও তার ঘরে ঢোকার আগে অনুমতি নেবে।\n\n## বাবাদের জন্য\n\nএই আলাপটা বাবাদেরই শুরু করা উচিত। হাঁটতে বা গাড়িতে যেতে যেতে — এমন শান্ত মুহূর্ত বাছুন। বাবা না থাকলে চাচা, মামা, দাদা-নানা বা মা এগিয়ে আসতে পারেন। দরজাটা খোলা রাখুন: “তুমি আমাকে যেকোনো কিছু জিজ্ঞেস করতে পারো, আমি কখনো তোমাকে নিয়ে হাসব না।”"}'::jsonb, '{}'::jsonb, 4, 3287, 5844, '{}'::text[], 'male', ARRAY['puberty', 'boys', 'wet dreams', 'ghusl', 'baligh', 'fitrah', 'hygiene']::text[], false, 'in_review'::lp_review_status, 9040),
  ('isl-modesty-haya', 'article', 'islamic', 'shared', 'educational', 'religious', '🌾', '{"en":"Haya and modesty for boys and girls","bn":"ছেলে ও মেয়ের জন্য হায়া ও শালীনতা"}'::jsonb, '{"en":"Haya is part of faith and brings only good. It is for boys as much as girls, it protects children''s bodies and dignity, and it never means being too shy to ask or speak up.","bn":"হায়া ঈমানের অংশ এবং তা শুধু কল্যাণই আনে। এটা মেয়েদের মতো ছেলেদের জন্যও, শিশুর শরীর ও মর্যাদা রক্ষা করে, আর এর মানে কখনো প্রশ্ন করতে বা মুখ খুলতে লজ্জা পাওয়া নয়।"}'::jsonb, '{"en":"## What haya is\n\nHaya is a beautiful mix of modesty, self-respect and a feeling of shame before doing wrong. The Prophet ﷺ said that haya is a branch of faith (Sahih al-Bukhari and Sahih Muslim), and that haya brings nothing but good (Sahih al-Bukhari and Sahih Muslim).\n\n## For boys as much as girls\n\nIn many homes modesty is taught only to daughters. But Allah tells believing men first to lower their gaze and guard their modesty, and then tells believing women the same (Surah An-Nur 24:30–31). Sons need to learn modest clothes, respectful eyes, clean speech and respect for girls just as much.\n\nAllah also reminds us that the best clothing is the clothing of taqwa, mindfulness of Him (Surah Al-A''raf 7:26). Modesty starts in the heart.\n\n## Privacy at home, from the Quran\n\nSurah An-Nur teaches children to ask permission before entering their parents'' room at three times: before Fajr, when clothes are taken off at midday, and after ''Isha (Surah An-Nur 24:58). Once they reach puberty, they ask permission at all times (Surah An-Nur 24:59). The Prophet ﷺ also told parents to separate children''s beds by about ten (Sunan Abi Dawud 495).\n\nYou can teach this from about five: knock, wait for a yes, and close the door when changing or using the toilet.\n\n## Haya protects children\n\nModesty and body safety go together. Teach in simple words:\n\n- Your private parts are covered by your underwear. They are yours.\n- No one should touch them or ask to see them, except a parent or doctor helping you to be clean or healthy, with a trusted adult there.\n- No one should ask you to keep a secret about touching. Tell Ammu or Abbu straight away, even if that person is someone we know.\n- You will never be in trouble for telling.\n\n## Haya is not silence\n\n''A''ishah praised the women of the Ansar because their haya did not stop them from learning their religion (Sahih Muslim). A child with haya can still ask questions, say no, and speak up when something is wrong.\n\n## Hijab and dress\n\nThe age and way of starting hijab is discussed among scholars and families. Many girls begin by choice before puberty, and scholars explain it as a duty from puberty. Ask a trusted local scholar. Whatever you decide, build love for it through example, praise and freedom to ask questions, never through shame, insults or force.\n\n## What harms haya\n\n- Mocking a child''s body, weight, skin colour or development.\n- Changing children in front of guests, or posting their bath photos online.\n- Harsh shaming about clothes. It teaches fear, not modesty.\n- Unsupervised screens. Talk often about what they see online.","bn":"## হায়া কী\n\nহায়া হলো শালীনতা, আত্মমর্যাদা আর অন্যায় করার আগে লজ্জাবোধের এক সুন্দর মিশ্রণ। রাসূলুল্লাহ ﷺ বলেছেন, হায়া ঈমানের একটি শাখা (সহিহ বুখারি ও সহিহ মুসলিম), আর হায়া শুধু কল্যাণই নিয়ে আসে (সহিহ বুখারি ও সহিহ মুসলিম)।\n\n## মেয়েদের মতো ছেলেদের জন্যও\n\nঅনেক ঘরে শালীনতা শুধু মেয়েদের শেখানো হয়। কিন্তু আল্লাহ প্রথমে মুমিন পুরুষদের দৃষ্টি নত রাখতে ও লজ্জাস্থান হেফাজত করতে বলেছেন, তারপর মুমিন নারীদেরও একই কথা বলেছেন (সূরা আন-নূর ২৪:৩০–৩১)। ছেলেদেরও সমানভাবে শিখতে হবে শালীন পোশাক, সম্মানজনক দৃষ্টি, পরিচ্ছন্ন কথা আর মেয়েদের প্রতি সম্মান।\n\nআল্লাহ আরও মনে করিয়ে দেন, সবচেয়ে উত্তম পোশাক হলো তাকওয়ার পোশাক (সূরা আল-আ''রাফ ৭:২৬)। শালীনতা শুরু হয় মন থেকে।\n\n## কুরআন থেকে ঘরের গোপনীয়তা\n\nসূরা আন-নূর শিশুদের তিন সময়ে বাবা-মায়ের ঘরে ঢোকার আগে অনুমতি নিতে শেখায়: ফজরের আগে, দুপুরে যখন কাপড় খুলে রাখা হয়, আর এশার পরে (সূরা আন-নূর ২৪:৫৮)। বালেগ হলে তারা সব সময়ই অনুমতি নেবে (সূরা আন-নূর ২৪:৫৯)। রাসূলুল্লাহ ﷺ দশ বছর বয়সে সন্তানদের বিছানা আলাদা করতেও বলেছেন (সুনান আবু দাউদ ৪৯৫)।\n\nপাঁচ বছর বয়স থেকেই শেখাতে পারেন: দরজায় টোকা দাও, হ্যাঁ বলা পর্যন্ত অপেক্ষা করো, আর কাপড় বদলানো বা টয়লেটের সময় দরজা বন্ধ রাখো।\n\n## হায়া শিশুকে রক্ষা করে\n\nশালীনতা আর শরীরের নিরাপত্তা একসাথে চলে। সহজ কথায় শেখান:\n\n- জাঙ্গিয়া বা প্যান্টি যে জায়গা ঢেকে রাখে, সেটা তোমার গোপন অঙ্গ। এটা তোমার।\n- কেউ সেখানে ছোঁবে না বা দেখতে চাইবে না — শুধু বাবা-মা বা ডাক্তার, তোমাকে পরিষ্কার বা সুস্থ রাখতে, কোনো বিশ্বস্ত বড় মানুষের উপস্থিতিতে।\n- ছোঁয়া নিয়ে কেউ তোমাকে কথা গোপন রাখতে বলবে না। সাথে সাথে আম্মু বা আব্বুকে বলবে, সে চেনা কেউ হলেও।\n- বললে তুমি কখনো বিপদে পড়বে না।\n\n## হায়া মানে চুপ থাকা নয়\n\nআয়েশা (রা.) আনসারি নারীদের প্রশংসা করেছেন, কারণ তাঁদের হায়া তাঁদের দ্বীন শেখা থেকে আটকায়নি (সহিহ মুসলিম)। হায়াসম্পন্ন শিশুও প্রশ্ন করতে পারে, না বলতে পারে, আর কিছু ভুল হলে মুখ খুলতে পারে।\n\n## হিজাব ও পোশাক\n\nকোন বয়সে ও কীভাবে হিজাব শুরু হবে, তা নিয়ে আলেম ও পরিবারগুলোর মধ্যে আলোচনা আছে। অনেক মেয়ে বালেগ হওয়ার আগেই নিজের ইচ্ছায় শুরু করে, আর আলেমরা বালেগ হওয়া থেকে একে দায়িত্ব হিসেবে ব্যাখ্যা করেন। বিশ্বস্ত স্থানীয় আলেমকে জিজ্ঞেস করুন। যে সিদ্ধান্তই নিন, উদাহরণ, প্রশংসা আর প্রশ্ন করার স্বাধীনতা দিয়ে ভালোবাসা গড়ুন — লজ্জা, অপমান বা জোর দিয়ে কখনো নয়।\n\n## যা হায়ার ক্ষতি করে\n\n- শিশুর শরীর, ওজন, গায়ের রং বা বেড়ে ওঠা নিয়ে ঠাট্টা।\n- অতিথিদের সামনে শিশুর কাপড় বদলানো, বা গোসলের ছবি অনলাইনে দেওয়া।\n- পোশাক নিয়ে কঠোরভাবে লজ্জা দেওয়া — এতে শালীনতা নয়, ভয় শেখে।\n- নজরদারি ছাড়া স্ক্রিন। অনলাইনে সে কী দেখে, তা নিয়ে প্রায়ই কথা বলুন।"}'::jsonb, '{}'::jsonb, 4, 1826, 7305, '{}'::text[], 'any', ARRAY['haya', 'modesty', 'privacy', 'body safety', 'lowering gaze', 'hijab', 'boys and girls']::text[], false, 'in_review'::lp_review_status, 9041),
  ('isl-teen-faith-questions', 'scenario', 'islamic', 'shared', 'important', 'religious', '💭', '{"en":"My teen has questions or doubts about faith","bn":"আমার কিশোর সন্তানের ঈমান নিয়ে প্রশ্ন বা সংশয় আছে"}'::jsonb, '{"en":"Questions are not the end of faith; often they are the start of a stronger one. Listen first, never shame, and look for answers together.","bn":"প্রশ্ন ঈমানের শেষ নয়; প্রায়ই এটা আরও মজবুত ঈমানের শুরু। আগে শুনুন, কখনো লজ্জা দেবেন না, আর একসাথে উত্তর খুঁজুন।"}'::jsonb, '{}'::jsonb, '{"understand":{"en":"Your teen may say things like “How do we know Islam is true?”, “Why do I have to pray?” or “My friend says religion is just made up.” They may stop praying, or seem bored or angry at the masjid. This can feel frightening for a parent.","bn":"আপনার কিশোর সন্তান হয়তো বলছে, “ইসলাম যে সত্য, আমরা কীভাবে জানি?”, “আমাকে কেন নামাজ পড়তে হবে?” বা “আমার বন্ধু বলে ধর্ম মানুষের বানানো।” হয়তো নামাজ ছেড়ে দিয়েছে, বা মসজিদে বিরক্ত বা রাগী মনে হচ্ছে। বাবা-মায়ের জন্য এটা ভয়ের মনে হতে পারে।"},"why":{"en":"Teenagers start to think for themselves. They meet new ideas at school, online and from friends, and they want faith that is their own, not only their parents''. The Quran invites reflection: do they not reflect on the Quran? (Surah An-Nisa 4:82). Even Ibrahim asked Allah to show him how He gives life to the dead, not from disbelief, but so that his heart would be at peace (Surah Al-Baqarah 2:260). Some Companions told the Prophet ﷺ that they found thoughts in themselves too terrible to say. He did not scold them; he said that their discomfort with such thoughts was a sign of clear faith (Sahih Muslim). And Allah says there is no compulsion in religion (Surah Al-Baqarah 2:256): faith grows by conviction, not force.","bn":"কিশোর বয়সে সন্তান নিজে নিজে ভাবতে শুরু করে। স্কুলে, অনলাইনে, বন্ধুদের কাছে নতুন নতুন ধারণার মুখোমুখি হয়, আর এমন ঈমান চায় যা শুধু বাবা-মায়ের নয়, তার নিজের। কুরআন চিন্তা করতে ডাকে: তারা কি কুরআন নিয়ে চিন্তা করে না? (সূরা আন-নিসা ৪:৮২)। এমনকি ইবরাহিম (আ.)-ও আল্লাহর কাছে জানতে চেয়েছিলেন তিনি কীভাবে মৃতকে জীবিত করেন — অবিশ্বাস থেকে নয়, বরং মন প্রশান্ত করার জন্য (সূরা আল-বাকারা ২:২৬০)। কিছু সাহাবি রাসূলুল্লাহ ﷺ-কে বলেছিলেন, তাঁদের মনে এমন চিন্তা আসে যা মুখে আনাও ভয়ংকর। তিনি তাঁদের বকেননি; বলেছেন, এমন চিন্তায় অস্বস্তি বোধ করাই স্পষ্ট ঈমানের লক্ষণ (সহিহ মুসলিম)। আর আল্লাহ বলেন, দ্বীনের ব্যাপারে কোনো জবরদস্তি নেই (সূরা আল-বাকারা ২:২৫৬): ঈমান বাড়ে বিশ্বাস থেকে, জোর থেকে নয়।"},"normal":{"en":"Questions and ups and downs in practice are common in the teen years, including in children from very religious homes. Many young people who were allowed to ask and were answered with patience grow into adults with deep, confident faith.","bn":"কিশোর বয়সে প্রশ্ন আর আমলে ওঠানামা খুবই সাধারণ, খুব ধার্মিক পরিবারের সন্তানদের মধ্যেও। যে তরুণরা প্রশ্ন করার সুযোগ পেয়েছে আর ধৈর্যের সাথে উত্তর পেয়েছে, তাদের অনেকেই গভীর ও আত্মবিশ্বাসী ঈমান নিয়ে বড় হয়।"},"do_now":{"en":["Stay calm. Take a breath before you answer.","Thank them for telling you: “I''m glad you can talk to me about this.”","Ask what made them think about it, and listen to the end without interrupting.","Say honestly if you do not know an answer: “Good question. Let''s find out together.”","Make dua for them quietly, and keep loving them openly."],"bn":["শান্ত থাকুন। উত্তর দেওয়ার আগে একটা লম্বা শ্বাস নিন।","বলার জন্য ধন্যবাদ দিন: “তুমি যে আমার সাথে এ নিয়ে কথা বলতে পারছ, তাতে আমি খুশি।”","জিজ্ঞেস করুন কী কারণে সে এটা ভাবছে, আর বাধা না দিয়ে শেষ পর্যন্ত শুনুন।","উত্তর না জানলে সৎভাবে বলুন: “ভালো প্রশ্ন। চলো একসাথে খুঁজে দেখি।”","চুপিচুপি তার জন্য দোয়া করুন, আর খোলাখুলি ভালোবাসা দেখাতে থাকুন।"]},"steps":{"en":["Keep regular one-to-one time that is not about religion: food, walks, sport, their interests.","Explore questions together using trusted books, talks or a knowledgeable, gentle scholar or mentor who is good with young people.","Share why faith matters to you personally, including your own struggles, not just rules.","Connect them with good company: a youth circle, a volunteering project, a mentor they look up to.","Invite rather than order: “Will you pray Maghrib with me?” Keep your own worship visible and joyful.","Talk about the online content they are watching, and watch some of it together.","Be patient over months and years. Faith often comes back stronger after a period of questioning."],"bn":["ধর্মের বাইরে নিয়মিত একান্ত সময় রাখুন: খাবার, হাঁটা, খেলা, তার পছন্দের বিষয়।","নির্ভরযোগ্য বই, আলোচনা, বা তরুণদের সাথে ভালো মেশেন এমন জ্ঞানী ও কোমল আলেম বা মেন্টরের সাহায্যে একসাথে প্রশ্নগুলো খুঁজে দেখুন।","শুধু নিয়ম নয়, ঈমান আপনার কাছে ব্যক্তিগতভাবে কেন জরুরি, নিজের সংগ্রামসহ তা বলুন।","ভালো সঙ্গের সাথে যুক্ত করুন: তরুণদের হালাকা, স্বেচ্ছাসেবী কাজ, বা সে শ্রদ্ধা করে এমন একজন মেন্টর।","হুকুম নয়, আমন্ত্রণ: “আমার সাথে মাগরিব পড়বে?” নিজের ইবাদত দৃশ্যমান ও আনন্দময় রাখুন।","অনলাইনে সে কী দেখছে তা নিয়ে কথা বলুন, আর কিছু কিছু একসাথে দেখুন।","মাসের পর মাস, বছরের পর বছর ধৈর্য ধরুন। প্রশ্নের সময় পেরিয়ে ঈমান প্রায়ই আরও মজবুত হয়ে ফেরে।"]},"avoid":{"en":["Shouting, mocking or calling them a kafir or a bad Muslim","Using fear of Hell as the main answer","Telling relatives or the community about their doubts","Banning all questions or saying “just believe and don''t ask”","Cutting off love, money or contact as a punishment","Forcing worship with threats or hitting"],"bn":["চিৎকার, ঠাট্টা, বা তাকে কাফির বা খারাপ মুসলিম বলা","জাহান্নামের ভয়কে মূল উত্তর বানানো","আত্মীয় বা পাড়ার লোকদের তার সংশয়ের কথা বলে দেওয়া","সব প্রশ্ন নিষেধ করা বা বলা “শুধু বিশ্বাস করো, প্রশ্ন কোরো না”","শাস্তি হিসেবে ভালোবাসা, টাকা বা যোগাযোগ বন্ধ করা","হুমকি বা মারধর দিয়ে ইবাদত করানো"]},"example":{"en":"Sixteen-year-old Tahsin said at dinner, “I''m not sure I believe any of this.” His father felt a jolt of fear, but he put down his spoon and said, “That''s a big thing to say. Thank you for being honest with me. What''s been making you think about it?” They talked for an hour. A week later they went together to a youth talk at a local masjid, and on the way home Tahsin asked his father why he prayed. His father told him about the hardest year of his own life.","bn":"ষোলো বছরের তাহসিন রাতের খাবারে বলল, “আমি নিশ্চিত না যে এসব আমি বিশ্বাস করি।” বাবার বুকটা ভয়ে ধক করে উঠল, কিন্তু তিনি চামচ নামিয়ে রেখে বললেন, “এটা বড় একটা কথা। সৎভাবে বলার জন্য ধন্যবাদ। কী কারণে এসব ভাবছ?” তারা এক ঘণ্টা কথা বলল। এক সপ্তাহ পর দুজনে মহল্লার মসজিদে তরুণদের একটা আলোচনায় গেল, আর ফেরার পথে তাহসিন বাবাকে জিজ্ঞেস করল, তিনি কেন নামাজ পড়েন। বাবা তাকে নিজের জীবনের সবচেয়ে কঠিন বছরের গল্প বললেন।"},"seek_help":{"en":["If your teen seems very sad, hopeless or withdrawn for more than two weeks, talk to a counsellor or doctor as well","If they talk about harming themselves or not wanting to live, get help the same day; in an emergency call 999","If you feel out of your depth, ask a scholar or youth worker who is known for being gentle with young people"],"bn":["দুই সপ্তাহের বেশি সন্তানকে খুব বিষণ্ণ, হতাশ বা গুটিয়ে থাকা মনে হলে একজন কাউন্সেলর বা ডাক্তারের সাথেও কথা বলুন","নিজের ক্ষতি করা বা বেঁচে থাকতে না চাওয়ার কথা বললে সেদিনই সাহায্য নিন; জরুরি হলে ৯৯৯-এ ফোন করুন","নিজে সামলাতে না পারলে এমন আলেম বা তরুণদের নিয়ে কাজ করেন এমন কাউকে জিজ্ঞেস করুন, যিনি তরুণদের সাথে কোমল আচরণের জন্য পরিচিত"]}}'::jsonb, 4, 4748, 7305, '{}'::text[], 'any', ARRAY['teen', 'doubts', 'questions', 'faith', 'listening', 'iman']::text[], false, 'in_review'::lp_review_status, 9042),
  ('isl-good-friends', 'article', 'islamic', 'shared', 'educational', 'religious', '🧑‍🤝‍🧑', '{"en":"Good friends: the perfume seller and the blacksmith","bn":"ভালো বন্ধু: আতর বিক্রেতা ও কামার"}'::jsonb, '{"en":"The Prophet ﷺ compared friends to a perfume seller and a blacksmith. How to help children choose good company without cutting them off from the world.","bn":"রাসূলুল্লাহ ﷺ বন্ধুকে আতর বিক্রেতা আর কামারের সাথে তুলনা করেছেন। দুনিয়া থেকে বিচ্ছিন্ন না করে কীভাবে সন্তানকে ভালো সঙ্গ বাছতে সাহায্য করবেন।"}'::jsonb, '{"en":"## The hadith\n\nThe Prophet ﷺ said: the example of a good companion and a bad companion is like the perfume seller and the blacksmith. The perfume seller may give you some perfume, or you may buy some from him, or at least you will enjoy a pleasant smell. The blacksmith may burn your clothes, or at least you will get a bad smell from him (Sahih al-Bukhari and Sahih Muslim).\n\nHe also said: a person follows the way of their close friend, so let each of you look carefully at whom you befriend (Sunan Abi Dawud, Jami'' at-Tirmidhi).\n\nThe point is simple and children understand it well: we take on the “smell” of the people we spend time with.\n\n## Share the picture with your child\n\nAsk: which friends leave you feeling better, kinder and happier? Which ones leave you feeling worse, or pushed to do things you know are wrong? Let them think it through. A conclusion they reach themselves lasts longer than a rule.\n\n## What helps\n\n- **Know their friends.** Learn their names, welcome them home, offer food. A home where friends are welcome lets you see who they spend time with.\n- **Open good doors.** Sport, scouts, a youth circle at the masjid, volunteering, a Quran class with friends. Good company is easier to find when there are good places to go.\n- **Be a friend yourself.** Teens who feel close to their parents are less pulled by peer pressure.\n- **Practise saying no.** Role-play: “Come on, everyone''s doing it.” “No thanks, I''m going home.”\n- **Online friends count too.** Talk about who they chat with and what groups they are in.\n\n## Kindness to everyone\n\nGood company does not mean only Muslim friends, or looking down on others. Allah does not forbid us from being kind and fair to people of other faiths who live peacefully with us (Surah Al-Mumtahanah 60:8). A good friend of any background who is honest and kind is a perfume seller.\n\n## When you are worried about a friend\n\nAvoid banning a friend in anger. It often pushes children closer to them. Instead, say calmly what worries you, listen to your child''s view, set clear limits (where, when, with whom), and spend more time with your child yourself. If you see signs of drugs, bullying, or someone much older taking a special interest in your child, act quickly and get help.\n\nAllah tells the Prophet ﷺ to keep himself patiently with those who call on their Lord morning and evening (Surah Al-Kahf 18:28). Help your children find, and become, that kind of friend.","bn":"## হাদিসটি\n\nরাসূলুল্লাহ ﷺ বলেছেন: ভালো সঙ্গী আর খারাপ সঙ্গীর উদাহরণ আতর বিক্রেতা আর কামারের মতো। আতর বিক্রেতা হয়তো তোমাকে কিছু আতর দেবে, বা তুমি তার কাছ থেকে কিনবে, নয়তো অন্তত সুগন্ধ পাবে। কামার হয়তো তোমার কাপড় পুড়িয়ে দেবে, নয়তো অন্তত তার কাছ থেকে দুর্গন্ধ পাবে (সহিহ বুখারি ও সহিহ মুসলিম)।\n\nতিনি আরও বলেছেন: মানুষ তার ঘনিষ্ঠ বন্ধুর পথে চলে, তাই তোমরা প্রত্যেকে দেখে নাও কাকে বন্ধু বানাচ্ছ (সুনান আবু দাউদ, জামে তিরমিজি)।\n\nকথাটা সহজ, শিশুরাও ভালো বোঝে: আমরা যাদের সাথে সময় কাটাই, তাদের “গন্ধ” আমাদের গায়েও লাগে।\n\n## ছবিটা সন্তানের সাথে ভাগ করুন\n\nজিজ্ঞেস করুন: কোন বন্ধুদের সাথে থাকলে তুমি আরও ভালো, দয়ালু আর খুশি বোধ করো? কাদের সাথে থাকলে খারাপ লাগে, বা যে কাজ ভুল জানো তা করতে চাপ আসে? তাকে নিজে ভাবতে দিন। নিজে যে সিদ্ধান্তে পৌঁছায়, তা নিয়মের চেয়ে বেশি দিন টেকে।\n\n## যা সাহায্য করে\n\n- **তার বন্ধুদের চিনুন।** নাম জানুন, ঘরে স্বাগত জানান, খেতে দিন। যে ঘরে বন্ধুরা স্বাগত, সেখানে আপনি দেখতে পান সন্তান কাদের সাথে সময় কাটায়।\n- **ভালো দরজা খুলে দিন।** খেলাধুলা, স্কাউট, মসজিদের তরুণদের হালাকা, স্বেচ্ছাসেবী কাজ, বন্ধুদের সাথে কুরআন ক্লাস। যাওয়ার মতো ভালো জায়গা থাকলে ভালো সঙ্গ পাওয়া সহজ হয়।\n- **নিজে বন্ধু হোন।** যে কিশোর বাবা-মায়ের কাছের, তার ওপর বন্ধুদের চাপ কম কাজ করে।\n- **না বলা অনুশীলন করুন।** অভিনয় করে দেখুন: “আরে চল, সবাই তো করছে।” “না, ধন্যবাদ, আমি বাসায় যাচ্ছি।”\n- **অনলাইনের বন্ধুরাও বন্ধু।** কার সাথে চ্যাট করে, কোন গ্রুপে আছে, তা নিয়ে কথা বলুন।\n\n## সবার প্রতি দয়া\n\nভালো সঙ্গ মানে শুধু মুসলিম বন্ধু রাখা বা অন্যদের ছোট করে দেখা নয়। যারা আমাদের সাথে শান্তিতে বাস করে, অন্য ধর্মের এমন মানুষদের প্রতি দয়া ও ন্যায় করতে আল্লাহ নিষেধ করেন না (সূরা আল-মুমতাহিনা ৬০:৮)। যেকোনো পরিচয়ের সৎ ও দয়ালু বন্ধুই আতর বিক্রেতা।\n\n## কোনো বন্ধুকে নিয়ে দুশ্চিন্তা হলে\n\nরাগের মাথায় কোনো বন্ধুকে নিষিদ্ধ করবেন না। এতে প্রায়ই সন্তান তার আরও কাছে চলে যায়। বরং শান্তভাবে বলুন কী নিয়ে চিন্তা, সন্তানের মত শুনুন, স্পষ্ট সীমা ঠিক করুন (কোথায়, কখন, কার সাথে), আর নিজে সন্তানের সাথে বেশি সময় কাটান। মাদক, বুলিং, বা অনেক বড় কেউ সন্তানের প্রতি বিশেষ আগ্রহ দেখাচ্ছে — এমন লক্ষণ দেখলে দ্রুত ব্যবস্থা নিন এবং সাহায্য চান।\n\nআল্লাহ রাসূলুল্লাহ ﷺ-কে বলেছেন, যারা সকাল-সন্ধ্যা তাদের রবকে ডাকে, ধৈর্যের সাথে তাদের সাথে থাকতে (সূরা আল-কাহফ ১৮:২৮)। সন্তানকে এমন বন্ধু খুঁজে পেতে আর নিজে এমন বন্ধু হতে সাহায্য করুন।"}'::jsonb, '{}'::jsonb, 3, 2557, 7305, '{}'::text[], 'any', ARRAY['friends', 'peer pressure', 'company', 'teens', 'perfume seller', 'blacksmith']::text[], false, 'in_review'::lp_review_status, 9043)
