INSERT INTO lp_task_templates (key, title, description, why, benefit, steps, safety_note, task_type, frequency, assignee, subject, min_day, max_day, estimated_minutes, xp, emoji, category_key, resource_slug, source_key, sex, review_status, sort_order) VALUES
  ('isl_choose_name', '{"en":"Choose a meaningful name together","bn":"একসাথে সুন্দর অর্থের একটি নাম বাছুন"}'::jsonb, '{"en":"Make a short list of names for a girl and a boy, check the meanings, and agree as a couple.","bn":"মেয়ে ও ছেলের জন্য নামের একটি ছোট তালিকা করুন, অর্থ যাচাই করুন, আর স্বামী-স্ত্রী মিলে একমত হোন।"}'::jsonb, '{"en":"The Prophet ﷺ chose good names and changed names with bad meanings. A name is a lifelong gift to your child.","bn":"রাসূলুল্লাহ ﷺ সুন্দর নাম রাখতেন এবং খারাপ অর্থের নাম বদলে দিতেন। নাম সন্তানের জন্য সারা জীবনের উপহার।"}'::jsonb, '{"en":"No last-minute rush, and a name both parents love with a meaning you are sure of.","bn":"শেষ মুহূর্তের তাড়াহুড়া নেই, আর এমন নাম যা দুজনেরই পছন্দ এবং যার অর্থ নিয়ে আপনি নিশ্চিত।"}'::jsonb, '[{"en":"Each parent writes three to five favourite names","bn":"বাবা-মা দুজনে তিন থেকে পাঁচটি পছন্দের নাম লিখুন"},{"en":"Check each meaning with a reliable dictionary or a scholar","bn":"নির্ভরযোগ্য অভিধান বা আলেমের কাছে প্রতিটির অর্থ যাচাই করুন"},{"en":"Check the spelling in Bangla and English for birth registration","bn":"জন্মনিবন্ধনের জন্য বাংলা ও ইংরেজি বানান দেখে নিন"},{"en":"Agree on a shortlist and make dua together","bn":"একটি ছোট তালিকায় একমত হোন এবং একসাথে দোয়া করুন"}]'::jsonb, '{}'::jsonb, 'family', 'once', 'shared', 'pregnancy', -280, 0, 30, 15, '📝', 'islamic_upbringing', 'isl-choosing-a-name', 'sahih_muslim', 'any', 'in_review'::lp_review_status, 9101),
  ('isl_aqiqah_planning', '{"en":"Plan the aqiqah, if you are able","bn":"সামর্থ্য থাকলে আকিকার পরিকল্পনা করুন"}'::jsonb, '{"en":"Decide what you can afford and arrange the aqiqah for the seventh day, or later if needed.","bn":"কতটুকু সামর্থ্য আছে ঠিক করুন, আর সপ্তম দিনে — প্রয়োজনে পরে — আকিকার ব্যবস্থা করুন।"}'::jsonb, '{"en":"Aqiqah is a sunnah of thanks for a new child, with a sacrifice, head shaving and charity.","bn":"আকিকা নতুন সন্তানের জন্য শুকরিয়ার একটি সুন্নাহ — পশু জবাই, মাথা মুণ্ডন ও সদকাসহ।"}'::jsonb, '{"en":"A calm, joyful celebration that includes the poor, without debt or stress.","bn":"ঋণ বা চাপ ছাড়া শান্ত, আনন্দময় উদযাপন, যাতে গরিবরাও শরিক।"}'::jsonb, '[{"en":"Agree on a budget as a couple","bn":"স্বামী-স্ত্রী মিলে বাজেট ঠিক করুন"},{"en":"Ask a trusted scholar if unsure about the animals or a cow share","bn":"পশু বা গরুর ভাগ নিয়ে নিশ্চিত না হলে বিশ্বস্ত আলেমকে জিজ্ঞেস করুন"},{"en":"Arrange the animal and the slaughter","bn":"পশু ও জবাইয়ের ব্যবস্থা করুন"},{"en":"Plan who will receive the meat, starting with the poor","bn":"কারা গোশত পাবে ঠিক করুন, গরিবদের দিয়ে শুরু করুন"}]'::jsonb, '{"en":"Shave the baby''s head only if the baby is well, with a clean new blade, by a careful person. The mother''s and baby''s health comes first; the aqiqah can wait.","bn":"শিশু সুস্থ থাকলে তবেই নতুন পরিষ্কার ব্লেড দিয়ে, সাবধানী কাউকে দিয়ে মাথা মুণ্ডন করান। মা ও শিশুর স্বাস্থ্য আগে; আকিকা অপেক্ষা করতে পারে।"}'::jsonb, 'recommended', 'once', 'shared', 'child', 0, 8, 30, 15, '🐐', 'islamic_upbringing', 'isl-aqiqah', 'sunan_abi_dawud', 'any', 'in_review'::lp_review_status, 9102),
  ('isl_bismillah_meals', '{"en":"Say Bismillah together at a meal","bn":"খাওয়ার সময় একসাথে বিসমিল্লাহ বলুন"}'::jsonb, '{}'::jsonb, '{"en":"The Prophet ﷺ taught a young boy: say Bismillah, eat with your right hand, and eat from what is near you.","bn":"রাসূলুল্লাহ ﷺ এক ছোট ছেলেকে শিখিয়েছিলেন: বিসমিল্লাহ বলো, ডান হাতে খাও, আর তোমার কাছ থেকে খাও।"}'::jsonb, '{"en":"A tiny daily habit that brings Allah into ordinary moments.","bn":"ছোট্ট একটি দৈনিক অভ্যাস, যা সাধারণ মুহূর্তেও আল্লাহকে মনে করিয়ে দেয়।"}'::jsonb, '[{"en":"Say Bismillah aloud before the first bite, and let your child copy","bn":"প্রথম লোকমার আগে জোরে বিসমিল্লাহ বলুন, সন্তানকে অনুকরণ করতে দিন"},{"en":"Gently guide the right hand","bn":"আলতো করে ডান হাত ঠিক করে দিন"},{"en":"End with Alhamdulillah together","bn":"একসাথে আলহামদুলিল্লাহ বলে শেষ করুন"}]'::jsonb, '{}'::jsonb, 'family', 'daily', 'shared', 'child', 730, 4748, 1, 5, '🍽️', 'islamic_upbringing', 'isl-eating-etiquette', 'sahih_bukhari', 'any', 'in_review'::lp_review_status, 9103),
  ('isl_teach_weekly_dua', '{"en":"Teach one new dua this week","bn":"এই সপ্তাহে একটি নতুন দোয়া শেখান"}'::jsonb, '{"en":"Pick one dua from the daily duas checklist and practise it at the real moment all week.","bn":"প্রতিদিনের দোয়ার চেকলিস্ট থেকে একটি দোয়া বেছে সারা সপ্তাহ আসল মুহূর্তে অনুশীলন করুন।"}'::jsonb, '{"en":"Children learn duas best by hearing them again and again at the right time, with the meaning explained.","bn":"শিশুরা ঠিক সময়ে বারবার শুনে আর অর্থ বুঝে সবচেয়ে ভালো দোয়া শেখে।"}'::jsonb, '{"en":"Over a year, your child can learn the everyday duas without pressure.","bn":"এক বছরে চাপ ছাড়াই সন্তান প্রতিদিনের দোয়াগুলো শিখে ফেলতে পারে।"}'::jsonb, '[{"en":"Choose one dua and explain its meaning in Bangla","bn":"একটি দোয়া বেছে বাংলায় অর্থ বুঝিয়ে দিন"},{"en":"Say it aloud yourself at the right moment every day","bn":"প্রতিদিন ঠিক মুহূর্তে নিজে জোরে পড়ুন"},{"en":"Tick it on a chart when your child can say it","bn":"সন্তান বলতে পারলে চার্টে টিক দিন"}]'::jsonb, '{}'::jsonb, 'learn', 'weekly', 'shared', 'child', 1096, 4748, 10, 10, '📿', 'islamic_upbringing', 'isl-daily-duas-checklist', 'hisnul_muslim', 'any', 'in_review'::lp_review_status, 9104),
  ('isl_learn_short_surah', '{"en":"Learn one short surah this month","bn":"এই মাসে একটি ছোট সূরা শিখুন"}'::jsonb, '{"en":"Work on the next surah in the list, one ayah at a time, a few minutes a day.","bn":"তালিকার পরের সূরাটি দিনে কয়েক মিনিট করে, একবারে এক আয়াত করে শিখুন।"}'::jsonb, '{"en":"Short surahs are used in every salah, and learning them young builds a lifelong bond with the Quran.","bn":"ছোট সূরাগুলো প্রতি নামাজে লাগে, আর ছোটবেলায় শিখলে কুরআনের সাথে সারা জীবনের সম্পর্ক গড়ে ওঠে।"}'::jsonb, '{"en":"Steady progress and a celebration at the end of each month.","bn":"ধীর কিন্তু নিয়মিত অগ্রগতি, আর প্রতি মাস শেষে একটি উদযাপন।"}'::jsonb, '[{"en":"Tell the meaning or story of the surah first","bn":"আগে সূরার অর্থ বা ঘটনা বলুন"},{"en":"Listen to a clear reciter together","bn":"একসাথে স্পষ্ট কোনো কারির তিলাওয়াত শুনুন"},{"en":"Repeat one ayah at a time through the day","bn":"সারাদিন একটি করে আয়াত বারবার বলুন"},{"en":"Use the surah in salah once it is learned","bn":"শেখা হলে সূরাটি নামাজে পড়ুন"}]'::jsonb, '{}'::jsonb, 'learn', 'monthly', 'shared', 'child', 1461, 4748, 10, 20, '🌟', 'quran', 'isl-short-surahs-list', 'quran', 'any', 'in_review'::lp_review_status, 9105),
  ('isl_wudu_practice', '{"en":"Practise wudu together","bn":"একসাথে অজু অনুশীলন করুন"}'::jsonb, '{}'::jsonb, '{"en":"Wudu comes before salah. Practising it calmly before age seven makes starting salah much easier.","bn":"নামাজের আগে অজু। সাত বছরের আগে শান্তভাবে অনুশীলন করলে নামাজ শুরু করা অনেক সহজ হয়।"}'::jsonb, '{"en":"Your child learns the steps, saves water, and feels proud to be ready to pray.","bn":"সন্তান ধাপগুলো শেখে, পানি বাঁচায়, আর নামাজের জন্য প্রস্তুত হতে পেরে গর্ব বোধ করে।"}'::jsonb, '[{"en":"Do wudu side by side, saying each step aloud","bn":"পাশাপাশি দাঁড়িয়ে প্রতিটি ধাপ মুখে বলে অজু করুন"},{"en":"Let your child lead the steps once they know them","bn":"শেখা হলে সন্তানকে ধাপগুলো বলতে দিন"},{"en":"Praise effort and use only a little water","bn":"চেষ্টার প্রশংসা করুন, আর অল্প পানি ব্যবহার করুন"}]'::jsonb, '{"en":"Use a non-slip mat or stool; wet bathroom floors are slippery for small children.","bn":"পিছলে না যাওয়ার পাপোশ বা টুল ব্যবহার করুন; ভেজা বাথরুমের মেঝে ছোট শিশুর জন্য পিচ্ছিল।"}'::jsonb, 'learn', 'weekly', 'shared', 'child', 1826, 2557, 10, 10, '💧', 'salah', 'isl-wudu-steps', 'quran', 'any', 'in_review'::lp_review_status, 9106),
  ('isl_quran_listening', '{"en":"Quran listening time","bn":"কুরআন শোনার সময়"}'::jsonb, '{"en":"Recite or listen to the Quran together for a few calm minutes.","bn":"কয়েক মিনিট শান্তভাবে একসাথে কুরআন তিলাওয়াত করুন বা শুনুন।"}'::jsonb, '{"en":"Allah says: when the Quran is recited, listen and be silent, so that you may receive mercy (Surah Al-A''raf 7:204).","bn":"আল্লাহ বলেন: যখন কুরআন তিলাওয়াত করা হয়, মনোযোগ দিয়ে শোনো ও চুপ থাকো, যেন তোমাদের প্রতি রহমত করা হয় (সূরা আল-আ''রাফ ৭:২০৪)।"}'::jsonb, '{"en":"A peaceful daily moment, and a memory of the Quran in a loved one''s voice.","bn":"প্রতিদিনের একটি শান্ত মুহূর্ত, আর প্রিয় মানুষের কণ্ঠে কুরআনের স্মৃতি।"}'::jsonb, '[{"en":"Pick a fixed time, such as after Fajr or Maghrib","bn":"ফজর বা মাগরিবের পরের মতো একটি নির্দিষ্ট সময় বাছুন"},{"en":"Recite yourself or play a trusted recording, without the TV on","bn":"নিজে তিলাওয়াত করুন বা নির্ভরযোগ্য রেকর্ডিং চালান, টিভি বন্ধ রেখে"},{"en":"Share the meaning of one ayah","bn":"একটি আয়াতের অর্থ বলুন"}]'::jsonb, '{}'::jsonb, 'family', 'daily', 'any', 'child', 0, 4748, 10, 5, '🎧', 'quran', 'isl-quran-listening-together', 'quran', 'any', 'in_review'::lp_review_status, 9107),
  ('isl_kindness_deed', '{"en":"One kindness deed today","bn":"আজ একটি দয়ার কাজ"}'::jsonb, '{"en":"Help your child do one small act of kindness and talk about how it felt.","bn":"সন্তানকে একটি ছোট দয়ার কাজ করতে সাহায্য করুন, আর কেমন লাগল তা নিয়ে কথা বলুন।"}'::jsonb, '{"en":"The Prophet ﷺ said that a good word is charity, and that even smiling at your brother is charity.","bn":"রাসূলুল্লাহ ﷺ বলেছেন, ভালো কথা সদকা, এমনকি ভাইয়ের দিকে তাকিয়ে হাসাও সদকা।"}'::jsonb, '{"en":"Kindness becomes a habit, and children learn that small deeds matter to Allah.","bn":"দয়া অভ্যাসে পরিণত হয়, আর শিশু শেখে যে ছোট কাজও আল্লাহর কাছে মূল্যবান।"}'::jsonb, '[{"en":"Choose a deed together: share a toy, help Dadi, water a plant, feed a bird, greet a neighbour","bn":"একসাথে একটি কাজ বাছুন: খেলনা ভাগ করা, দাদিকে সাহায্য, গাছে পানি, পাখিকে খাওয়ানো, প্রতিবেশীকে সালাম"},{"en":"Do it without expecting thanks","bn":"ধন্যবাদের আশা না করে কাজটি করুন"},{"en":"At bedtime, ask: how did it feel?","bn":"ঘুমানোর আগে জিজ্ঞেস করুন: কেমন লাগল?"}]'::jsonb, '{}'::jsonb, 'family', 'daily', 'shared', 'child', 1096, 4748, 5, 5, '💝', 'character', 'isl-salam-kind-words', 'sahih_bukhari', 'any', 'in_review'::lp_review_status, 9108)
